COLLDATA("tafsirnoor","ur",[[1256,"§جہا دکی ترغیب کے سلسلہ میں وضاحت\nچنانچہ جہاد کی ترغیب کے سلسلہ میں کتب حدیث میں کثرت کے ساتھ احادیث موجود ہیں۔ بخاری شریف میں ارشادِ نبوی صلی اللہ علیہ وسلم ملاحظہ فرمائیں :” جس شخص کا اللہ تعالیٰ کی ذات اور رسول اکرم صلی اللہ علیہ وسلم کی رسالت پر ایمان ہے آپ کے ساتھ نمازیں باقاعدگی سے ادا کرتا ہے زکاۃ کی ادائیگی میں بھی سستی نہیں کرتا، رمضان المبارک کے روزے رکھتا ہے تو ایسے شخص کے لیے اللہ پاک نے اپنے اوپر فرض کر لیا ہے کہ اس کو جنت میں داخل فرمائے گا خواہ اس نے اللہ تعالیٰ کی راہ میں ہجرت کی ہے یا نہیں۔ صحابہ کرام رضی اللہ عنہم نے عر ض کیا کیا ہم دوسروں کو بھی اس خوشخبری سے شاد کام نہ کریں ؟ آپ صلی اللہ علیہ وسلم نے فرمایا جنت میں میں یک صد درجات ہیں جن کو اللہ پاک نے خصوصیت کے ساتھ مجاہدین فی سبیل اللہ کے لیے تیار کیا ہے۔ ہر دودرجات کے درمیان میں فاصلہ زمین، آسمان کے درمیان فاصلہ کے برابر ہے لہٰذا جب تم اللہ تعالیٰ سے سوال کرو تو جنت الفردوس کا سوال کرو اس لیے کہ جنت الفردوس تمام جنتوں کے درمیان اور سب سے بلند ہے اس جنت کے اوپر اللہ تعالیٰ کا عرش ہے اور وہیں سے جنت کی جانب نہریں پھوٹتی ہیں۔\n(ابن کثیر : 804/1، طبع دارالفکر، صحیح البخاری، صحیح مسلم)\n﴿عَسَى اللّٰهُ اَنْ يَّكُفَّ﴾ ذہن نشین کریں کہ لفظ ”عسٰی“میں وعدہ کا تحقق ہے اللہ تعالیٰ کے کلام میں جب یہ لفظ استعمال ہوگا تو اس کے بعد آنے والی خبر نہایت پختہ ہوگی آپ صلی اللہ علیہ وسلم کا ایمان والوں کو آپ صلی اللہ علیہ وسلم کی معیت میں جہاد کرنے پر رغبت دلانا اس مرکزی نقطہ کے سبب ہے کہ ان کے دلوں میں ایمان کی حلاوت موجود ہے اس کے سبب وہ خود کو جہاد کے لیے تیار کریں گے اور میدان جہاد میں پامردی کے ساتھ دشمن سے جہاد کرتےرہیں گے۔ حقیقت یہ ہے کہ جہاد کی تیاری میں لگے رہنا ایسا عجیب نسخہ ہے جس کے سبب لڑائی عملاً برپا نہ ہو تب بھی ہر گروہ دوسرے گروہ سے خائف رہے گا لیکن عملاً حملہ آور نہ ہوگا۔\n﴿وَاللّٰهُ اَشَدُّ بَاْسًا وَّاَشَدُّ تَنْكِيْلًا۰۰۸۴﴾ تم نے کفار کی طاقت سے خائف نہیں ہوناہے اس کے ساتھ ساتھ تم نے رسول اکر م صلی اللہ علیہ وسلم کی اطاعت سے بھی دست کش نہیں ہونا ہے بلکہ آپ صلی اللہ علیہ وسلم کی ترغیب کے مطابق رواں دواں رہنا ہو گا جب کہ اللہ پاک نے اپنے پیغمبر صلی اللہ علیہ وسلم سے فتح و نصرت کا وعدہ کیا ہوا ہے اور اللہ تعالیٰ قوت اور عبرت ناک سزادینے کے لحاظ سے بہت سخت ہے اور سنت الٰہیہ کا انداز پتہ دے رہا ہے کہ پرہیز گاروں کاانجام بہتر ہے جب تک وہ مامورات پر عمل پیرا رہیں گے منہایت سے بچتے رہیں اور تیاری کے ساتھ ساتھ صبر اور ثابت قدمی کا مظاہرہ کرتے رہیں گےاسباب سے کنارہ کش رہیں گے جن سے ناکامی اور رسوائی سے ہمکنار ہونے کا خدشہ ہو۔ (المراغی : 108,107/5)\nجو شخص خود کو آپ صلی اللہ علیہ وسلم کے ساتھ ملا ئے گا او رجہا دمیں آپ صلی اللہ علیہ وسلم کی مدد کرے گا جب کہ تجھ اکیلے کو اس کاحکم دیا گیا ہے تو اس کی مدد کے سبب اس کو نہ صرف کامیابی میں حصہ عطا ہوگا بلکہ دنیا میں غنیمت ہاتھ آئے گی جب کہ حق کا باطل پر غلبہ ہوگا۔مزید آخرت میں اس کو بہر حال ثواب ملےگا عام ہے کہ دنیا میں اسے کامیابی حاصل ہوئی یا نہیں۔\n﴿وَمَنْ يَّشْفَعْ شَفَاعَةً سَيِّئَةً يَّكُنْ لَّهٗ كِفْلٌ مِّنْهَاؕ﴾ اور جو شخص دشمن کی فوج میں شامل ہوجائے اس کے ساتھ مل کر لڑائی کرے یا ایمان داروں کی مدد سے دست کش ہو جائے تو اس کو اس کے برے عمل کا بدلہ ضرو ر ملے گا۔ دنیا میں رسوائی سے دو چار ہوگا جب کہ آخرت میں عذاب ِالٰہی میں مبتلا ہوگا اس کی برائی پر کسی کی اعانت کرنا شفاعت سئیہ ہے اس کو اس کے سبب جو سزا ملے گی۔ اس کو لفظ ”کفل“سے تعبیر فرمایا گیا ہے کہ وہ محدود ہے۔\n﴿فَمَا لَكُمْ فِي الْمُنٰفِقِيْنَ فِئَتَيْنِ وَاللّٰهُ اَرْكَسَهُمْ بِمَا كَسَبُوْاؕ اَتُرِيْدُوْنَ اَنْ تَهْدُوْا مَنْ اَضَلَّ اللّٰهُؕ وَمَنْ يُّضْلِلِ اللّٰهُ فَلَنْ تَجِدَ لَهٗ سَبِيْلًا۰۰۸۸ وَدُّوْا لَوْ تَكْفُرُوْنَ كَمَا كَفَرُوْا فَتَكُوْنُوْنَ سَوَآءً فَلَا تَتَّخِذُوْا مِنْهُمْ اَوْلِيَآءَ حَتّٰى يُهَاجِرُوْا فِيْ سَبِيْلِ اللّٰهِؕ فَاِنْ تَوَلَّوْا فَخُذُوْهُمْ وَاقْتُلُوْهُمْ حَيْثُ وَجَدْتُّمُوْهُمْ١۪ࣕ وَلَا تَتَّخِذُوْا مِنْهُمْ وَلِيًّا وَّلَا نَصِيْرًاۙ۰۰۸۹ اِلَّا الَّذِيْنَ يَصِلُوْنَ اِلٰى قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُمْ مِّيْثَاقٌ اَوْ جَآءُوْكُمْ حَصِرَتْ صُدُوْرُهُمْ اَنْ يُّقَاتِلُوْكُمْ اَوْ يُقَاتِلُوْا قَوْمَهُمْؕ وَلَوْ شَآءَ اللّٰهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقٰتَلُوْكُمْۚ فَاِنِ اعْتَزَلُوْكُمْ فَلَمْ يُقَاتِلُوْكُمْ وَاَلْقَوْا اِلَيْكُمُ السَّلَمَۙ فَمَا جَعَلَ اللّٰهُ لَكُمْ عَلَيْهِمْ سَبِيْلًا۰۰۹۰ سَتَجِدُوْنَ اٰخَرِيْنَ يُرِيْدُوْنَ اَنْ يَّاْمَنُوْكُمْ وَيَاْمَنُوْا قَوْمَهُمْؕ كُلَّمَا رُدُّوْۤا اِلَى الْفِتْنَةِ اُرْكِسُوْا فِيْهَاۚ فَاِنْ لَّمْ يَعْتَزِلُوْكُمْ۠ وَيُلْقُوْۤا اِلَيْكُمُ السَّلَمَ وَيَكُفُّوْۤا اَيْدِيَهُمْ فَخُذُوْهُمْ وَاقْتُلُوْهُمْ حَيْثُ ثَقِفْتُمُوْهُمْ۠ؕ وَاُولٰٓىِٕكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطٰنًا مُّبِيْنًاࣖ۰۰۹۱﴾\nپھر تمہیں کیا ہوا ہے کہ منافقوں کے بارے میں دو گروہوں میں بٹ گئے ہو؟ حالانکہ اللہ نے ان کے اعمال کی وجہ سے انہیں الٹا کر دیا ہے۔ کیا تم چاہتے ہو کہ ان لوگوں کو ہدایت دو جنھیں اللہ نے گمراہ کیا ہو؟ اور جسے اللہ گمراہ کرے، پھر اس کے لیے آپ ہرگز کوئی راستہ نہیں پائیں گے⟦88⟧ وہ چاہتے ہیں کہ تم بھی کفر کرو جس طرح کہ انہوں نے کفر کیا، پھر تم ان کے برابر ہو جائو، چنانچہ تم ان میں سے کسی کو دوست نہ بنائو یہاں تک کہ وہ اللہ کی راہ میں ہجرت کریں، پھر اگر وہ (دین سے) منہ موڑیں تو تم انہیں پکڑو اور انہیں جہاں پائو قتل کر دو۔ اور ان میں سے کسی کو اپنا دوست اور مدد گار نہ بنائو⟦89⟧ مگر وہ لوگ (اس حکم سے مستثنیٰ ہیں) جو اس قوم سے تعلق رکھتے ہوں جن سے تمہارا معاہدہ ہو چکا ہے یا (وہ منافق بھی مستثنیٰ ہیں) جو تمہارے پاس اس حالت میں آئیں کہ وہ لڑائی سے بیزار ہوں نہ تم سے لڑنا چاہتے ہوں اور نہ اپنی قوم سے۔ اور اگر اللہ چاہتا تو انہیں تم پر مسلط کر دیتا، پھر وہ تم سے یقینا لڑتے، لہٰذا اگر وہ تم سے کنارہ کشی اختیار کر لیں اور تمہارے ساتھ لڑنے سے باز رہیں، اور تمہاری طرف صلح اور امن کا ہاتھ بڑھائیں تو اللہ نے تمہارے لیے کوئی گنجائش نہیں رکھی کہ تم ان سے لڑائی کرو⟦90⟧ تمہیں ایک اور قسم کے منافق ملیں گے جو چاہتے ہیں کہ تم سے بھی امن میں رہیں اور اپنی قوم سے بھی، مگر جب کبھی وہ فتنے کا موقع پاتے ہیں تو اس میں کود پڑتے ہیں، چنانچہ ایسے لوگ اگر تم سے مقابلہ کرنے سے باز نہ آئیں اور تمہیں صلح اور امن کی پیشکش نہ کریں اور لڑائی سے اپنے ہاتھ نہ روکیں تو تم انہیں جہاں کہیں پائو، پکڑ کر قتل کر دو۔ یہی وہ لوگ ہیں جن پر (ہاتھ اٹھانے کے لیے) ہم نے تمہیں کھلی اجازت دے دی ہے⟦91⟧"],[1257,"§اُحد سے واپس آجانے والے منافقوں کے بارے میں صحابہ کرام رضی اللہ عنہم کا اختلاف\nمنافقوں کے بارے میں اختلاف کرتے ہوئے مومنوں نے جو دو قول اختیار کر لیے تھے اللہ تعالیٰ نے اس روش کی تردید فرمائی۔ اس آیت کے سبب نزول کے بارے میں اختلاف ہے، امام احمد رحمہ اللہ نے سیّدنا زید بن ثابت رضی اللہ عنہ کی روایت بیان کی ہے کہ رسو ل اللہ صلی اللہ علیہ وسلم جب جنگ احد کے لیے نکلے تھے، اس وقت آپ صلی اللہ علیہ وسلم کے ساتھ نکلنے والوں میں سے کچھ لوگ واپس آگئے تھے، تو ان کے بارے میں صحابہ کرام رضی اللہ عنہم دو گروہوں میں تقسیم ہو گئے تھے۔ ایک گروہ کا کہنا تھا کہ ہمیں انہیں قتل کر دینا چاہیے جب کہ دوسرے گروہ کی رائے یہ تھی کہ انہیں قتل نہیں کرنا چاہیے، لہٰذا اس موقع پر اللہ تعالیٰ نے یہ آیت ِ کریمہ نازل فرمائی:﴿فَمَا لَكُمْ فِي الْمُنٰفِقِيْنَ فِئَتَيْنِ﴾ ’’تو کیا سبب ہے کہ منافقوں کے بارے میں تم دو گروہ ہو رہے ہو ؟‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:«إِنَّهَا طَيْبَةُ وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ» ’’یہ شہر طیبہ ہے، یہ میل کچیل کو اسی طرح دور کردیتا ہے جس طرح آگ چاندی کے میل کچیل کو دور کر دیتی ہے۔ ‘‘(مسند أحمد)\nعوفی رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ یہ آیت مکہ کے کچھ لوگوں کے بارے میں نازل ہوئی ہے جنہوں نے اسلام قبول کر لیا تھا لیکن وہ مشرکوں کو غالب کرنا چاہتے تھے، وہ اپنی کسی ضرورت سے مکہ سے نکلے تو اس وقت کہنے لگے کہ اگر اصحاب محمد صلی اللہ علیہ وسلم سے ہماری ملاقات ہو گئی تو کوئی حرج نہیں ہے۔ مومنوں کو جب ان کے بارے میں معلوم ہوا کہ یہ مکہ سے روانہ ہو چکے ہیں، چنانچہ ان میں سے ایک جماعت یہ کہنے لگی کہ ان نامرادوں کے پیچھے جائو اور انہیں قتل کردو، یہ تمہارے دشمن کو تم پرغالب کرنا چاہتے ہیں۔ مومنوں کی ایک دوسری جماعت نے کہا کہ سبحان اللہ ! کیا تم ایسے لوگوں کو قتل کرنا چاہتے ہو جو تمہاری ہی طرح مسلمان ہیں ؟ محض اس وجہ سے قتل کرنا چاہتے ہو کہ انہوں نے ہجرت نہیں کی اور اپنے گھروں کو نہیں چھوڑا اور اس وجہ سے تم ان کے خونوں اور مالوں کو حلال سمجھنے لگے ہو؟\nاس طرح مسلمان دو جماعتوں میں تقسیم ہو گئے، حالانکہ رسول اللہ صلی اللہ علیہ وسلم بھی ان کے مابین موجود تھے اور آپ صلی اللہ علیہ وسلم نے (ابھی تک) ان میں سے کسی کو کسی بات سے روکا بھی نہ تھا، تب اسی موقع پر اللہ تعالیٰ نے اس آیت کریمہ کو نازل فرمایا:﴿فَمَا لَكُمْ فِي الْمُنٰفِقِيْنَ فِئَتَيْنِ﴾ ’’تو کیا سبب ہے کہ تم منافقوں کے بارے میں دو گروہ ہو رہے ہو ؟‘‘(تفسیرالطبری : 263/5) اسے امام ابن ابو حاتم رحمہ اللہ نے بھی روایت کیا ہے۔ (تفسیرابن أبی حاتم:1023/3)\n﴿وَاللّٰهُ اَرْكَسَهُمْ بِمَا كَسَبُوْاؕ﴾ ’’حالانکہ اللہ تعالیٰ نے ان کو ان کے کرتوتوں کے سبب اوندھا کر دیا ہے۔ ‘‘ یعنی انہیں غلطی میں مبتلا کر دیا ہے۔ سیّدنا ابن عباس رضی اللہ عنہما فرماتے ہیں: ﴿ اَرْكَسَهُمْ ﴾ کے معنی أَوْقَعَهُمْ کہ انہیں مبتلا کر دیا ہے، الجھا دیا ہے۔ (تفسیرالطبری : 266/5)﴿بِمَا كَسَبُوْاؕ﴾ ’’ان کے اعمال کی وجہ سے۔ ‘‘ یعنی اس لے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی نافرمانی اور مخالفت کی اورباطل کی اتباع کی۔﴿اَتُرِيْدُوْنَ اَنْ تَهْدُوْا مَنْ اَضَلَّ اللّٰهُؕ وَمَنْ يُّضْلِلِ اللّٰهُ فَلَنْ تَجِدَ لَهٗ سَبِيْلًا۰۰۸۸﴾ ’’کیا تم چاہتے ہو کہ ان لوگوں کو ہدایت دو جنھیں اللہ تعالیٰ نے گمراہ کر دیا ہو ؟ اور جس کو اللہ تعالیٰ گمراہ کردے، پھر آپ صلی اللہ علیہ وسلم اس کے لیے کبھی بھی رستہ نہیں پائیںگے۔ ‘‘ مطلب یہ ہے کہ اسے ہدایت کا رستہ نہیں مل سکتا اور وہ کبھی بھی ہدایت حاصل نہیں کر سکتا۔\nاور ارشادِ باری تعالیٰ :﴿وَدُّوْا لَوْ تَكْفُرُوْنَ كَمَا كَفَرُوْا فَتَكُوْنُوْنَ سَوَآءً﴾ ’’وہ چاہتے ہیں کہ جس طرح وہ خود کافر ہیں (اسی طرح) تم بھی کافر ہو کر (سب) برابر ہو جائو۔‘‘ یعنی وہ تمہارے لیے بھی گمراہی کو پسند کرتے ہیں تاکہ تم اور وہ سب بھی گمراہی میں برابرہو جائو اور یہ اس لیے کہ تم سے شدید عداوت اور بغض رکھتے ہیں، اس لیے اللہ تعالیٰ نے فرمایا ہے :﴿فَلَا تَتَّخِذُوْا مِنْهُمْ اَوْلِيَآءَ حَتّٰى يُهَاجِرُوْا فِيْ سَبِيْلِ اللّٰهِؕ﴾ ’’پس جب تک وہ اللہ تعالیٰ کی راہ میں وطن نہ چھوڑ جائیں، لہٰذا تم ان میں سے کسی کو دوست نہ بنانا۔‘‘ ﴿فَاِنْ تَوَلَّوْا﴾ کے معنی عوفی رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما سے یہ بیان کیے ہیں کہ اگر وہ ہجرت کو ترک کر دیں۔ اور امام سدی رحمہ اللہ نے یہ بیان کیے ہیں کہ اگر وہ کفر کا اظہا رکریں۔\n(تفسیر ابن أبی حاتم : 1026/3)"],[1258,"§لڑائی سے مستثنیٰ کیے جانے والے\nپھر اللہ تعالیٰ نے لڑائی سے مستثنیٰ کیے جانے والوں کا ذکر فرمایا:﴿اِلَّا الَّذِيْنَ يَصِلُوْنَ اِلٰى قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُمْ مِّيْثَاقٌ﴾ ’’مگر جو لوگ ایسے لوگوں سے جاملے ہوں جن کا تم سے (صلح کا) عہد ہو۔ ‘‘ یعنی جو ایسے لوگوں سے جاملیں جن کا تم سے صلح یا ذمہ کا عہد ہو تو ان سے معاملہ بھی انہی کی طرح کرو۔ یہ سدی، ابن زید اور ابن جریر رحمہم اللہ کا قول ہے۔ (تفسیرالطبری : 268/5)\nصحیح بخاری میں صلح حدیبیہ کے قصے میں ہے کہ جس نے چاہا وہ قریش کے ساتھ صلح و عہد میں داخل ہو گیا اور جس نے چاہا وہ محمد صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابۂ کرام رضی اللہ عنہم کے ساتھ صلح اور عہد میں داخل ہو گیا۔(ماخوذ از صحیح البخاری : 2731 و مسند أحمد) سیّدنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ اس حکم کو اس آیت نے منسوخ کر دیا تھا :﴿فَاِذَا انْسَلَخَ الْاَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِيْنَ حَيْثُ وَجَدْتُّمُوْهُمْ﴾ (التوبۃ:5) ’’پھر جب حرمت کے مہینے گزر جائیں تو مشرکوں کو جہاں پائو قتل کردو۔‘‘ (تفسیر ابن أبی حاتم : 1027/3)\n﴿وَلَوْ شَآءَ اللّٰهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقٰتَلُوْكُمْۚ﴾ ’’اور اگر اللہ تعالیٰ چاہتا تو ان کو تم پر غالب کر دیتا تو وہ تم سے ضرور لڑتے۔‘‘ لیکن اپنے لطف و کرم سے اس نے تمہیں تم سے دور رکھا۔ ﴿فَاِنِ اعْتَزَلُوْكُمْ فَلَمْ يُقَاتِلُوْكُمْ وَاَلْقَوْا اِلَيْكُمُ السَّلَمَۙ﴾ ’’پھر اگر وہ تم سے (جنگ کرنے سے) کنارہ کشی کریں اور لڑیں نہیں اور تمہاری طرف صلح (کا پیغام) بھیجیں۔‘‘ یعنی پھر صلح کر لینی چاہیں ﴿فَمَا جَعَلَ اللّٰهُ لَكُمْ عَلَيْهِمْ سَبِيْلًا۰۰۹۰﴾ ’’تو اللہ تعالیٰ نے تمہارے لیے کوئی راہ نہیں رکھی کہ ایسے لوگوں کے خلاف جنگ کرو۔ ‘‘ یعنی جب تک ان کا حال اس طرح ہے تو تمہیں ان سے لڑنے کی اجازت نہیں ہے، یہ بنی ہاشم کے ان لوگوں کی طرح ہیں جو بدر کے دن مشرکوں کے ساتھ نکلے تھے اور وہ جنگ میں شریک تو ہوئے لیکن وہ اسے ناپسند کرتے تھے : مثلاً:حضر ت عباس رضی اللہ عنہما وغیرہ، اسی لیے اس دن نبی اکرم صلی اللہ علیہ وسلم نے سیّدنا عباس رضی اللہ عنہ کے قتل سے منع فرمایا تھا اور قید کرنے کا حکم دیا تھا۔ (المستدرک للحاکم :4988)\n﴿سَتَجِدُوْنَ اٰخَرِيْنَ يُرِيْدُوْنَ اَنْ يَّاْمَنُوْكُمْ وَيَاْمَنُوْا قَوْمَهُمْؕ﴾ ’’عنقریب کچھ اور لوگ ایسے بھی پائو گے جو یہ چاہتے ہیں کہ تم سے بھی امن میںرہیں اور اپنی قوم سے بھی امن میں رہیں۔‘‘ یہ لوگ ظاہری صورت میں تو ان لوگوں ہی کی طرح ہیں جن کا پہلے ذکر ہوا لیکن یہ نیت کے اعتبار سے ان سے مختلف ہیں کیوں کہ یہ منافق ہیں، نبی اکرم صلی اللہ علیہ وسلم اور صحابۂ کرام رضی اللہ عنہم کے سامنے تو اسلام کا اظہا رکرتے تاکہ اپنے خونوں، مالوں اور اولادوں کو بچاسکیں مگر خفیہ طور پر یہ کفار سے دوستی رکھتے ہیں اور ان کے ساتھ مل کر وہی عبادت کرتے ہیں جو وہ عبادت کرتے ہیں تاکہ ان کے پاس ما ٔمون ہو جائیں اور خفیہ طور پر بھی یہ انہی کے ساتھ ہیں جیسا کہ اللہ تعالیٰ نے فرمایا ہے :﴿وَاِذَا خَلَوْا اِلٰى شَيٰطِيْنِهِمْۙ قَالُوْۤا اِنَّا مَعَكُمْۙ﴾ (البقرۃ:14) ’’اور وہ جب اپنے شیطانوں کے پاس تنہا ہوتے ہیں تو (ان سے) کہتے ہیں کہ ہم تمہارے ساتھ ہیں۔ ‘‘ اور یہاں یہ فرمایا: ﴿كُلَّمَا رُدُّوْۤا اِلَى الْفِتْنَةِ اُرْكِسُوْا فِيْهَاۚ﴾ ’’(لیکن) جب کبھی فتنہ انگیزی کو بلائے جائیں تو اس میں اوندھے منہ گرپڑیں۔‘‘ یعنی منہمک ہوجائیں۔ سدی رحمہ اللہ کہتے ہیں کہ یہاں فتنے سے مراد شرک ہے۔ (تفسیر ابن أبی حاتم : 1029/3)\nابن جریر رحمہ اللہ نے مجاہد رحمہ اللہ سے روایت کیا ہے کہ یہ آیت مکہ کے کچھ لوگوں کے بارے میں نازل ہوئی ہے وہ جب نبی اکرم صلی اللہ علیہ وسلم کے پاس آتے تو ریاکاری کی وجہ سے آپ صلی اللہ علیہ وسلم کو سلام کہتے اور جب قریش کے پاس واپس جاتے تو اپنے بتوں کے سامنے اوندھے منہ گرجاتے اور اس طرز عمل سے وہ یہ چاہتے تھے کہ اپنے آپ کو دونوں کے ہاں محفوظ کر لیں تو اس وجہ سے ان سے لڑنے کا حکم دیا گیا، بشرطیکہ وہ کنارہ کشی اختیار نہ کریں اور صلح نہ کریں۔(تفسیر الطبری : 273/5) اسی لیے اللہ تعالیٰ نے فرمایا:﴿فَاِنْ لَّمْ يَعْتَزِلُوْكُمْ۠ وَيُلْقُوْۤا اِلَيْكُمُ السَّلَمَ﴾ ’’پھر اگر تم سے (لڑنے سے) کنارہ کشی نہ کریں اور نہ تمہاری طرف (پیغام) صلح بھیجیں۔‘‘ یعنی صلح کا معاہدہ نہ کر لیں ﴿وَيَكُفُّوْۤا اَيْدِيَهُمْ﴾ ’’اور نہ اپنے ہاتھوں کو روکیں۔‘‘ یعنی جنگ سے ﴿فَخُذُوْهُمْ ﴾ ’’تو ان کو پکڑ لو۔‘‘ یعنی قیدی بنا لو۔ ﴿وَاقْتُلُوْهُمْ حَيْثُ ثَقِفْتُمُوْهُمْ۠ؕ﴾ ’’اور جہاں ان کو پائو قتل کر دو۔ ‘‘﴿وَاُولٰٓىِٕكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطٰنًا مُّبِيْنًاࣖ۰۰۹۱﴾ ’’اوران لوگوںکے مقابلے میں ہم نے تمہارے لیے حجت صریح مقرر کر دی ہے۔ ‘‘ یعنی روشن اور واضح دلیل۔"],[1259,"§منافقوں کے بارے میں دو گروہ\nاس آیت کا شان ِ نزول درج ذیل حدیث سے واضح ہوتا ہے :\n’’زید رضی اللہ عنہ بن ثابت کہتے ہیں کہ : جب نبی اکرم صلی اللہ علیہ وسلم اُحد کی طرف نکلے تو کچھ لوگ (منافقین) آپ صلی اللہ علیہ وسلم کو چھوڑ کر مدینہ واپس آگئے۔ ان واپس ہونے والوں کے بارے میں صحابہ رضی اللہ عنہم کے دو گروہ ہو گئے۔ ایک کہتا تھا کہ ہم ان سے (بھی) لڑائی کریں گے اور دوسرا کہتا تھا کہ ہم ان سے لڑائی نہ کریں گے۔ اس وقت یہ آیت نازل ہوئی۔ ‘‘\n(صحیح البخاری، صحیح مسلم)"],[1260,"§مدینہ کے پاس کے منافقین اور ان کی اقسام\nیہاں اس بات کی وضاحت ضروری معلوم ہوتی ہے کہ منافقوں کی ایک قسم ایسی بھی تھی جو مدینہ کے اردگرد پھیلے ہوئے قبائل سے تعلق رکھتے تھے۔ یہ لوگ مسلمانوں سے خیر خواہی اور محبت کا اظہار ضرور کرتے تھے مگر عملی طور پر اپنے ہم وطن کافروں کاساتھ دیتے تھے یا دینے پر مجبور تھے ان کے لیے معیار یہ مقرر کیا گیا کہ اگر وہ ہجرت کرکے تمہارے پاس مدینہ آجائیں اور تمہارے ساتھ شامل ہو جائیں تو اس صورت میں تم انہیں سچا بھی سمجھو اور اپنا ہمدرد بھی۔ اور اگر وہ اسلام کی خاطر اپنا گھر بار چھوڑنے کی قربانی دینے پر تیار نہیں حالانکہ وہ ایسا کر سکتے ہیں تو تم ان پر ہرگز اعتماد نہ کرو نہ انہیں اپنا دوست بنائو اور نہ سمجھو اور اگر ایسے لوگ کافروں کے ساتھ تمہارے خلاف صف بستہ ہو جاتے ہیں تو انہیں قتل کرنے سے ہرگز دریغ نہ کرو۔"],[1261,"§کن لوگوں سے جنگ جائز نہیں\nالبتہ اس حکم قتل سے دو قسم کے لوگ مستثنیٰ ہیں: ایک وہ لوگ جو کسی ایسی قوم میں چلے جائیں جن سے تمہارا معاہدہ ہو چکا ہے کہ وہ اتنی مدت تک مسلمانوں سے جنگ نہ کریں گے تو ان کا تعاقب نہیں کیا جائے گا (جیسا کہ صلح حدیبیہ کے دوران کفار مکہ سے معاہد ہ ہوا تھا) یا ایسے منافق بھی مستثنیٰ ہیں جو فی الحقیقت غیر جانبدار رہنا چاہتے ہیں۔ نہ وہ اپنی قوم سے تمہارے ساتھ مل کر لڑنا چاہتے ہیں اور نہ ان کے ساتھ مل کر تم سے لڑنا چاہتے ہیں۔ خواہ وہ اپنی قوم کے ساتھ مل کر آہی گئے ہوں۔ مگر مسلمانوں کے خلاف لڑنے سے دل میں تنگی محسوس کر رہے ہوں جیسے میدان بدر میں مشرکین کے ساتھ سیدنا عباس رضی اللہ عنہ اور بنی ہاشم کے کئی لوگ آتو گئے تھے مگر لڑائی کے وقت علیحدہ رہے۔"],[1262,"§بدترین منافق\nایسے منافق بدترین قسم کے منافق ہیں جوڈھنڈورا تو اپنی امن پسندی کا پیٹیں اور جب دائو لگ جائے تو اسلام دشمنی میں کوئی کسر اُٹھا نہ رکھیں۔ ان کی امن پسندی کی تین ہی صورتیں ممکن ہیں: ایک یہ کہ مسلمانوں سے صلح کر لیں۔ دوسرے یہ کہ لشکر کفار میں شامل نہ ہوں۔ اور تیسرے یہ کہ اگر انہیں مجبورًا شامل ہونا ہی پڑے تو پھر اپنے ہاتھ روکے رکھیں یعنی عملاً لڑائی میں شامل نہ ہوں۔ اور اگر یہ تینوں باتیں نہ پائی جائیں تو اس کا مطلب یہ ہوا کہ ان کی نیت میں فتور ہے اور وہ امن پسندی کی آڑ میں دھوکہ دے کر مسلمانوں سے انتقام لینا چاہتے ہیں لہٰذا ایسے منافقوں کا علاج یہ ہے کہ جب بھی موقع ملے سب سے پہلے انہیں قتل کر کے ختم کرو۔ دوسرے کا فروں سے جنگ بعد میں کرو۔\nیہ نفی، نہی کے معنی میں ہے جو حرمت کی متقاضی ہے یعنی ایک مومن کا دوسرے مومن کو قتل کرنا ممنوع اور حرام ہے جیسے : ﴿وَمَا كَانَ لَكُمْ اَنْ تُؤْذُوْا رَسُوْلَ اللّٰهِ﴾ (الاحزاب:53) ’’تمہارے یہ لائق نہیں ہے کہ تم اللہ تعالیٰ کے رسول صلی اللہ علیہ وسلم کو ایذاء پہنچائو۔‘‘ یعنی حرام ہے۔\n﴿فَاِنْ لَّمْ يَعْتَزِلُوْكُمْ۠ وَيُلْقُوْۤا اِلَيْكُمُ السَّلَمَ﴾ اگر وہ تمہارے ساتھ لڑائی سے الگ نہ ہوں اور تمہارے مسلک کی اطاعت نہ کریں اور عملاً تمہارے ساتھ لڑائی سے باز نہ آئیں تو پھر انہیں پکڑو اور جہاں وہ مل جائیں انہیں موت کے گھاٹ اتاردو۔ ہم نے تمہیں ایسے لوگوں پر غلبہ عطا کیا ہے۔ مقصود یہ ہے کہ تمہارے پاس ان کو پکڑنے اور قتل کرنے کی کھلی دلیل ہے ان آیات کا مفہوم آپ نے معلوم کرلیا لیکن اس کے ساتھ ساتھ آپ کے علم میں ہے کہ مشرکین کے ساتھ جنگ کرنے سے خود کو روکنا سورۂ براء ۃ کی آیات کی روشنی میں منسوخ ہے۔ البتہ خلیفہ وقت کے لیے اجازت ہے کہ وہ ضرورت کے وقت ا س نظام پر عمل پیرا ہو جو شخص بھی اس نظام پر کاربند رہے گا وہ ناکام نہ ہوگا جب کہ وہ جزیرۃ العرب کے باہر ہے۔ واضح رہے کہ جزیرۃ العرب میں کبھی دو دین اکٹھے نہیں ہو سکتے۔ (ایسر التفاسیر : 439,438,4371)\nذہن نشین فرمائیں کہ امام بخاری رحمہ اللہ نے کتاب التفسیر،ص:951 پر اس آیت مبارکہ کے ساتھ باب کا انعقاد کیاہے۔\n﴿فَمَا لَكُمْ فِي الْمُنٰفِقِيْنَ فِئَتَيْنِ وَاللّٰهُ اَرْكَسَهُمْ﴾ اس عنوان کے نیچے زید بن ثابت رضی اللہ عنہ سے ایک حدیث لائے ہیں جس کا مفہوم یہ ہے کہ صحابہ کرام رضی اللہ عنہم میں سے کچھ لوگ اُحد سے واپس لوٹے چنانچہ واپس لوٹنے والوں کے بارے میں صحابہ کرام رضی اللہ عنہم دو حصوں میں بٹ گئے ایک فریق ان کو قتل کرنے کا قائل تھا اور دوسرا فریق قتل کرنے کا قائل تھا اس اختلاف پر یہ آیت مبارکہ نازل ہوئی نیز آپ صلی اللہ علیہ وسلم نےمدینہ کے بارے میں فرمایا: کہ مدینہ پاک ہے۔ میلے کچیلے لوگوں کو نکال دیتا ہے جیسا کہ آگ میں رکھنے سے چاندی کی میل کچیل دور ہو جاتی ہے۔ حافظ ابن حجر رحمہ اللہ فرماتے ہیں احد مقام سے جو لوگ واپس آئے ان سے مقصود عبداللہ بن ابی رئیس المنافقین اور اس کے رفقاء تھے جو تین صد ساتھیوں کو لے کر واپس آگیا۔\n﴿وَمَا كَانَ لِمُؤْمِنٍ اَنْ يَّقْتُلَ مُؤْمِنًا اِلَّا خَطَـًٔاۚ وَمَنْ قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيْرُ رَقَبَةٍ مُّؤْمِنَةٍ وَّدِيَةٌ مُّسَلَّمَةٌ اِلٰۤى اَهْلِهٖۤ اِلَّاۤ اَنْ يَّصَّدَّقُوْاؕ فَاِنْ كَانَ مِنْ قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيْرُ رَقَبَةٍ مُّؤْمِنَةٍؕ وَاِنْ كَانَ مِنْ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُمْ مِّيْثَاقٌ فَدِيَةٌ مُّسَلَّمَةٌ اِلٰۤى اَهْلِهٖ وَتَحْرِيْرُ رَقَبَةٍ مُّؤْمِنَةٍۚ فَمَنْ لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ١ٞؗ تَوْبَةً مِّنَ اللّٰهِؕ وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًا۰۰۹۲ وَمَنْ يَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهٗ جَهَنَّمُ خٰلِدًا فِيْهَا وَغَضِبَ اللّٰهُ عَلَيْهِ وَلَعَنَهٗ وَاَعَدَّ لَهٗ عَذَابًا عَظِيْمًا۰۰۹۳﴾\nاور کسی مومن کے لیے جائز نہیں کہ وہ دوسرے مومن کو قتل کرے، مگر غلطی سے (ہو جائے تو اور بات ہے) اور جو شخص کسی مومن کو غلطی سے قتل کر دے، اس پر ایک مسلمان غلام آزاد کرنا اور مقتول کے رشتے داروں کو خون بہا ادا کرنا لازم ہے۔ ہاں اگر وہ لوگ معاف کر دیں (تو اور بات ہے۔) پھر اگر وہ مقتول ایسی قوم میں سے ہو جو تمہاری دشمن ہو جبکہ وہ خود مومن ہو تو ایک مسلمان غلام آزاد کرنا لازم ہے۔ اور اگر وہ ایسی قوم میں سے ہو کہ تمہارے اور ان کے درمیان معاہدہ ہو چکا ہو تو اس کے وارثوں کو خون بہا دیا جائے گا اور ایک مسلمان غلام آزاد کرنا ہو گا، پھر جو شخص غلام آزاد کرنے کی طاقت نہ رکھتا ہو وہ دو ماہ لگاتار روزے رکھے، یہ (کفارہ) اللہ کی طرف سے توبہ (قبول کرنے کا ذریعہ) ہے۔ اور اللہ خوب جاننے والا، بہت حکمت والا ہے⟦92⟧ اور جو شخص کسی مومن کو جان بوجھ کر قتل کر دے اس کی سزا جہنم ہے، وہ اس میں ہمیشہ رہے گا اور اس پر اللہ کا غضب اور اس کی لعنت ہو گی اور اللہ نے اس کے لیے بہت بڑا عذاب تیار کر رکھا ہے⟦93⟧"],[1263,"§مومن کے قتل خطا کے بارے میں حکم\nاللہ تعالیٰ فرماتا ہے کہ کسی مومن کے لیے یہ جائز نہیں ہے کہ وہ اپنے مومن بھائی کو کسی طرح بھی قتل کرے جیسا کہ صحیحین میں سیّدنا ابن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی ایسے مسلمان آدمی کا جو یہ گواہی دیتا ہےہو کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور میں اللہ کا رسول صلی اللہ علیہ وسلم ہوں، تین میں سے کسی ایک صورت کے سوا خون حلال نہیں ہے :(1)جان کے بدلے جان (2)شادی شدہ بدکار اور (3)اپنے دین اسلام سے ارتداد کرکے مسلمانوں کی جماعت سے علیحدگی اختیار کرنے والا۔‘‘(صحیح البخاری: 6878 و صحیح مسلم :1676)\nپھر جب ان تین میں سے ایک کوئی ایک صورت وقوع پذیر ہو تو رعایا میں سے کسی کو اس کے قتل کرنے کی اجازت نہیں ہے بلکہ یہ امام یا اس کے نائب کا اختیار ہے۔ ارشادِ باری تعالیٰ ﴿اِلَّا خَطَـًٔا١ۚ﴾ ’’مگر غلطی سے۔ ‘‘یہ استثنامنقطع ہے۔\nاس آیت کے سبب نزول کے بار ے میں اختلاف ہے۔ امام مجاہد رحمہ اللہ وغیرہ نے فرمایا ہے کہ یہ آیت عَيَّاش بن ابوربیعہ کے بارے میں نازل ہوئی ہے جو ابوجہل کا اپنی ماں اسماء بنت سلمہ بن مُخَرَّبَه کی طرف سے بھائی تھا۔ اس نے ایک ایسے شخص کو قتل کر دیا تھا جو ابو جہل کے ساتھ مل کر انہیں اسلام قبول کرنے کی وجہ سے تکلیفیں دیا کرتا تھا اور وہ حارث بن یزید عامری تھا، عیاش نے اس کے لیے اپنے دل میں برے ارادے کو چھپائے رکھا مگر وہ مسلمان ہو گیا اور اس نے ہجرت بھی کر لی لیکن عیاش کو یہ معلوم نہ ہوسکا۔ اور اس نے فتح مکہ کے دن جب اسے دیکھا تو سمجھا کہ شاید وہ ابھی تک اپنے دین پر ہے، اس لیے اس نے حملہ کرکے اسے قتل کر دیا،تو اللہ تعالیٰ نے اس موقع پر اس آیت کریمہ کو نازل فرما دیا۔\n(ملخص از تفسیر الطبری: 276/5 وتفسیر ابن أبی حاتم:1031/3)\nعبدالرحمٰن بن زید بن اسلم کہتے ہیں کہ یہ آیت سیّدنا ابو درداء رضی اللہ عنہ کے بارے میں نازل ہوئی ہے کیوں کہ اُنھوں نے ایک ایسے شخص کو قتل کردیاتھا جس نے اس وقت کلمہ پڑھ لیا تھا جب انہوں نے اس پر تلوار کو اُٹھا یا،انہوں نے اس واقعے کا ذکر جب نبی اکرم صلی اللہ علیہ وسلم کے پاس کیا تو کہا کہ اس نے محض اپنی جان بچانے کی خاطر کلمہ پڑھا تھا تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: «أَلَا شَقَقْتَ عَنْ قَلْبِهٖ؟»’’کیا تم نے اس کے دل کو چیر (کر دیکھ) لیا تھا ؟ ‘‘(ملخص از تفسیر الطبری : 278/5 لیکن یہ روایت مرسل ہے۔)لیکن (صحیح بخاری و مسلم کی) حدیث میں یہ قصہ سیّدنا ابودراء رضی اللہ عنہ سے نہیں بلکہ کسی اور صحابی سے منسوب ہے۔ (یعنی سیّدنا اُسامہ بن زید رضی اللہ عنہما۔ دیکھیے : صحیح البخاری : 4269 و صحیح مسلم :96)\nاور فرمانِ الٰہی ہے :﴿وَمَنْ قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيْرُ رَقَبَةٍ مُّؤْمِنَةٍ وَّدِيَةٌ مُّسَلَّمَةٌ اِلٰۤى اَهْلِهٖۤ﴾ ’’اور جو غلطی سے بھی مومن کو مار ڈالے تو (ایک تو) ایک مسلمان غلام آزاد کر دے اور (دوسرے) مقتول کے وارثوں کو خون بہا دے۔‘‘ قتلِ خطا میں یہ دونوں چیزیں واجب ہیں: ایک تو اس عظیم گناہ کا کفارہ ہے، خواہ بغیر ارادے کے غلطی ہی سے سرزد ہو ا ہو اور اس کے لیے شرط یہ ہے کہ ایک مومن (غلام) کی گردن کو آزاد کیا جائے، کافر کی گردن کو آزاد کرکے بھی عہدہ برآنہ ہوسکے گا۔\nامام احمد رحمہ اللہ نے ایک انصاری صحابی رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ وہ ایک سیاہ رنگ کی لونڈی کولے کر آیا اور عرض کرنے لگا: اے اللہ کے رسول صلی اللہ علیہ وسلم ! مجھ پر ایک مومن گردن کی آزادی واجب ہے، اگر آپ صلی اللہ علیہ وسلم اس لونڈی کو مومن سمجھتے ہیں تو میں اسے آزاد کر دیتا ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: ’’کیا تو گواہی دیتی ہے کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں ؟ اس نے کہا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تو اس بات کی گواہی دیتی ہے کہ میں اللہ تعالیٰ کارسول صلی اللہ علیہ وسلم ہوں ؟ اس نے عرض کی : جی ہاں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تو مرنے کے بعد دوبارہ اُٹھنے پر ایمان رکھتی ہے ؟ اس نے عرض کی : جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: اسے آزاد کر دو۔‘‘(مسند أحمد، صحیح مسلم :537) اس حدیث کی سند صحیح ہے اور اگر صحابی رضی اللہ عنہ کا نام مذکور نہیں ہے تو اس میں کوئی حرج نہیں۔\n﴿وَّدِيَةٌ مُّسَلَّمَةٌ اِلٰۤى اَهْلِهٖۤ﴾ ’’اور (دوسرے) مقتول کے وارثوں کو خون بہادے۔‘‘یہ دوسرا واجب ہے جو قاتل کو مقتول کے وارثوں کو ان کے عزیز کے فوت ہوجانے کی وجہ سے ادا کرنا پڑتا ہے۔ اور واجب ہے کہ قتل خطا کی دیت میں پانچ قسم کے اونٹ ادا کیے جائیں۔(مسند أحمد) جیسا کہ امام احمد رحمہ اللہ اور اہل سنن نے سیّدنا ابن مسعود رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قتل خطا کی دیت میں فیصلہ فرمایا: کہ بیس بنت مخاض (ایسی اونٹنیاں جو عمر کے دوسرے سال میں داخل ہو گئی ہوں) بیس ابن مَخَاض (ایسے اونٹ جو عمر کے دوسرے سال میں داخل ہو گئے ہوں) بیس بنت ِ لبون (ایسی اونٹنیاں جو عمرکے تیسرے سال میں داخل ہو گئی ہوں) بیس، جَذَعَه(ایسے اونٹ جو عمر کے پانچویں سال میں داخل ہو گئے ہوں) اور بیس حِقَّه (ایسے اونٹ جو عمر کے چوتھے سال میں داخل ہو گئے ہوں) ادا کیے جائیں یہ سنن نسائی کی روایت کے الفاظ ہیں۔ (مسند أحمد و سنن النسائی :4806، سنن أبی داؤد)\nیہ دیت قاتل کے اپنے مال میں سے نہیں بلکہ اس کے عاقلہ (قاتل کے اولاد کے علاوہ پدری رشتے دار جن پر دیت واجب ہوتی ہے) پر واجب ہے جیسا کہ صحیح بخاری و مسلم میں سیّدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ خاندان هُذَيْل کی دو عورتیںلڑ پڑیں تو ایک نے دوسری کو پتھر مار کر اسے اور اس کے پیٹ کے بچے کو قتل کر دیا، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں یہ جھگڑ اپیش ہوا، چنانچہ آپ صلی اللہ علیہ وسلم نے فیصلہ فرمایا: کہ جنین کی دیت غلام یا لونڈی کو آزاد کرنا ہے اور عورت کی دیت اس کے عاقلہ پر ہے۔ (صحیح البخاری : 6909، صحیح مسلم :(35)-1681)\nاس کا تقاضا ہے کہ عَمدِ خطا کا حکم وجوب دیت میں محض قتل ہی کی طرح ہے لیکن اس میں دیت عمد کی طرح تین قسم کے اونٹوں کی صورت میں واجب ہے کیوں کہ اس میں عمد کا شبہ ہے۔ صحیح بخاری میں سیّدنا عبداللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خالد بن ولید کو بنو جَذِيمه کی طر ف بھیجا، انہوں نے انہیں اسلام کی دعوت دی مگر وہ اچھی طرح سے (أَسْلَمْنَا) نہ کہہ سکے اور انہوں نے (صَبَأْنَا صَبَأْنَا) ’’ہم بے دین ہو گئے ہم بے دین ہو گئے ‘‘ کہنا شروع کر دیا،تو سیّدنا خالد بن ولید رضی اللہ عنہ نے انہیں قتل کرنا شروع کر دیا اور… جب رسول اللہ صلی اللہ علیہ وسلم کو یہ خبر پہنچی،تب آپ صلی اللہ علیہ وسلم نے دونوں ہاتھ اُٹھائے اور کہا:«اَللّٰهُمَّ! إِنِّي أَبْرَأُ إِلَيْكَ مِمَّا صَنَعَ خَالِدٌ»’’ اے اللہ ! خالد رضی اللہ عنہ نے جو کچھ کیا ہے، میں اس سے برا ء ت کا اظہا رکرتا ہوں۔‘‘(صحیح البخاری : 4339)پھر آپ صلی اللہ علیہ وسلم نے سیّدنا علی رضی اللہ عنہ کو بھیجا اور انہوں نے ان کے مقتولوں کی دیت اور تلف شدہ اموال حتی کہ ان کتوں کے پانی پینے کے برتنوں تک کا معاوضہ ادا کر دیا۔ (ملخص از السیرۃ النبویۃ لابن ہشام : 74,73/4 ودلائل النبوۃ للبیہقی :114/5)\nاس حدیث سے یہ استدلال کیا جا سکتا ہے کہ امام یا اس کے نائب کی غلطی کی دیت یاکفارہ بیت المال سے ادا کیا جائے گا۔ ﴿اِلَّاۤ اَنْ يَّصَّدَّقُوْاؕ﴾ ’’ہاں، اگر وہ معاف کر دیں (تو ان کو اختیار ہے۔) ‘‘یعنی اس میں دیت واجب ہے جو مقتول کے وارثوں کو ادا کی جائے گی۔ ہاں، اگر وہ معاف کر دیں تو پھر دیت واجب نہیں ہے۔ ﴿فَاِنْ كَانَ مِنْ قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيْرُ رَقَبَةٍ مُّؤْمِنَةٍؕ﴾’’پھر اگر مقتول تمہارے دشمنوں کی جماعت میں سے ہو اور وہ خود مومن ہو تو صرف ایک مسلمان غلام آزاد کرنا چاہیے۔ ‘‘ یعنی اگر مقتول مومن ہو مگر اس کے وارث حربی کافر ہوں تو ان کے لیے دیت نہیں ہے لیکن قاتل کو ایک مسلمان غلام ضرور آزاد کرنا ہوگا نہ کہ کوئی غیر مسلم۔ ﴿وَاِنْ كَانَ مِنْ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُمْ مِّيْثَاقٌ﴾ ’’اور اگر مقتول ایسے لوگوں میں سے ہو جن کا تم سے (صلح کا) عہد ہو۔‘‘ یعنی اگر مقتول کے وارث ذمی ہوں یا ان سے صلح کا معاہدہ کیا گیا ہو تو پھر انہیں ان کے مقتول کی دیت ادا کی جائے۔\nاور مقتول اگر مومن ہو تو کامل دیت بھی ادا کی جائے گی اور قاتل پر ایک مسلمان غلام کو آزاد کرنا بھی واجب ہوگا۔ ﴿فَمَنْ لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ١ٞ﴾ ’’پھر جس کو یہ میسرنہ ہو تو وہ متواتر دو مہینے کے روزے رکھے۔‘‘جن میں ایک دن کے روزے کا ناغہ بھی نہ کرے بلکہ مسلسل دو ماہ روزے رکھے، اگر اس نے کسی مرض یا (عورت ہے تو) حیض و نفاس وغیرہ کے کسی شرعی عذر کے بغیر ایک دن بھی ناغہ کر لیا تو اسے از سر نو روزے رکھنا ہوں گے۔ ﴿تَوْبَةً مِّنَ اللّٰهِؕ وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًا۰۰۹۲﴾ ’’یہ (کفارہ) اللہ تعالیٰ کی طرف سے (قبول) توبہ (کے لیے) ہے اور اللہ تعالیٰ سب کچھ جانتا (اور) بڑا حکمت والا ہے۔ ‘‘یعنی جس قاتل نے قَتلِ خطا کا ارتکاب کیا ہو اور وہ آزاد کرنے کے لیے غلام نہ پائے تو اس کی توبہ کی صورت یہ ہے کہ وہ متواتر دو ماہ کے روزے رکھے۔ ﴿وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًا۰۰۹۲﴾ کی تفسیر قبل ازیں کئی بار بیان کی جا چکی ہے۔ (دیکھیے: النسآئ، آیات : 11 اور 24کے ذیل میں۔)"],[1264,"§قتلِ عمد پر وعید\nقتلِ خطا کے حکم کے بعد اب اللہ تعالیٰ نے قتل عمد کا حکم بیان کیا، چنانچہ فرمایا ہے :﴿وَمَنْ يَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا﴾ ’’اور جو شخص مسلمان کو قصدًا مار ڈالے گا۔ ‘‘ یہ شدید سرزنش اور زبردست وعید ہے، اس شخص کے لیے جو اس کبیرہ گناہ کا ارتکاب کرے جسے کتاب اللہ کی کئی آیات میں شرک کے ساتھ ملا کر بیان کیا گیا ہے، مثلاً:﴿وَالَّذِيْنَ لَا يَدْعُوْنَ مَعَ اللّٰهِ اِلٰهًا اٰخَرَ وَلَا يَقْتُلُوْنَ النَّفْسَ الَّتِيْ حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّ﴾ (الفرقان:68) ’’اور وہ جو اللہ تعالیٰ کے ساتھ کسی اور معبود کو نہیں پکارتے اور جس نفس کو مار ڈالنا اللہ تعالیٰ نے حرام کیا ہے اس کو قتل نہیں کرتے مگر جائز طریق(شریعت کے حکم) سے۔ ‘‘ اور فرمایا:﴿قُلْ تَعَالَوْا اَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ اَلَّا تُشْرِكُوْا بِهٖ شَيْـًٔا وَّبِالْوَالِدَيْنِ۠ اِحْسَانًاۚ وَلَا تَقْتُلُوْۤا اَوْلَادَكُمْ مِّنْ اِمْلَاقٍؕ نَحْنُ نَرْزُقُكُمْ وَاِيَّاهُمْۚ وَلَا تَقْرَبُوا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَۚ وَلَا تَقْتُلُوا النَّفْسَ الَّتِيْ حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّؕ ذٰلِكُمْ وَصّٰىكُمْ بِهٖ لَعَلَّكُمْ تَعْقِلُوْنَ۰۰۱۵۱﴾(الأنعام:151) ’’کہہ دیجئے (لوگو!) آئو میں تمہیں وہ چیزیں پڑھ کر سنائوں جو تمہارے پروردگار نے تم پر حرام کر دی ہیں (ان کی نسبت اس نے اس طرح ارشاد فرمایا ہے)کہ کسی چیز کو اللہ تعالیٰ کا شریک نہ بنانا اور ماں باپ سے (بدسلوکی نہ کرنا بلکہ) احسان کرتے رہنا۔ اور ناداری (کے اندیشے) سے اپنی اولاد کو قتل نہ کرنا (کیوں کہ) تم کو اور ان کو ہم ہی رزق دیتے ہیں۔ اور بے حیائی کے کام ظاہر ہوں یا پوشیدہ ان کے پاس نہ پھٹکنا اور کسی جان(والے) کو جس کے قتل کو اللہ تعالیٰ نے حرام کر دیا ہے قتل نہ کرنا مگر جائز طور پر (جس کا شریعت حکم دے) ان باتوں کا وہ تمہیں ارشاد فرماتا ہے تاکہ تم سمجھو۔ ‘‘\nقتل کی حرمت کے بارے میں آیات کے ساتھ ساتھ بہت زیادہ احادیث ہیں، مثلاً: صحیح بخاری و مسلم میں سیّدنا ابن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت کے دن لوگوں میں سب سے پہلے خونوں ہی کے بارے میں فیصلہ کیا جائے گا۔ ‘‘(صحیح البخاری: 68، صحیح مسلم :1678) ایک دوسری حدیث میں ہے جسے امام ابوداؤد رحمہ اللہ نے بروایت عُبادہ بن صامت رضی اللہ عنہ بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:«لَايَزَالُ الْمُؤْمِنُ مُعْنِقًا صَالِحًا مَّا لَمْ يُصِبْ دَمًا حَرَامًا، فَإِذَا أَصَابَ دَمًا حَرَامًا بَلَّحَ»’’مومن ہمیشہ اللہ تعالیٰ کی اطاعت میں تیز رفتار، عمل میں ہوشیار اور نیکوکاررہتا ہے، بشرطیکہ حرام خون کا ارتکاب نہ کرے اور جب وہ کسی حرام خون کا ارتکاب کر لیتا ہے تو وہ تھک ہار کر (ان صفات سے) منقطع ہوجاتا ہے۔ ‘‘(سنن أبی داؤد:4270) ایک اور حدیث میں ہے : «لَزَوَالُ الدُّنْيَا أَهْوَنُ عِنْدَ اللهِ مِنْ قَتْلِ رَجُلٍ مُّسْلِمٍ» ’’پوری دنیا کا ختم ہوجانا اللہ تعالیٰ کے نزدیک ایک مسلمان آدمی کے قتل کی نسبت کم تر ہے۔ ‘‘ (صحیح: جامع الترمذی : 1395 و سنن النسائی :3992 واللفظ لہ)"],[1265,"§کیا عمداً قتل کرنے والے کی توبہ قبول ہو جاتی ہے ؟\nسیّدنا ابن عباس رضی اللہ عنہما کی رائے یہ تھی کہ مومن کو قصداً مار ڈالنے والے کی توبہ قبول نہیں ہوتی، چنانچہ امام بخاری رحمہ اللہ نے ابن جبیر کا قول بیان کیا ہے کہ اس مسئلے میں جب اہل کوفہ میں اختلاف ہوا تو میں سفر کرکے سیّدنا ابن عباس رضی اللہ عنہما کی خدمت میں حاضر ہوا اور آپ رضی اللہ عنہ سے اس کے بارے میں پوچھا تو آپ رضی اللہ عنہ نے فرمایا: کہ یہ آیت :﴿وَمَنْ يَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهٗ جَهَنَّمُ﴾ ’’اور جو شخص مسلمان کو قصدًا مار ڈالے گا تو اس کی سزا دوزخ ہے۔ ‘‘ سب سے آخر میں نازل ہوئی ہے اور اسے کسی شے نے منسوخ نہیں کیا۔ (صحیح البخاری: 4590. مزید دیکھیے حدیث:3855 و صحیح مسلم :3023)\nجمہور سلف و خلف ِ اُمت کا قول یہ ہے کہ قاتل کی توبہ بھی قبول ہو جاتی ہے، اگر وہ توبہ کر لے، اللہ تعالیٰ کی طرف رجوع کر لے، خشوع و خضوع کا اظہا رکرے اور نیک عمل بجالانا شروع کر دے تو اللہ تعالیٰ اس کے گناہوں کو نیکیوں سے بدل دے گا اور مقتول کو اپنے فضل و کرم سے نواز کر خوش کر دے گا۔ اللہ تعالیٰ نے فرمایا ہے : ﴿وَالَّذِيْنَ لَا يَدْعُوْنَ مَعَ اللّٰهِ اِلٰهًا اٰخَرَ﴾ -تا- ﴿اِلَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَاُولٰٓىِٕكَ يُبَدِّلُ اللّٰهُ سَيِّاٰتِهِمْ حَسَنٰتٍؕ﴾ (الفرقان:68-70) ’’اور وہ جو اللہ تعالیٰ کے ساتھ کسی اور معبود کو نہیں پکارتے…مگر جس نے توبہ کی اور ایمان لے آیا اور اچھے کام کیے تو ایسے لوگوں کے گناہوں کو اللہ تعالیٰ نیکیوں سے بدل دے گا۔ ‘‘ اس خبر کو منسوخ قرار دینا اور اسے صرف مشرکوں پر محمول کرنا صحیح نہیں ہے۔ اور آیت:﴿وَمَنْ يَّقْتُلْ مُؤْمِنًا﴾ کو صرف مومنوں پر محمول کرنا خلافِ ظاہر اور محتاجِ دلیل ہے۔ واللہ أعلم.\nارشادِ باری تعالیٰ ہے : ﴿قُلْ يٰعِبَادِيَ الَّذِيْنَ اَسْرَفُوْا عَلٰۤى اَنْفُسِهِمْ لَا تَقْنَطُوْا مِنْ رَّحْمَةِ اللّٰهِؕ﴾ (الزمر:53) ’’(اے پیغمبر صلی اللہ علیہ وسلم! میری طرف سے لوگوں کو) کہہ دیجئے !اے میرےبندو! جنہوں نے اپنی جانوں پر زیادتی کی ہے، اللہ تعالیٰ کی رحمت سے نااُمید نہ ہو نا۔ ‘‘ یہ آیت کریمہ کفر، شرک، شک، نفاق، قتل اور فسق وغیرہ سب گناہوں کے لیے عام ہے جو شخص بھی ان گناہوں سے توبہ کرے گا تو اللہ تعالیٰ اس کی توبہ کو قبول فرما لے گا۔ ارشاد ِ باری تعالیٰ ہے : ﴿اِنَّ اللّٰهَ لَا يَغْفِرُ اَنْ يُّشْرَكَ بِهٖ وَيَغْفِرُ مَا دُوْنَ ذٰلِكَ لِمَنْ يَّشَآءُؕ﴾ (النسآئ:48) ’’اللہ تعالیٰ (اس گناہ کو) نہیں بخشے گا کہ کسی کو اس کا شریک بنایا جائے اور اس کے سوا جس کے لیے اور جس گناہ کو چاہے معاف کر دے۔ ‘‘ اور یہ آیت بھی شرک کے سوا دیگرتمام گناہوں کو شامل ہے اور اس کا اس سورۂ کریمہ میں اس آیت کے بعد اور اس سے پہلے(یعنی آیت : 48 اور 116) ذکر اس لیے کیا گیا ہے تاکہ گناہوں کی مغفرت کی اُمید کو تقویت پہنچائی جا سکے۔\nصحیح بخار ی و مسلم میں اس اسرائیلی کا واقعہ بھی موجود ہے جس نے ایک سو (100) انسان کو قتل کیا تھا اور جب اس نے ایک عالم سے پوچھا کیا میری توبہ قبول ہو سکتی ہے ؟ تو اس نے کہا: کیوں نہیں ! آپ کے اور توبہ کے درمیا ن کون حائل ہو سکتا ہے ؟ پھر اس نے ایک بستی کی طرف بھی رہنمائی کی کہ وہاں جا کر اللہ تعالیٰ کی عبادت کرو، اس نے اس بستی کی طرف ہجرت کی تو اسے رستے ہی میں موت آگئی تو اس کی روح کو رحمت کے فرشتے نے اپنے قبضے میں لے لیا تھا۔ (ملخص از صحیح البخاری: 3470، صحیح مسلم 2766) ہم نے اس واقعے کو کئی بار ذکر کیا ہے۔ (دیکھیے : النسآئ : 100 اور الزمر:53 کے ذیل میں۔)اگربنی اسرائیل کے اس شخص کی جرمِ قتل سے توبہ قبول ہو سکتی ہے تو اس اُمت کے گناہ گاروں کی توبہ بالاولیٰ قبول ہوگی کیوں کہ اللہ تعالیٰ نے ہم سے وہ تمام بوجھ اور بیڑیاں اتار پھینکی ہیں جو ان پرڈال دی گئی تھیں۔ اللہ تعالیٰ نے ہمارے نبی صلی اللہ علیہ وسلم کو آسان دین حنیف کے ساتھ مبعوث فرمایا ہے۔\nآیت ِ کریمہ :﴿وَمَنْ يَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهٗ جَهَنَّمُ﴾ کے بارے میں سیّدنا ابوہریرہ رضی اللہ عنہ اور ائمہ سلف میں سے ایک جماعت نے فرمایا ہے کہ اگر اللہ تعالیٰ سزا دینا چاہے تو یہ اس قاتل کی سزا ہے۔(تفسیر ابن أبی حاتم : 1038/3. دیکھیے : الدرالمنثور:352/2) اسی طرح ہر گناہ کے بارے میں جو وعید بیان کی گئی ہے، اس کایہی مفہوم ہے۔ یہ بھی ہو سکتا ہے کہ اس نے کچھ ایسے اعمال صالحہ بھی کیے ہوں جو اس تک اس سزا کو نہ پہنچنے دیں وعید کے سلسلے میں یہ ایک انتہائی مستحسن قول ہے۔ واللہ أعلم بالصَّواب. اور اگر یہ فرض بھی کر لیا جائے کہ قاتل جہنم میں داخل ہوگا جیسا کہ سیّدنا ابن عباس رضی اللہ عنہما اور ان کے ہم نوا لوگوں نے یہ فرمایا ہے کہ اس کی توبہ قبول نہیں یا جمہور کے بقول اس کا کوئی عمل صالح نہ ہو جو اسے جہنم سے بچا سکے تو پھر بھی وہ ابدی جہنمی نہیں ہوگا۔ خلود سے مراد یہ ہوگا کہ وہ طویل عرصے تک جہنم میں رہے گا کیوں کہ متواتر احادیث سے یہ ثابت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:«يُخْرَجُ مِنَ النَّارِ مَنْ كَانَ فِي قَلْبِهٖ مِثْقَالُ ذَرَّةٍ مِّنَ الْإِيمَانِ» ’’جہنم میں سے ہر اس شخص کو باہر نکال لیا جائے گا جس کے دل میں ذرہ بھر بھی ایمان ہوا۔‘‘\n(صحیح البخاری : 22 و 44، صحیح مسلم :(326)-193)\nمنافقین کے ساتھ قتال کا حکم بیان کرنے کے بعد صادق الایمان مومن کے قتل کا حکم بیان کرنا مناسب معلوم ہوا، سب سے پہلے تو اللہ تعالیٰ نے یہ بیان کیا کہ مسلمان کےلیے کسی طرح بھی مناسب اور جائز نہیں کہ وہ اپنے مسلمان بھائی کو قتل کرے۔ ہاں، اگر غلطی سے بغیر قصد کے ایسا ہوجائے تو دوسری بات ہے، جیسے کوئی کسی کافر پر گولی چلائے، اور غلطی سے کسی مسلمان کو لگ جائے، یا کسی پر کافر سمجھ کر گولی چلائے، اور وہ مسلمان نکل آئے۔ ابن جریر، ابن ابی حاتم، اور ابن المنذر رحمہم اللہ وغیرہم نے مجاہد رحمہ اللہ سے روایت کی ہےکہ یہ آیت عیاش بن ابی ربیعہ کے بارے میں نازل ہوئی، جنہوں نے حارث بن یزید کو کافر سمجھ کر مدینہ میں قتل کر دیا تھا۔ حار ث اور ابو جہل مکہ میں عیاش کو سزادیتے رہے تھے۔ بعد میں حارث مسلما ن ہو کر مدینہ آگئے۔ عیاش نے ان کو مدینہ میں دیکھا تو سمجھا کہ ابھی کافر ہی ہیں۔ چنانچہ اپنی تلوار سے انہیں قتل کر دیا۔ جب انہیں ان کے اسلام کا علم ہوا تو رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا، اس پر یہ آیت نازل ہوئی، جس میں قتل ِ خطا کا حکم بیان ہوا۔\nاگر کوئی شخص غلطی سے کسی مسلمان کو قتل کر دیتا ہے، اور مقتول کے ورثہ ’’دیت‘‘ معاف کر دیتے ہیں تو دیت ساقط ہو جائے گی، لیکن اللہ کا حق یعنی ایک مسلمان غلام یا لونڈی کو آزاد کرنا واجب ہوگا، تاکہ اس کے ہر عضوکے بدلے قاتل کا ہر عضو جہنم کی آگ سے آزاد ہو جائے۔ اگر مقتول کے ورثہ معاف نہیں کرتے تو دیت دینا واجب ہوگا، جس کی مقدار عمرو بن حزم اور جابر سے مروی صحیح احادیث کے مطابق سو اونٹ، دو سو گائیں، دوہزار بکریاں، ہزار دینا، یا بارہ ہزار درہم ہے، جسے قاتل کے آبائی رشتہ دار ادا کریں گے اور اگر مقتول ایسی کافر قوم کا فرد ہو جو مسلمانوں کے دشمن ہوں، البتہ وہ مسلمان تھا جس کے اسلام کا پتہ نہ چل سکا تھا، تو ایک مسلمان غلام یا لونڈی آزاد کرنا ہوگا، اور دیت ساقط ہو جائے گی، اس لیے کہ اس کی قوم کے لوگ کافر اور مسلمانوں کے دشمن ہیں، اس لیے اس کے اور اس کے رشتہ داروں کے درمیان وراثت ثابت نہیں ہوگی اور اگرمقتول ایسی کافر قوم کا فرد ہے جس کا مسلمان کے ساتھ معاہدہ ہے، تو مقتول کے ورثہ کو دیت دینی ہوگی اور ایک مسلمان غلام یا لونڈی بھی آزاد کرنا ہوگا اور اگر غلام یا لونڈی دستیاب نہیں ہوتی جسے آزاد کیا جا سکے تو بطور توبہ مسلسل دو ماہ تک روزے رکھنے ہوں گے۔\nقتلِ عمد اتنا بڑا گناہ ہے کہ اللہ تعالیٰ نے متعدد آیات میں اسے شرک باللہ کے ساتھ بیان کیا ہے، جیسا کہ سورۃ الفرقان آیت (68)میں ہے : ﴿وَالَّذِيْنَ لَا يَدْعُوْنَ مَعَ اللّٰهِ اِلٰهًا اٰخَرَ وَلَا يَقْتُلُوْنَ النَّفْسَ الَّتِيْ حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّ﴾ ’’اور جو لوگ اللہ تعالیٰ کے ساتھ کسی دوسرے معبود کو نہیں پکارتے، اور کسی نفس کو قتل نہیں کرتے جسے اللہ تعالیٰ نے حرام کیا ہے، مگر حق کے ساتھ۔‘‘ اور احادیث میں بھی اس کی بڑی وعید آئی ہے۔ جیسا کہ ترمذی رحمہ اللہ نے ابو سعید خدری رضی اللہ عنہ اور ابوہریرہ رضی اللہ عنہ سے روایت کی ہے کہ ’’اگر آسمان و زمین کے تمام رہنے والے ایک مومن کے قتل میں شریک ہو جائیں، تو اللہ تعالیٰ ان سب کوجہنم میں ڈال دے گا۔ ‘‘\nکسی مومن کو قصداً قتل کرنے والے کی توبہ قبول کی جائے گی یا نہیں، اس کے بارے میں صحابہ رضی اللہ عنہم کا اختلاف رہا ہے۔ ابن عباس رضی اللہ عنہما کہتے ہیں کہ اس کی توبہ نہیں قبول ہوگی۔ بخاری رحمہ اللہ نے سعید بن جبیر رحمہ اللہ سے ابن عباس رضی اللہ عنہما کا قول نقل کیا ہے کہ یہ آیت آخری دنوں میں نازل ہوئی، اور کسی دوسری آیت نے اسے منسوخ نہیں کیا ہے۔ مسلم، نسائی اور ابوداؤد رحمہم اللہ نے ایک دوسری اسی معنی کی حدیث ابن عباس رضی اللہ عنہما ہی سے روایت کی ہے، جس کے آخر میں ہے کہ اس آیت کے بعد کوئی دوسری آیت نازل نہیں ہوئی جو اُسے منسوخ کرے۔ زید بن ثابت، ابوہریرہ، عبداللہ بن عمرو رضی اللہ عنہم، حسن اور قتادہ وغیرہم کی یہی رائے ہے۔ اور جمہور علمائے اُمّت کا قول ہے کہ قاتلِ عمد کی اس کے اور اس کے رب کے درمیان توبہ ہے۔ اگر توبہ کرلے، اور عملِ صالح کے ذریعہ اپنی حالت درست کرلے، تو اللہ تعالیٰ اس کے گناہوں کو نیکیوں سے بدل دے گا، اور مقتول کو اس کی مظلومت کا اچھا بدلہ عطا کرکے اُسے خوش کر دے گا۔ سورۃ الفرقان کی جو آیت ابھی گزری ہے، اس میں شرک باللہ، قتل عمد اور زنا جیسے جرائم کا ذکر کرنے کے بعد، اللہ تعالیٰ نے فرمایا ہے : ﴿اِلَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَاُولٰٓىِٕكَ يُبَدِّلُ اللّٰهُ سَيِّاٰتِهِمْ حَسَنٰتٍؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًا۰۰۷۰﴾ کہ ’’جو شخص توبہ کر لے گا، او ر ایمان لے آئے گا، او رعمل صالح کرے گا، تو اللہ تعالیٰ اس کے گناہوں کو نیکیوں سے بدل دے گا۔ اور بے شک اللہ تعالیٰ غفور رحیم ہے۔ ‘‘ اللہ تعالیٰ نے سورۃ الزمر آیت (53)میں فرمایا ہے : ﴿قُلْ يٰعِبَادِيَ الَّذِيْنَ اَسْرَفُوْا عَلٰۤى اَنْفُسِهِمْ لَا تَقْنَطُوْا مِنْ رَّحْمَةِ اللّٰهِؕ اِنَّ اللّٰهَ يَغْفِرُ الذُّنُوْبَ جَمِيْعًاؕ﴾ ’’آپ صلی اللہ علیہ وسلم کہہ دیجئے کہ اے میرے بندو! جنہوں نے اپنے آپ پر ظلم کیا ہے، اللہ تعالیٰ کی رحمت سے نااُمید نہ ہو، بے شک اللہ تعالیٰ تمام گناہوں کو معاف کردیتا ہے۔ ‘‘ ان دونوں آیتوں میں تمام گناہوں کے بارے میں حکم عام ہے کہ صدق دل سے توبہ کرنے سے اللہ تعالیٰ انہیں معاف کر دیتا ہے۔ او راگر فرض بھی کر لیا جائے کہ قتل ِ عمد کامرتکب جہنم میں ضرور داخل ہوگا، یا تو اس لیے کہ ابن عباس رضی اللہ عنہما وغیرہ کے قول کے مطابق اس کی توبہ قبول نہیں ہوگی، یا جمہور کے قول کے مطابق کہ اس کے پاس کوئی عمل صالح نہیں، تو بھی وہ جہنم میں ہمیشہ کے لیے نہیں رہے گا، اس لیے کہ آیت میں ’’خلود فی النار‘‘ سے مراد لمبی مدت ہے، جیسا کہ متواتر احادیث سے ثابت ہے کہ جس کے دل میں ایک ذرہ کے برابر بھی ایمان ہوگا، وہ جہنم سے نکال دیا جائے گا۔\nیہاں ایک سوال اور رہ جاتا ہے کہ اُمت کا اجماع ہے کہ توبہ کے ذریعہ کسی کا حق ساقط نہیں ہوجاتا۔ اس لیے توبہ کرنے کے بعد بھی مقتول کا حق قاتل کے ذمہ باقی رہے گا، اور وہ قیامت کے دن اپنے حق کا مطالبہ کرے گا۔ تو اس کا جواب یہ ہے کہ جب اللہ تعالیٰ قاتل کی توبہ قبول کرلے گا، تو ممکن ہے کہ اللہ تعالیٰ مقتول کو اس کی مظلومیت کا اتنا اچھا بدلہ دے گا کہ وہ خوش ہو جائے گا، او رقاتل کی توبہ قبول ہو جانے کی وجہ سے وہ بھی اللہ تعالیٰ کے فضل و کرم سے جنت میں بھیج دیا جائے گا۔"],[1266,"§قتل خطا کی صورتیں اور کفارہ\nاس آیت میں قتل خطا کے احکا م بیان ہوئے ہیں۔ قتل خطا کی کئی صورتیں ہو سکتی ہیں: مثلاً تیر یا پتھر مارا تو شکار کو تھا لیکن وہ کسی مسلمان کو لگ گیا اور وہ مر گیا۔ دوسری صورت یہ ہے کہ ماری تو کوئی چیز عمدًا ہی تھی مگر مارنے والے کو ہرگز یہ گمان نہ تھا کہ وہ اس ہلکی سی ضرب سے مر ہی جائے گا۔ تیسری یہ کہ لڑائی وغیرہ کسی ہنگامے میں کسی مسلمان کو کافر سمجھ کر مار ڈالے۔ جیسا کہ جنگ اُحد میں شکست کے بعد مسلمانوںنے بدحواسی کے عالم میںسیدنا حذیفہ بن یمان رضی اللہ عنہ کے والد سیدنا یمان رضی اللہ عنہ کو کافر سمجھ کر شہید کرڈالا تھا۔ حالانکہ سیدنا حذیفہ رضی اللہ عنہ یہ کہتے ہی رہے کہ یہ تو میرے والد ہیں مگر اس افراتفری کے عالم میں کسی نے سیدنا حذیفہ رضی اللہ عنہ کی آواز کو سنا ہی نہ تھا۔ اورچوتھی صورت جو آج کل بہت عام ہے، یہ کہ ٹریفک کے حادثہ میں کسی گاڑی کے نیچے آکر، یا اس کی ضرب سے مار ا جائے۔\nقتل خطا کے احکام یا اس کے کفارہ کی صورتیں یہ ہیں :\n1:\nاگر مقتول کے وارث مسلمان ہیں تو ایک غلام مومن (خواہ مرد ہو یا عورت) آزاد کرنا ہوگا اور مقتول کے وارثوں کو خون بہا بھی ادا کرنا ہوگا۔ خون بہایا دیت سو اونٹ یا ان کی قیمت کے برابر رقم ہے۔ جو قاتل کے وارث مقتول کے وارثوں کو ادا کریں گے۔ امام ابو حنیفہ رحمہ اللہ کے نزدیک ادائیگی دیت کی زیادہ سے زیادہ مدت تین سال تک ہے اور یہ دیت مقتول کے وارث چاہیں تو معاف بھی کر سکتے ہیں۔\nاور اگر قاتل کو (آزاد کرنے کے لیے) غلام میسر نہ آئے تو وہ متواتر دو ماہ روزے بھی رکھے گا۔\nواضح رہے کہ سیدنا حذیفہ رضی اللہ عنہ کے والد جنگ اُحد میں اجتماعی صورت میں کی مسلمانوں کے ہاتھوں شہید ہوئے جنھیں سیدنا حذیفہ رضی اللہ عنہ نے علی الاعلان معاف کر دیا تھا۔ اور اللہ تعالیٰ نے اہل احد کی خطائیں معاف کر دی تھیں لہٰذا وہاں کفار ے کا کوئی سوال ہی پیدا نہ ہوتا تھا۔\n6:\nاگر مقتول تو مومن ہو مگر دشمن قوم سے تعلق رکھتا ہو تو اس کا کفارہ صرف ایک مسلمان غلام آزاد کرنا ہے۔ اور اگر میسر نہ آئے تو دو ماہ کے متواتر روزے ہیں اور اس کی دیت نہ ہوگی۔\n3:\nاوراگر مومن مقتول کا تعلق کسی معاہد قوم سے ہو تو اس کے وہی احکام ہیں جو پہلی صورت کے ہیں۔\nقتل خطا کے کفارے کی مختلف صورتیں اور توبہ کا طریقہ تو بیان کر دیا گیا مگر کسی مومن کاقتل عمدًا انتہائی شدید جرم ہے جس کا اس دنیا میں کفارہ ممکن ہی نہیں۔ قتل ناحق کسی غیر مسلم کا ہو تو وہ بھی شدید جرم ہے پھر اگر مومن کا ہو تو مزید شدید جرم بن جاتاہے۔ نیز جرم بیان کرنے کے بعد اللہ تعالیٰ کا غضب اور اس کی لعنت کے الفاظ سے اس جرم کی شدت واضح ہو جاتی ہے۔ رہا یہ سوال کہ ایسے مجرم کی توبہ بھی قبول ہے یا نہیں؟ تو اگرچہ اس میں علماء کا اختلاف موجو دہے تاہم سیدنا ابن عباس رضی اللہ عنہما اسی بات کے قائل ہیں کہ ایسے مجرم کی توبہ قبول نہیں ہوتی۔ جیسا کہ درج ذیل احادیث سے جہاں یہ بات واضح ہوتی ہے وہاں یہ بھی معلوم ہوتا ہے کہ یہ کتنا بڑا جرم ہے۔\n1:\nسیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم نے (اپنے خطبہ حجۃ الوداع) میں فرمایا:’’ اللہ تعالیٰ نے تم پر ایک دوسرے کے خون، مال اور آبرو اسی طرح حرام کر دی ہیں جس طرح تمہارے اس دن (یوم النحر) کی تمہارے اس شہر (مکہ) کی اور تمہارے اس مہینہ (ذوالحجہ) کی حرمت ہے۔ نیز فرمایا: کہ میرے بعد ایک دوسرے کی گردنیں مار کر کافر نہ بن جانا۔ ‘‘(صحیح البخاری)\n2:\nقتل ناحق اور قتل عمد: سیدنا ابو بکر رضی اللہ عنہ فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ جب دو مسلمان تلوار لے کر باہم لڑیں تو قاتل و مقتول دونوں جہنمی ہیں۔ ‘‘ میں نے کہا:’’ اے اللہ کے رسول صلی اللہ علیہ وسلم! یہ تو قاتل تھا، مقتول کا کیا قصور ؟ ‘‘ فرمایا:’’ اس لیے کہ وہ بھی اپنے ساتھی کے قتل کے درپے تھا۔‘‘(صحیح البخاری)\n3:\nسیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ تین آدمیوں پر اللہ تعالیٰ (قیامت کے دن) سب سے زیادہ غضب ناک ہوگا: (1)حرم میں الحاد کرنے والا (2)اسلام میں طریقہ جاہلیت کا متلاشی اور (3)ناحق کسی کا خون بہانے کا طالب۔‘‘(صحیح البخاری)\n4:\nسیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’قیامت کے دن قاتل کو پیشانی کے بال اور سر مقتول کے ہاتھ میںہوگا اور اس کے گلے کی رگوں سے خون بہہ رہا ہوگا اور اللہ تعالیٰ سے فریاد کرے گا کہ اے میرے رب ! اس نے مجھے قتل کیا تھا یہاں تک کہ عرش کے قریب لے جائے گا۔ راوی کہتا ہے کہ لوگوں نے ابن عباس رضی اللہ عنہما کے سامنے توبہ کا ذکر کیا تو انہوں نے یہی آیت پڑھی اور کہا کہ یہ آیت نہ منسوخ ہے اور نہ بدلی گئی۔ پھر اس کی توبہ کیسے قبول ہو سکتی ہے؟\n(ترمذی)\n5:\nسیدناابن عباس رضی اللہ عنہما کہتے ہیں کہ یہ آیت اخیر زمانہ میں نازل ہوئی (لہٰذا محکم ہے) اسے کسی چیز نے منسوخ نہیں کیا۔\n(صحیح البخاری)\nیہ قتل عمد کی سزا ہے۔ قتل کی تین قسمیںہیں : (1)قتل خطا (جس کا ذکر ماقبل کی آیت میں ہے)۔ (2)قتل شبہ عمدجو حدیث سے ثابت ہے۔ (3)قتل عمد جس کا مطلب ہے، ارادہ اور نیت سے کسی کو قتل کرنا اور اس کے لیے دو آلہ استعمال کرنا جس سے فی الواقع عادتاً قتل کیاجاتا ہے جیسے تلوار، خنجر وغیرہ۔ آیت میں مومن کے قتل پر نہایت سخت وعید بیان کی گئی ہے۔ مثلاً اس کی سزاجہنم ہے، جس میں ہمیشہ رہنا ہوگا، نیز اللہ تعالیٰ کا غضب اور اس کی لعنت اور عذاب عظیم بھی ہوگا۔ اتنی سخت سزائیں بیک وقت کسی بھی گناہ کی بیان نہیں کی گئیں۔ جس سے یہ واضح ہوجاتا ہےکہ ایک مومن کو قتل کرنا اللہ تعالیٰ کے ہاں کتنا بڑا جرم ہے۔ احادیث میں بھی اس کی سخت مذمت اور اس پر سخت وعیدیں بیان کی گئی ہیں۔\nمومن کے قاتل کی توبہ قبول ہے یا نہیں؟ بعض علماء مذکورہ سخت وعیدوں کے پیش نظر قبول توبہ کے قائل نہیں ہے لیکن قرآن و حدیث کی نصوص سے واضح ہے کہ خالص توبہ سے ہر گناہ معاف ہوسکتا ہے۔ ﴿اِلَّا مَنْ تَابَ وَاٰمَنَ وَعَمِلَ عَمَلًا صَالِحًا﴾ (الفرقان:70) اور دیگر آیات توبہ عام ہیں۔ ہر گناہ چاہے چھوٹا ہو یا بڑا یا بہت بڑا، توبۃ النصوح سے اس کی معانی ممکن ہے۔ یہاں اس کی سزا جہنم جو بیان کی گئی ہے اس کا مطلب ہے کہ اگر اس نے توبہ نہیں کی تو اس کی یہ سزا ہے جو اللہ تعالیٰ اس جرم پر اسے دے سکتا ہے۔ اسی طرح توبہ نہ کرنے کی صورت میں خلود (ہمیشہ جہنم میں رہنے) کا مطلب مکث طویل (لمبی مدت) ہے۔ کیوں جہنم میں خلود کا فروں اور مشرکوں کے لیے ہی ہے۔ علاوہ ازیں قتل کا تعلق اگرچہ حقوق العباد سے ہے جو توبہ سے بھی ساقط نہیں ہوتے لیکن اللہ تعالیٰ اپنے فضل و کرم سے بھی اس کی تلافی اور ازالہ فرما سکتا ہے اس طرح مقتول کو بھی بدلہ مل جائے گا اور قاتل کی بھی معافی ہو جائے گی۔ (فتح القدیر و ابن کثیر)\nاور وہ لوگ جو اللہ تعالیٰ کے ساتھ کسی دوسرے معبود کو نہیں پکار تے ہیں اور اس جان کو جس کی حرمت کو اللہ تعالیٰ نے ثابت کیا ہے قتل نہیں کرتے ہیں مگرحق کے ساتھ اور وہ زنا نہیں کرتے ہیں اور جو شخص ان کاموں کا مرتکب ہوگا وہ گناہ سے دو چار ہوا قیامت کے دن اسے دو گنا عذاب دیا جائے گا اور وہ اس میں ہمیشہ رہے گا، البتہ وہ شخص جو توبہ کرتا ہے اور ایمان لاتا ہے اورا عمال صالحہ کرتا ہے تو یہ وہ لوگ ہیں کہ اللہ تعالیٰ ان کی بڑائیوں کو نیکیوں میں تبدیل کرے گا اور اللہ تعالیٰ معاف کرنے والا ہے۔ ذہن نشین کریں جس شخص سے قتل کا جرم سر زد ہو تا ہے اس جرم کے بعد جب وہ محسوس کرتا ہے کہ اس کا یہ جرم تو ایسا ہے جس کی پاداش میں اسے ہمیشہ دوزخ میں رہنا ہے بلکہ اللہ تعالیٰ کی لعنت کا مستحق ہوتا ہے اور اللہ تعالیٰ کی رحمت سے دوررہنا ہے وہ اللہ تعالیٰ کی ناراضگی میں ہی رہے گا جب وہ اس سزا پر غور کرتا ہے تو وہ گناہ اور اس کی سزا کے تصور سے کانپ اُٹھتاہے۔ فرط ندامت سے اس کی آنکھیں غیر شعوری طور پر اشک بار ہوجاتی ہیں اس کا جسم گناہ کی سزا کے تصور سے بے جان سا ہوجاتاہے۔ وہ صدق دل اور پر نم آنکھوں کے ساتھ بارگاہِ الٰہی میں ذلت و مسکنت کے ساتھ حاضر ہوتا ہے وہ خلوص کے ساتھ توبہ کرتا ہے مغفرت کی بھیک مانگتا ہے اور اس عزم کا اظہار کرتا ہے کہ دوبارہ اس گناہ کا ارتکاب ہر گز نہیں ہوگا بلکہ اس کے علاوہ دیگر گناہوں سے بھی دور ر ہے گا اور زندگی بھر اعمال صالحہ پر مداومت کرتا رہے گا یقیناً اس کیفیت کے ساتھ موصوف شخص کے بارے میں اُمید ہے کہ اس کا جرم عظیم معاف ہو جائے گا۔ حافظ ابن حجر رحمہ اللہ نے واضح کیا کہ قاتل کی توبہ گناہ گاروں کی توبہ کی طرح صحیح ہے اور توبہ کا قبول نہ ہونا تشدد ہے جب کہ اسرائیلی شخص جس نے ننانوے قتل کیے بلکہ سو کی گنتی مکمل کی اس کی توبہ قبول کی گئی جو اُمت محمدیہ سے نہیں تھا تو اُمت محمدیہ کی توبہ کیوں نہ ہوگی جب کہ اُمت محمدیہ سے بہت بوجھ اُتار دیے گئے جو پہلی اُمتوں پر تھے۔ (فتح الباری : 496/8)\n﴿يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْۤا اِذَا ضَرَبْتُمْ فِيْ سَبِيْلِ اللّٰهِ فَتَبَيَّنُوْا وَلَا تَقُوْلُوْا لِمَنْ اَلْقٰۤى اِلَيْكُمُ السَّلٰمَ لَسْتَ مُؤْمِنًاۚ تَبْتَغُوْنَ عَرَضَ الْحَيٰوةِ الدُّنْيَا١ٞؗ فَعِنْدَ اللّٰهِ مَغَانِمُ كَثِيْرَةٌؕ كَذٰلِكَ كُنْتُمْ مِّنْ قَبْلُ فَمَنَّ اللّٰهُ عَلَيْكُمْ فَتَبَيَّنُوْاؕ اِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُوْنَ خَبِيْرًا۰۰۹۴﴾\nاے لوگو جو ایمان لائے ہو! جب تم اللہ کے راستے میں نکلو تو تحقیق کر لیا کرو، اور جو شخص تمہیں سلام کرے تو اس کے متعلق یہ نہ کہو کہ تو مومن نہیں۔ تم دنیاوی زندگی کا سامان چاہتے ہو، تو اللہ کے پاس (تمہارے لیے) بہت سے مال غنیمت ہیں۔ تم اس سے پہلے خود بھی اس حالت میں مبتلا رہ چکے ہو، پھر اللہ نے تم پر احسان کیا، لہٰذا معاملے کی تحقیق کر لیا کرو۔ بے شک تم جو عمل کرتے\nہو اللہ اس سے خوب با خبر ہے⟦94⟧"],[1267,"§سلام کہنااسلام کی علامت ہے\nامام احمد رحمہ اللہ نے عکرمہ رحمہ اللہ کی سیّدنا ابن عباس رضی اللہ عنہما سے روایت کو بیان کیا ہے کہ بنو سُلَيم کا ایک شخص صحابہ کرام رضی اللہ عنہم کی ایک جماعت کے پاس سے گزرا جو اپنی بکریاں چرا رہا تھا۔ اس نے انہیں سلام کہا تو انہوں نے کہا کہ اس نے ہم سے بچنے کے لیے سلام کہا ہے، لہٰذا نھوں نے اسے قتل کر دیا اور اس کی بکریاں لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آگئے تواس وقت یہ آیت نازل ہوئی تھی۔(مسند أحمد) امام ترمذی رحمہ اللہ نے اسے روایت کیا ہے اور کہا ہے کہ یہ حدیث حسن ہے۔ اور اس باب میں سیّدنا اسامہ بن زید رضی اللہ عنہ سے بھی حدیث مروی ہے۔(جامع الترمذی : 3030) امام حاکم رحمہ اللہ نے بھی اسے روایت کیا اور کہا ہے کہ اس کی سند صحیح ہے مگر امام بخاری و مسلم رحمہما اللہ نے اسے (اس سند سے) بیان نہیں کیا۔ (المستدرک للحاکم :2920)\nامام بخاری رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ ایک شخص اپنی بکریوں کے ریوڑ میں تھا کہ مسلمانوں نے اسے جا لیا، تو اس نے کہا: السلام علیکم مگر انہوں نے اسے قتل کر دیا اور اس کی بکریوں کو پکڑ لیا تو اس موقع پر اللہ تعالیٰ نے یہ آیت کریمہ نازل فرمائی:﴿وَلَا تَقُوْلُوْا لِمَنْ اَلْقٰۤى اِلَيْكُمُ السَّلٰمَ لَسْتَ مُؤْمِنًاۚ﴾ ’’اور جو شخص تم کو سلام کرے، اس سے یہ نہ کہو کہ تو مومن نہیں ہے۔ ‘‘\nسیّدنا ابن عباس رضی اللہ عنہما فرماتے ہیں کہ اس آیت :﴿عَرَضَ الْحَيٰوةِ الدُّنْيَا١ٞ﴾ ’’دنیا کی زندگی کے فائدے ‘‘ سے مراد یہی مالِ غنیمت ہے۔ (اور ﴿ السَّلٰمَ﴾ میں کئی اور قراء تیں بھی ہیں، مثلاً: السَّلَم اور السَّلْم.) جب کہ انہوں نے السَّلٰم ہی پڑھا ہے۔ (صحیح البخاری : 4591 و صحیح مسلم :3025)\nامام احمد رحمہ اللہ نے قَعقاع کی اپنے باپ عبداللہ بن ابو حَدْرَد رضی اللہ عنہما سے روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں إِضَمْ (یہ مدینہ منورہ کی شمالی جانب أرض جہینہ کی ایک جگہ کا نام ہے جو جبلِ احد کے پیچھے واقع ہے۔)کی طرف بھیجا،چنانچہ میں مسلمانوں کی ایک جماعت کے ساتھ روانہ ہوا جس میں ابو قتادہ حارث بن رِبعی اور مُحَلَّمْ بن جثامہ بن قیس رضی اللہ عنہم بھی تھے، ہم چلے جا رہے تھے اور جب وادی إِضم میں پہنچے تو عامر بن أضبط اشجعی اپنے اونٹ پر سوار ہمارے قریب ہوئے تو ان کے پاس تھوڑا سا سامان اور دودھ کا مشکیزہ بھی تھا، جب وہ ہمارے پاس سے گزرے تو انہوں نے ہمیں سلام کہا جس کی وجہ سے ہم نے تو انہیں کچھ نہ کہا مگر مُحَلَّمْ بن جَثَّامه نے حملہ کرکے انہیں قتل کر دیا، اس لیے کہ دونوں میں پہلے سے کوئی ناراضی تھی، مُحَلَّمْ نے اس کے اونٹ اور سامان بھی لے لیا، جب ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو ہم نے آپ صلی اللہ علیہ وسلم کو یہ واقعہ بتایا، چنانچہ اس موقع پر اللہ تعالیٰ نے اس آیت ِکریمہ کو نازل فرما دیا۔(مسند أحمد، والسیرۃ النبویۃ لابن ہشام :275/4) اس روایت کو بیان کرنے میں امام احمد رحمہ اللہ متفرد ہیں۔\nامام بخاری رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مقداد رضی اللہ عنہ سے فرمایا تھا : ’’یہ شخص اپنی قوم کفار میں رہتے ہوئے اپنے ایمان کو مخفی رکھے ہوئے تھا مگر جب اس نے اپنے ایمان کا اظہار کیا تو تونے اسے قتل کر دیا، حالانکہ تو بھی اس سے پہلے مکہ میں اپنے ایمان کو چھپائے ہوئے تھا۔(صحیح البخاری: 6866) امام بخاری رحمہ اللہ نے اس حدیث کو معلق اور مختصر بیان کیا ہے جب کہ یہ روایت مطوّل اورموصول بھی مروی ہے۔\nچنانچہ حافظ ابو بکر بزار رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک سَرِيَّه روانہ فرمایا جس میں مقداد بن اسود رضی اللہ عنہ بھی تھے، جب وہ لوگوں کے پاس پہنچے تو دیکھا کہ وہ الگ الگ ہو چکے ہیں مگر ایک شخص جس کے پاس بہت سامال ہے، وہ ابھی تک وہیں ہے، اس نے انہیں دیکھ کر کہہ دیا : «أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا اللهُ» مگر مقداد رضی اللہ عنہ نے اس پر حملہ کر کے اسے قتل کر دیا، اس کے ساتھیوں میں سے ایک شخص نے کہا: کیا تم نے ایسے آدمی کو بھی قتل کر دیا جو (لَاإِلٰهَ إِلَّا اللہُ) کی گواہی دے رہا تھا ؟ اللہ کی قسم ! میں اس بات کا نبی اکرم صلی اللہ علیہ وسلم سے ضرور ذکر کروں گا، جب یہ لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضرہوئے تو انہوں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم! ایک آدمی نے گواہی دی کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں مگر مقداد رضی اللہ عنہ نے اسے بھی قتل کر دیا۔\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مقداد رضی اللہ عنہ کو میرے پاس لائو، مقداد رضی اللہ عنہ آئے تو آپ صلی اللہ علیہ وسلم نے فرمایا: مقداد رضی اللہ عنہ تم نے ایک ایسے آدمی کو قتل کردیا جو لا الٰہ الا اللہ کہتا تھا تمہارا کیا حال ہوگا جب وہ کل لا الٰہ الا اللہ کے ساتھ آئے گا؟ تو اس موقع پر اللہ تعالیٰ نے اس آیت کریمہ کو نازل فرمایا: ’’مومنو! جب تم اللہ تعالیٰ کی راہ میں باہر نکلا کرو تو تحقیق سے کام لیا کرو اور جو شخص تم کو سلام کرے، اس سے یہ نہ کہو کہ تم مومن نہیں ہو اور اس سے تمہاری غرض یہ ہو کہ دنیا کی زندگی کا فائدہ حاصل کرو، اللہ تعالیٰ کے نزدیک تو بہت سی غنیمتیں ہیں، تم بھی تو پہلے ایسے ہی تھے۔ پھر اللہ تعالیٰ نے تم پر احسان کیا تو (آئندہ) تحقیق کر لیا کرو۔ ‘‘ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے مقداد رضی اللہ عنہ سے فرمایا: ’’یہ مومن شخص اپنی کافر قوم میں رہتے ہوئے اپنے ایمان کو مخفی رکھے ہوئے تھا مگر جب اس نے اپنے ایمان کا اظہار کیا تو تُو نے اسے قتل کر دیا تھا، حالانکہ تو بھی اس سے پہلے مکہ میں اپنے ایمان کو چھپائے ہوئے تھا۔ ‘‘(کشف الأستار : 2202)\n﴿فَعِنْدَ اللّٰهِ مَغَانِمُ كَثِيْرَةٌؕ﴾ ’’سو اللہ تعالیٰ کے نزدیک تو بہت سی غنیمتیں ہیں۔ ‘‘ یعنی اللہ تعالیٰ کے پاس جو بھلائیاں ہیں وہ دنیا کی زندگی کے اس فائدے سے کہیں بہتر ہیں جس کی وجہ سے تم نے اس شخص کو قتل کر دیا جس نے تمہیں سلام کہا تھا اور تمہارے سامنے اپنے ایمان کا اظہا رکیا تھا مگر تم اس سے غافل ہو گئے۔ اورتم نے اس پر یہ الزام لگایا کہ وہ اپنے آپ کو تم سے بچانے کے لیے تقیہ کے طور پر اسلام کا اظہار کر رہا ہے تاکہ تم دنیا کی زندگی کے فائدے کو حاصل کر سکو مگر اللہ تعالیٰ کے پاس جو رزقِ حلال ہے وہ اس شخص کے مال سے تمہارے لیے کہیں بہتر ہے۔\n﴿كَذٰلِكَ كُنْتُمْ مِّنْ قَبْلُ فَمَنَّ اللّٰهُ عَلَيْكُمْ﴾ ’’تم بھی تو پہلے ایسے ہی تھے، پھر اللہ تعالیٰ نے تم پر احسان کیا۔ ‘‘ الغرض! اس سے پہلے تم بھی اس شخص کی طرح تھے جو اپنے ایمان کو اپنی قوم سے چھپائے ہوئے تھا جیسا کہ ابھی ابھی مرفوع حدیث کے حوالے سے بیان کیا جا چکا ہے۔ اور جیسا کہ اللہ تعالیٰ نے فرمایا ہے :﴿وَاذْكُرُوْۤا اِذْ اَنْتُمْ قَلِيْلٌ مُّسْتَضْعَفُوْنَ فِي الْاَرْضِ﴾ (الأنفال:26) ’’اور (اس وقت کو) یاد کرو جب تم زمین (مکہ) میں قلیل اور ضعیف سمجھے جاتے تھے۔‘‘\nامام عبدالرزاق رحمہ اللہ نے بھی ﴿كَذٰلِكَ كُنْتُمْ مِّنْ قَبْلُ﴾ کے بارے میں سعید بن جبیر رحمہ اللہ کی روایت کو بیان کیا ہے کہ اس سے پہلے تم بھی اپنے ایمان کو اسی طرح چھپا کر رکھتے تھے جس طرح بکریوں کے اس چرواہے نے اپنے ایمان کو اپنی قوم سے چھپایا تھا۔(تفسیر عبدالرزاق : 472/1، رقم:626 اور اس میں اس واقعے کی طرف اشارہ ہے جو مذکورہ آیت کی تفسیر کی ابتدا میں بیان ہوا ہے۔) اور فرمانِ الٰہی :﴿فَتَبَيَّنُوْا١ؕ﴾ ’’تو تحقیق کر لیا کرو۔ ‘‘ یہ پہلے بیان کی گئی بات کی تاکید ہے۔ اور﴿اِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُوْنَ خَبِيْرًا۰۰۹۴﴾ ’’بے شک تم جو عمل کرتے ہو اللہ تعالیٰ کو سب کی خبر ہے۔ ‘‘کے بارے میں سیّدنا سعید بن جبیرفرماتے ہیں کہ یہ سرزنش اور وعید ہے۔(تفسیر ابن أبی حاتم : 1042/3)"],[1268,"§جنگ کے دوران قتل خطا\nابتدائے اسلام میں ’’السلام علیکم‘‘ کا لفظ مسلمانوں کے لیے شعار اور فریقین کے مسلمان ہونے کی علامت سمجھاجاتا تھا کیوں کہ اس دور میں عرب کے نو مسلموں اور کافروں کے درمیان لباس، زبان یا کسی دوسری چیز میں نمایاں امتیاز نہ تھا جس کی بنا پر ایک مسلمان سرسری طور پر دوسرے مسلمان کو پہچان سکتا ہو لیکن کافروں سے لڑائی کے دوران یہ پیچیدگی پیش آجاتی کہ جس قوم پر مسلمان حملہ آور ہوتے ان میں سے کوئی شخص السلام علیکم یا لا الہ الا اللہ کہنے لگتا جس سے مسلمانوں کو یہ مغالطہ ہوتا کہ وہ حقیقتًا مسلمان نہیں بلکہ محض اپنی جان بچانے کے لیے یہ کلمہ زبان سے ادا کر رہا ہے تو وہ اپنے اسی گمان کی بنا پر اسے قتل کر دیتے اور اس کا مال لوٹ لیتے۔ چنانچہ درج ذیل احادیث میں اسی قسم کے دو واقعات کا ذکرہے :\n1:\nسیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ ایک شخص تھوڑی سی بکریاں لیے ہوئے مسلمانوں کو ملا اور السلام علیکم کہا۔ مسلمانوں نے اسے (بہانہ خور سمجھ کر) مار ڈالا۔ اور اس کی بکریاں لے لیں (اسامہ بن زید رضی اللہ عنہ نے اسے قتل کیا) اس وقت اللہ تعالیٰ نے یہ آیت اُتاری۔ (صحیح البخاری)\n2:\nجنگ کے دوران کلمہ اسلام کہنے والے کافر کا قتل جرم عظیم ہے : سیدنا اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ہمیں حرقات (قبیلہ جہینہ) کی طرف بھیجا۔ ہم نے علی الصبح ان پر حملہ کیا اور انہیں شکست دی۔ میں اور ایک انصاری ان کے ایک آدمی سے ملے اور جب ہم نے اس پر قابو پالیا تو اس نے لا الہ الا اللہ کہا۔ اب انصاری تو اس سے رُک گیا مگر میں نے نیزہ چلادیا حتی کہ وہ مر گیا۔ جب ہم واپس آئے تو یہ بات نبی اکرم صلی اللہ علیہ وسلم کو پہنچی تو آپ صلی اللہ علیہ وسلم نے مجھے کہا:’’ اسامہ رضی اللہ عنہ ! کیا تو نے لا الہ الا اللہ کہنے کے بعد اسے قتل کیا؟‘‘ میں نے کہا:’’ یا رسول اللہ صلی اللہ علیہ وسلم! اس نے پناہ چاہنے کے لیے یہ کہا تھا۔ ‘‘آپ صلی اللہ علیہ وسلم نے پھر فرمایا:’’ کیا تو نے اسے لا الہ الااللہ کہنے کے بعد قتل کیا؟‘‘ آپ صلی اللہ علیہ وسلم یہ الفاظ کئی بار دہراتے رہے حتی کہ میں نے خواہش کی کہ میں آج سے پہلے اسلام ہی نہ لایا ہوتا۔ (صحیح البخاری)\n3:\nسیدنا عبداللہ بن عمر رضی اللہ عنہ فرماتے ہیں کہ سیدنا خالد بن ولید رضی اللہ عنہ نے (بنی ہدبہ کی جنگ میں) کافروں کو مارنا شروع کیا (حالانکہ وہ کہتے جاتے تھے کہ ہم نے دین بدلا ہم نے دین بدلا) رسول اللہ صلی اللہ علیہ وسلم نے جب یہ حال سنا تو فرمایا:’’ یا اللہ! میں خالد کے کام سے بیزار ہوں۔‘‘ (صحیح البخاری) بعض روایات میں آیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بعد میں ایسے مقتولوں کی دیت بھی بیت المال سے ادا کر دی تھی۔ اور بعض دوسری روایت میں ہے کہ آپ صلی اللہ علیہ وسلم نے سیدنا اسامہ رضی اللہ عنہ سے پوچھا کہ ’’کیا تونے اس کا دل چیر کر دیکھ لیا تھا کہ وہ محض اپنی جان بچانے کی خاطر لا الہ الا اللہ کہہ رہا ہے۔ ‘‘\n4:\nمقداد بن اسود رضی اللہ عنہ سے روایت ہے کہ میں نے آپ صلی اللہ علیہ وسلم سے پوچھا : یا رسول اللہ صلی اللہ علیہ وسلم! بھلا دیکھیے اگر میں کسی کافر سے لڑائی کرو ں اور وہ مجھ سے لڑائی کرے اور اپنی تلوار سے میرا ایک ہاتھ کاٹ دے پھر مجھ سے بچ کر ایک درخت کی اوٹ میں چلا جائے اور کہنے لگے میں اللہ تعالیٰ کے لیے اسلام لایا تو اس کے یہ کہنے کے بعد میں سے قتل کر سکتا ہوں ؟ آپ صلی اللہ علیہ وسلم نے فرمایا: اسے مت قتل کر۔ میں نے کہا یا رسول اللہ صلی اللہ علیہ وسلم! اس نے میرا ہاتھ کاٹنے کے بعد ایسا کہا تھا۔ پھر بھی میں اسے قتل نہ کروں ؟ آپ صلی اللہ علیہ وسلم نے فرمایا:’’اسے مت قتل کر اگرچہ تجھے اس سے تکلیف پہنچی۔ ورنہ وہ اس مقام پر آجائے گا جو تیرے قتل کرنے سے پہلے تیرا مقام تھا (یعنی وہ ظالم تھا اورتم حق پر تھے) اور اگر تونے کلمہ اسلام کہنے کے بعد اسے قتل کیا تو تم اس کے مقام پر آجائو گے (یعنی تم ظالم اور وہ مظلوم ہوگا)۔(صحیح مسلم)\nاس حدیث سے ضمناً یہ بھی معلوم ہوتا ہے کہ شریعت کے احکام ظاہر کے مطابق جاری ہوتے ہیں اور باطن کا معاملہ اللہ تعالیٰ کے سپرد ہے۔\nچونکہ ایسا گمان شرعی نقطہ نظر سے غلط ہے لہٰذا اللہ تعالیٰ نے اس قسم کے واقعہ کی پوری طرح چھان بین کا حکم دیا۔ تحقیق کے بغیر چھوڑ دینے میں اگر یہ امکان ہے کہ ایک کافر جھوٹ بول کر اپنی جان بچالے تو قتل کرنے میں اس کا بھی امکان ہے کہ ایک بے گناہ مومن تمہارے ہاتھ سے مارا جائے اور تمہارا ایک کافر کو چھوڑ دینے میں غلطی کرنا اس سے بدرجہا بہتر ہے کہ تم ایک مومن کو قتل کرنے میںغلطی کرو۔\nواضح رہے کہ آیت نمبر 92میں اللہ تعالیٰ نے کسی مومن کے قتل خطا کے احوال و ظروف کے لحاظ سے تین صورتیں اور ان کے کفارے کا یوں بیان فرمایا:\n1:\nمسلمان مقتول مسلمانوں ہی میں موجود ہو۔ اس کا کفارہ مسلمان غلام آزاد کرنا ہے اور دیت بھی۔ غلام نہ ملنے کی صورت میں متواتر دو ماہ کے روزے۔\n2:\nمسلمان مقتول جو غیر مسلموں میں رہتا ہو۔ اس کا کفارہ صرف مسلمان غلام آزاد کرنا یا متبادل صورت میں روزے رکھناہے اس کے وارثوں کو دیت نہیں دی جائے گی اس لیے کہ اس سے اسلام کے دشمنوں کو ہی فائدہ پہنچے گا۔\n3:\nاور اگر مسلمان مقتول ایسے غیر مسلموں سے ہو جن کے درمیان معاہدہ امن ہو چکا ہو تو اس کا کفارہ وہی ہوگا جو نمبر (1)کی صورت میں ہے۔\nاب دیکھیے ان تینوں صورتوں میں مسلمان غلام آزاد کرنا لازم قرار دیا گیا ہے وہ اس لیے کہ جس طرح اس نے بے احتیاطی سے ایک مسلمان کو مار ڈالا ہے تو اس کے کفارہ میں مسلمان غلام آزاد کرنے کا مطلب یہ ہوا، کہ مسلمان غلام کو آزاد کر دینا گویا ایک مسلمان کو زندہ کر دینے کے مترادف ہے کیوں کہ غلامی انسان کی صفت ملکیت اور آزادی کو، جسے اللہ تعالیٰ نے انسان کی فطرت میں رکھتا ہے اور یہی اس کی زندگی کا مقتضٰی ہے، زائل کرتی ہے اور اس کفارہ میں نوع انسان پر احسان بھی ہے۔ دوسری قابل وضاحت بات یہ ہے کہ قتل کی کل پانچ قسمیں ہیں :\n1:\nقتل کی پانچ اقسام: مسلمان کا قتل عمد۔ اس کی اخروی سزا یہاں مذکور ہوئی ہے اور دنیا میں اس کی سزا قصاص ہے یا اس کے متبادل دیت اور مقتول کے وارثوں کی طرف سے معافی۔\n2:\nقتل خطا جبکہ خطا سمجھنے میں ہو جیسے کسی کو کافر سمجھ کر مار ڈالے جس کا بیان اوپر گزر چکا ہے۔\n3:\nقتل خطا جب کہ خطا فعل میں ہو جیسے گولی یا تیر مار ا تو کسی شکار کو تھا او روہ لگ جائے کسی مسلمان کو جس سے اس کی موت واقع ہو جائے۔\n4:\nقتل خطا جب کہ خطا اتفاقاً واقع ہو جائے جیسے کوئی آدمی گاڑی کے نیچے آکر مر جائے۔\n5:\nقتل شبہ عمد۔ یعنی کسی شخص کی ایسی چیز سے موت واقع ہو جائے جس سے عمومًا موت واقع نہ ہوتی ہو جیسے کسی کو مُکایا چھڑی مار دی جائے جس سے وہ مر جائے۔\nان پانچ صورتوں میںپہلی صورت کے سوا باقی سب قتل خطا کے ضمن میں آتی ہیں اور ان میں قصاص نہیں دیت ہوتی ہے جو قاتل کے ان رشتہ داروں پر پڑتی ہے جو اس کے نفع و نقصان میں شریک ہوتے اور جنھیں عاقلہ کہتے ہیں اور دیت کی ادائیگی کی زیادہ سے زیادہ مدت تین سال تک ہے۔"],[1269,"§قتل اور دوسرے جرائم کی تحقیق ضروری ہے خواہ سفر ہو یا حضر\nاس آیت میں تحقیق کا حکم سفر کے ساتھ اس لیے متعلق کیا گیا ہے کہ ایسا واقعہ سفر جہاد میں ہو ا تھا ورنہ تحقیق کا حکم حضر میں بھی ایسے ہی ہے جیسے سفر میں۔ تحقیق کے بغیر کسی (السلام علیکم) کہنے والے کو جلدی سے قتل کردینے کی ایک وجہ یہ ہوسکتی ہے کہ کچھ لوٹ کا مال بھی ہاتھ لگ جائے گا۔ اللہ تعالیٰ نے فرمایا: کہ تمہارے لیے بہت سے ایسے مواقع پیش آنے والے ہیں جن سے اموال غنیمت تمہیں بکثرت حاصل ہوں گے لہٰذا لوٹ مار کی ہوس کی بنا پر ایسے کام ہر گز نہ کرو۔\n﴿لَا يَسْتَوِي الْقٰعِدُوْنَ مِنَ الْمُؤْمِنِيْنَ غَيْرُ اُولِي الضَّرَرِ وَالْمُجٰهِدُوْنَ فِيْ سَبِيْلِ اللّٰهِ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْؕ فَضَّلَ اللّٰهُ الْمُجٰهِدِيْنَ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ عَلَى الْقٰعِدِيْنَ دَرَجَةًؕ وَكُلًّا وَّعَدَ اللّٰهُ الْحُسْنٰىؕ وَفَضَّلَ اللّٰهُ الْمُجٰهِدِيْنَ عَلَى الْقٰعِدِيْنَ اَجْرًا عَظِيْمًاۙ۰۰۹۵ دَرَجٰتٍ مِّنْهُ وَمَغْفِرَةً وَّرَحْمَةًؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًاࣖ۰۰۹۶﴾\nکسی عذر کے بغیر (پیچھے) بیٹھ رہنے والے مومن اور اللہ کی راہ میں اپنے مالوں اور اپنی جانوں کے ساتھ جہاد کرنے والے برابر نہیں ہو سکتے۔ اللہ نے اپنے مالوں اور اپنی جانوں کے ساتھ جہاد کرنے والوں کو (پیچھے) بیٹھ رہنے والوں پر مرتبے میں فضیلت دی ہے۔ اور اللہ نے سب سے بھلائی کا وعدہ کیا ہے، اور اللہ نے مجاہدین کو (پیچھے) بیٹھ رہنے والوں کے مقابلے میں بہت بڑا اجر دیا ہے\nان کے لیے اللہ کی طرف سے درجے ہیں اور بخشش اور رحمت ہے۔ اور اللہ تعالیٰ بہت بخشنے والا، نہایت رحم کرنے\nوالا ہے"],[1270,"§جہاد کرنے والے اور گھروں میں بیٹھ رہنے والے برابر نہیں\nامام بخاری رحمہ اللہ نے سیّدنا براء رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ جب یہ آیت : ﴿لَا يَسْتَوِي الْقٰعِدُوْنَ مِنَ الْمُؤْمِنِيْنَ﴾ نازل ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے سیّدنا زید رضی اللہ عنہ کو بلا کر یہ آیت لکھوائی تو سیّدنا ابن ام مکتوم رضی اللہ عنہ آئے اور انہوں نے اپنے نابیناہونے کی شکایت کی، چنانچہ اللہ تعالیٰ نے ﴿غَيْرُ اُولِي الضَّرَرِ﴾ ’’کوئی عذر نہ رکھنے والے۔ ‘‘ کے الفاظ نازل فرما دیے۔ (صحیح البخاری: 4593 و صحیح مسلم: 1898)\nامام بخاری رحمہ اللہ ہی نے سیّدنا سہل بن سعد ساعدی رضی اللہ عنہما کی روایت کو بیا ن کیا ہے کہ میں نے مروان بن حکم کو مسجد میں دیکھا تو میں آکر ان کے پاس بیٹھ گیا، انہوں نے بیان کیا کہ سیّدنا زید بن ثابت رضی اللہ عنہ نے انہیں یہ خبر دی تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے لکھوایا: ’’مسلمانوں میں سے بیٹھ رہنے والے، اللہ تعالیٰ کے رستے میں لڑنے والوں کے برابر نہیں ہو سکتے۔ ‘‘ اور آ پ صلی اللہ علیہ وسلم جس وقت لکھوا رہے تھے عین اسی وقت ابن ام مکتوم رضی اللہ عنہ آئے اور عرض کرنے لگے : اے اللہ کے رسول صلی اللہ علیہ وسلم ! اگر مجھے جہاد کرنے کی استطاعت ہوتی تو میں بھی ضرو ر جہاد کرتا۔ انہوں نے یہ اس لیے عرض کی کہ وہ نابینا تھے، چنانچہ اسی وقت اللہ تعالیٰ نے رسول اللہ صلی اللہ علیہ وسلم پر وحی کا نزول شروع فرما دیا، اس وقت آپ صلی اللہ علیہ وسلم کی ران مبارک میری ران پر تھی، مجھے اس قدر بوجھ محسوس ہوا کہ میں ڈرنے لگا کہ کہیں میری ران ہی نہ ٹوٹ جائے، جب وحی کی کیفیت ختم ہوئی (تو معلوم ہوا کہ) اللہ تعالیٰ نے اس آیت میں یہ الفاظ بھی نازل فرما دیے ہیں :﴿غَيْرُ اُولِي الضَّرَرِ﴾ ’’کوئی عذر نہ رکھنے والے۔‘‘ (صحیح البخاری: 2832) اس روایت کو (اسی سند سے) صرف امام بخاری رحمہ اللہ نے بیان کیا ہے، امام مسلم رحمہ اللہ نے نہیں۔ (صحیح مسلم : 1898)\nپہلے یہ حکم مطلق تھا کہ ﴿لَا يَسْتَوِي الْقٰعِدُوْنَ مِنَ الْمُؤْمِنِيْنَ﴾ لیکن جب ﴿غَيْرُ اُولِي الضَّرَرِ﴾ کے الفاظ بذریعہ وحی نازل ہو گئے تو اس سے ان لوگوں کو مستثنیٰ قرار دے دیا گیا جو نابینا پن، لنگڑا پن یا مرض وغیرہ کے ایسے عذر رکھتے ہوں جن کی وجہ سے ان کے لیے جہاد میں شریک نہ ہونے کی اجازت ہے جیسا کہ صحیح بخاری میں سیّدنا انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مدینہ میںرہنے کے باوجود کچھ ایسے لوگ بھی ہیں کہ تم نے جس قدر بھی سفر کیا اور جتنی وادیوں کو بھی طے کیا وہ تمہارے ساتھ تھے۔ صحابہ کرام رضی اللہ عنہم نے عرض کی: اے اللہ کے رسول صلی اللہ علیہ وسلم ! وہ تو مدینہ میں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:(ہاں) اگرچہ وہ مدینہ میں ہیں لیکن انہیں عذر نے جہا دمیں شرک سے روکا ہے۔ ‘‘\n(صحیح البخاری :4423 و صحیح مسلم :1911)\nاور فرمانِ الٰہی :﴿وَكُلًّا وَّعَدَ اللّٰهُ الْحُسْنٰىؕ﴾ ’’اور اللہ تعالیٰ کا نیک وعدہ سب کے لیے ہے۔ ‘‘یعنی جنت او ربے پایاں اجر و ثواب کا وعدہ۔ اور یہ آیت کریمہ اس بات کی بھی دلیل ہے کہ جہادِفرض عین نہیں بلکہ فرضِ کفایہ ہے۔ پھر اللہ تعالیٰ نے فرمایا ہے :﴿وَفَضَّلَ اللّٰهُ الْمُجٰهِدِيْنَ عَلَى الْقٰعِدِيْنَ اَجْرًا عَظِيْمًاۙ۰۰۹۵﴾ ’’اور اللہ تعالیٰ نے جہاد کرنے والوں کو بیٹھ رہنے والوں کے مقابلے میں اجرِ عظیم کے لحاظ سے فضیلت دی ہے۔ ‘‘ پھر فرمایا: کہ یہ فضیلت جنت کے بلند و بالا اور ارفع و اعلیٰ بالا خانوں، گناہوں اور لغزشوں کی مغفرت اور اللہ تعالیٰ کی طرف سے نازل ہونے والی رحمتوں اور برکتوں کی صورت میں ہوگی، چنانچہ ارشاد فرمایا:﴿دَرَجٰتٍ مِّنْهُ وَمَغْفِرَةً وَّرَحْمَةًؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًاࣖ۰۰۹۶﴾ ’’(ان کے لیے) اللہ تعالیٰ کی طرف سے درجے ہیں اور بخشش اور رحمت ہے۔ اور اللہ تعالیٰ بڑا بخشنے والا (اور) مہربان ہے۔ ‘‘\nصحیح بخاری و مسلم میں سیّدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یقیناً جنت میں سو(100) درجے ہیں جنھیں اللہ تعالیٰ نے اپنے رستے میں جہاد کرنے والوں کے لیے تیار فرما رکھا ہے جب کہ ان میں سے ہر دو(2) درجوں کے درمیان اس قدر فاصلہ ہے جتنا آسمان اور زمین کے مابین ہے۔ ‘‘\nاس آیت میں مجاہدین کے لیے جو اجرِ عظیم ہے اسی کی تفصیل ہے۔ بخاری و مسلم نے ابو سعید خدری رضی اللہ عنہ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جنت میں سو (100)درجے ہیں، جنھیں اللہ تعالیٰ نے مجاہدین کے لیے تیار کیا ہے، ہر دو درجوں کے درمیان آسمان اور زمین کی مسافت ہے۔ ‘‘\nعلماء نے اسی آیت ِ جہاد سے استدلال کرکے کہا ہے کہ جہاد فرض عین نہیں ہے، اگر فرض عین ہوتا تو پھر بیٹھنے والوں کے لیے کسی فضیلت کا ذکر نہ ہوتا۔ آیت میں اس بات کی بھی دلیل ہے کہ جہاد ان تمام اعمال سے افضل ہے جو جہاد میں شرکت نہ کرنے والے لوگ کرتے رہتے ہیں۔ سیوطی رحمہ اللہ نے ’’الإکلیل‘‘ میں لکھا ہے کہ اس آیت میں مجاہدین کو تمام دوسرے لوگوں پر فضیلت دی گئی ہے، اور یہ بھی بیان کر دیا گیا ہے جو لوگ واقعی جہاد میں شرکت کرنے سے معذور ہوتے ہیں ان کا درجہ بھی مجاہدین ہی کا ہے۔\nاس آیت کے شان نزول کے بارے میں میں درج ذیل حدیث ملاحظہ فرمایے : براء بن عازب رضی اللہ عنہ کہتے ہیں کہ جب یہ آیت ﴿لَا يَسْتَوِي الْقٰعِدُوْنَ مِنَ الْمُؤْمِنِيْنَ﴾ اتری تو آپ صلی اللہ علیہ وسلم نے زید بن ثابت رضی اللہ عنہ کو بلایا انہوں نے یہ آیت لکھی۔ اتنے میں ابن اُم مکتوم رضی اللہ عنہ آئے اور شکوہ کیاکہ میں تو اندھا ہوں (میرا کیا قصور؟) اس وقت اللہ تعالیٰ نے غیر اولی الضرر کے الفاظ نازل فرمائے۔ (صحیح البخاری)\nگویا اللہ نے سیدنا عبداللہ رضی اللہ عنہ بن اُم مکتوم کے عذر کو قبول فرما لیا لیکن اس رخصت کے باوجود آپ رضی اللہ عنہ کا جذبہ جہاد اتنا بلند تھا کہ نابینا ہونے کے باوجود آپ رضی اللہ عنہ مشقت اُٹھا کر بھی کئی غزوات میں شریک ہوئے۔ سیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ اس آیت کا مطلب یہ ہے کہ جو مسلمان جنگ بدر میں شریک ہوئے اور جو نہیں ہوئے یہ دونوں برابر نہیںہو سکے۔ (حوالہ ایضاً)"],[1271,"§جہاد فرض عین نہیں\nاس آیت سےمعلوم ہواکہ جہاد فرض عین نہیں اور اس کے کئی پہلو ہیں: ایک تویہ ہے کہ معاشرہ میں کئی افرادبوڑھے، ناتواں، کمزو ر، اندھے، لنگڑے، لولے، بیمار وغیرہ ہوتے ہیں جو جہاد پر جا ہی نہیں سکتے۔ جیسا کہ حدیث بالا سے ظاہر ہے۔ دوسرا پہلو یہ ہے کہ کچھ لوگ ملک کے اندرونی دفاع، مجاہدوں کے گھروں کی حفاظت، ان کے اہل و عیال کی دیکھ بھال کے لیے بھی ضرور پیچھے رہنے چاہئیں۔ اور اس لیے بھی کہ مجاہدین کو بروقت کمک مہیا کرتے رہیں، خواہ یہ رسد اور سامان خورو و نوش سے متعلق ہو یا افرادی قوت سے۔ پھر کچھ لوگ زخمیوں کی دیکھ بھال کے لیے بھی ضروری ہوتے ہیں اور ایسے سب لوگ بھی درجہ بدرجہ جہاد میں شامل سمجھے جاتے ہیں۔ جیسا کہ درج ذیل حدیث سے واضح ہے :"],[1272,"§جہاد سے معذور لوگ\nسیدنا انس رضی اللہ عنہ کہتے ہیں کہ رسول اکرم صلی اللہ علیہ وسلم جب غزوۂ تبوک سے واپس ہوئے اور مدینہ کے قریب پہنچے تو فرمایا:’’ مدینہ میں کچھ ایسے لوگ ہیں کہ جب تم کوئی سفر کرتے ہو یا کوئی وادی طے کر تے ہو تو وہ تمہارے ساتھ ہوتے ہیں ‘‘ صحابہ رضی اللہ عنہم نے پوچھا :’’ باوجود اس کے کہ وہ مدینہ میں ہوتے ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ ہاں ! یہ وہ لوگ ہیں جنھیں کسی عذر نے روک لیا ہے۔ ‘‘ (صحیح البخاری، صحیح مسلم)\nجہا دکے فرض عین نہ ہونے پر یہ آیت بھی دلالت کرتی ہے :﴿وَمَا كَانَ الْمُؤْمِنُوْنَ لِيَنْفِرُوْا كَآفَّةًؕ﴾ (التوبۃ:122) ’’(مومنوں کے لیے ممکن ہی نہیں کہ سب کے سب نکل کھڑے ہوں)‘‘ اور آج کل تو حکومتوں نے محکمہ دفاع ہی الگ بنا رکھاہے۔البتہ اگر ایک اسلامی حکومت جہاد کا اعلان کرکے عام لوگوں کو جہاد کے لیے کہے تو اس صورت میں عام لوگوں پر بھی جہاد فرض ہو جائے گا لیکن پھر بھی یہ فرض کفایہ ہی ہوگا۔ فرض عین نہیں ہوگا۔ تاہم جہاد ایک اہم فرض کفایہ ہے جس سے غفلت کا نتیجہ قوم کی موت کی صورت میں نکلتا ہے اوریہ تا قیامت جاری رہے گا۔"],[1273,"§مجاہدین کے درجے\nدوسری بات جو اس آیت سے معلوم ہوتی ہے وہ یہ ہے کہ اللہ تعالیٰ کی راہ میں جان و مال سے جہاد کرنے والوں کے ہی دوسروں کی بہ نسبت درجات بلند ہوتے ہیں اور وہی اجر عظیم کے مستحق ہوتےہیں۔ کیوں کہ جان اور مال سے ہی انسان کو سب سے زیادہ محبت ہوتی ہے پھر جس نے اللہ تعالیٰ کی راہ میں ان دونوں چیزوں کی قربانی دے دی اس سے بڑھ کر کس کا درجہ ہو سکتا ہے۔ چنانچہ سیدنا ابو سعید خدری رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا ’’ لوگوں میں سب سے افضل کون ہے ؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ جو اللہ کی راہ میں اپنی جان اور مال سے جہاد کرے۔ ‘‘ (صحیح البخاری) اور سیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ جنت میں سو درجے ہیں جنھیں اللہ تعالیٰ نے مجاہدین فی سبیل اللہ کے لیے تیار کیا ہے اور ہر درجہ کے درمیان اتنا فاصلہ ہے جتنا زمین و آسمان کے درمیان ہے۔‘‘ (صحیح البخاری)"],[1274,"§صوفیاء کا جہاد اصغر اور جہاد اکبر کا نظریہ\nاس مقام پر ایک عوامی عقیدہ کا جائزہ لینا ضروری معلوم ہوتا ہے جس کا صوفیاء کے طبقہ نے ریاضت و مجاہدہ کی فضیلت ثابت کرنے کے لیے خوب خوب پرچار کیا ہے اور وہ عقیدہ یہ ہے کہ جہاد بالسیف جہاد اصغر ہے اور نفس سے جہاد کرنا جہاد اکبر ہے اور جہاد اصغر سے جہاد اکبر بہتر ہے۔ اس سلسلہ میں اس حدیث کا سہارا لیاجاتا ہے: «وَالْمُجَاهِدْ مَنْ جَاهَدَ نَفْسَهُ فِيْ طَاعَةِ اللهِ» مجاہد وہ ہے جو اللہ تعالیٰ کی اطاعت میں اپنے نفس سے جہاد کرے۔ اس حدیث میں فی طاعۃ اللہ کے الفاظ اس گمان باطل کو رد کرنے کے لیے کافی ہیں۔ کیوں کہ ان کے ریاضت و مجاہدہ میں بے شمار ایسی چیزیں ہیں جو صریحًا کتاب و سنت کے خلاف ہیں مثلاً ترک نکاح، چلے کاٹنا اور اپنے جسم کی تعذیب اور اسے مختلف طریقوں سے مضمحل کرکے کمزور بنانا وغیرہ اور حقیقت یہ ہے کہ ان کے ایسے کام مجاہدہ نفس نہیں بلکہ نفس کشی ہوتی ہے اور فی طاعۃ اللہ کے بجائے فی معصیۃ اللہ ہوتی ہے اور اللہ تعالیٰ کی اطاعت اور اسلامی نقطہ نگاہ سے ان چیزوں کا دور کا بھی تعلق نہیں۔ یہ حدیث بیہقی نے شعب الایمان میں فضالہ سے روایت کی ہے کہ جس کے پورے الفاظ یہ ہیں ’’ اور مجاہد وہ ہے جس نے اللہ تعالیٰ کی اطاعت میں اپنے نفس سے جہاد کیا او رمہاجر وہ ہے جس نے چھوٹے اور بڑے گناہوں کو چھوڑا۔‘‘ ظاہر ہے کہ اس حدیث میں جہاد اور ہجرت کے اس پہلو پر روشنی ڈالی گئی ہے جس طرف ذہن عمومًا منتقل نہیں ہوتا۔ بتایا یہ گیا ہے کہ جہاد اور ہجرت کا ایک پہلو یہ بھی ہے۔ ورنہ جس طرح ہجرت وہی ہے جو مسلمانوں نے فتح مکہ سے پہلے کی ہے یا ایسے حالات میں مسلمان اعلائے کلمۃ اللہ کے لیے کریں۔ اسی طرح جہاد حقیقتًا وہی ہے جسے جہاد بالسیف کہاجاتا ہے اور ان دونوں میں زمین آسمان کا فرق ہے۔\nاس آیت میں صوفیاء کے اس نظریہ کی پرزور تردید موجود ہے۔ اللہ تعالیٰ نے اس آیت میں دوبارہ فرمایا: کہ جو لوگ اپنی جانوں اور اپنے اموال سے اللہ تعالیٰ کی راہ میں جہاد کرتے ہیں وہ بیٹھنے والوں سے افضل ہیں اور یہ تو ظاہر ہے کہ نفس سے خواہ کوئی کس انداز سے مجاہدہ کرے وہ بیٹھنے والوں میں ہی شامل رہے گا۔ مجاہدین فی سبیل اللہ میں شامل نہیں ہو سکتا۔ علاوہ ازیں ارشادات نبوی صلی اللہ علیہ وسلم سے بھی یہی بات صراحت سے ثابت ہوتی ہے کہ جہاد کو آپ صلی اللہ علیہ وسلم نے افضل الاعمال قرار دیا ہے۔\nصوفیاء نے اپنے اس نظریہ کو درست ثابت کرنے کے لیے ایک موضوع حدیث بھی گھڑ رکھی ہے جو یہ ہے کہ آپ صلی اللہ علیہ وسلم نے ایک دفعہ جہاد سے واپسی پر فرمایا: کہ «رَجَعْنَا مِنَ الْجِهَادِ الْاَصْغَرِ اِلَى الْجِهَادِ الْاَكْبَرِ» ہم چھوٹے جہاد (یعنی جہاد بالسیف) سے بڑے جہاد (یعنی جہاد بالنفس) کی طرف لوٹ آئے ہیں۔\nاس حدیث کے متعلق مولانا حسین احمد مدنی کہتے ہیں کہ صوفیاء اس کو حدیث کہتے ہیں لیکن امام عسقلانی رحمہ اللہ کہتے ہیں کہ امام نسائی رحمہ اللہ نے اسے ابراہیم بن عیلہ رحمہ اللہ کا قول بتایا ہے۔ الفاظ کی رکاکت زبردست قرینہ ہے کہ یہ نبی اکرم صلی اللہ علیہ وسلم کا قول نہیں ہو سکتا۔شاہ عبدالعزیز جیسے معتبر محدث نے کہا ہے: ایسی احادیث کا فیصلہ محدثین کے اصول و قواعد کی رُو سے کیا جائے گا بیچارے صوفیاء جن پر حسن ظن کا غلبہ رہتا ہے۔ ان حضرات کو تنقید و تفتیش کی فرصت کہاں؟ ان کے حسن ظن سے کسی قول کا حدیث رسول ہونا تو ثابت نہیں ہو جائے گا۔ ‘‘(مکتوبات شیخ الاسلام 307،308 بحوالہ اسلامی تصوف یوسف سلیم چشتی،ص: 123)\nصوفیاء کے اس نظریہ نے مسلمانوں کو جتنا نقصان پہنچایا شاید ہی کسی اور وجہ سے پہنچا ہو اس نظریہ نے مسلمانوں سے جہاد کی روح کو ختم کرکے دنیا میں ذلیل اور رسوا بنا دیا اور ایسے افعال سے مجاہدہ نفس شروع کیا جس سے انسانیت کو بھی شرم آنے لگے۔ دسویں صدی ہجری کے اواخر تک اس نظریہ نے مسلمانوں کو اس قدر مفلوج، کاہل اور بے فہم بنا دیا تھا کہ فرانسیسی فاتحین کے حملوں کادفاع جامعہ ازہر میں بیٹھ کر اوراد و وظائف کے ذریعے کر رہے تھے۔ نابلیوں کا انتخاب کرکے انہیں صوفیاء کی گودڑی پہنائی گئی اور اس کی رہنمائی میں ذکر و فکر کی مجالس قائم کی گئیں۔ بخاری شریف کا ختم بھی کرایا گیا۔ لیکن ان سب باتوں کا کچھ بھی فائدہ نہ ہوا اور مسلمان مار ہی کھاتے رہے۔ بالآخر جب مسلمان مجاہدین نے یورپ کی سرزمین میں لوگوں سے جنگیں کیں تب جا کر حالات نے پلٹا کھایا۔ (مقدمہ الفکر الصوفی،ص:6)\nاس گوشہ نشینی کا جو اثر ان صوفیاء کی ذات پر مترتب ہوتا ہے وہ ابو بکر شبلی کی زبانی ملاحظہ فرمائیے۔ روایت ہے کہ کچھ عرصہ شبلی اپنے مقام سے غائب رہے۔ ہر چند تلاش کیا پتہ نہ چلا۔ ایک روز مخنثوں کے گروہ میں دیکھے گئے۔ لوگوں نے پوچھا اے شیخ! یہ کیا بات ہے؟ فرمایا: یہ گروہ (صوفیاء) دنیا میں نہ مرد ہیں نہ عور ت۔ میں بھی اسی حالت میں گرفتار ہوں نہ مرد ہوں نہ عورت پس ناچار میری جگہ انہی میں ہے۔ ‘‘(خزینۃ الاصفیاء،ص:147)"],[1275,"§شیخ جنید کے مریدوں کا جہاد بالسیف\nشبلی کے پیرو مر شد جنید بغدادی کے مریدوں کو ایک دفعہ جہاد بالسیف کا شوق چرایا یہ داستان اس طرح ہے کہ ’’شیخ جنید کے آٹھ مرید تھے جو سب کے سب کامل واکمل تھے۔ ایک روز انہوں نے خدمت شیخ میں عرض کی کہ اے شیخ ! شہادت ایک عجیب نعمت جان فزا ہے اس لیے شہادت کے لیے جہاد کرنا چاہیے شیخ نے ان کی تائید کی اور ان کے ساتھ ملک روم کی طرف جہاد کے لیے چل پڑے۔ ایک جگہ کفار سے مقابلہ ہوگیا۔ ایک گبر (آتش پرست) کے ہاتھوں شیخ کے آٹھوں مرید ایک ایک کرکے شہید ہو گئے۔ شیخ فرماتے ہیں کہ میں نے اس وقت ہوا میں نو کجاوے معلق دیکھے۔ میرے ساتھیوں میں سے جو شہید ہوتا تھا، اس کی روح ایک کجاوے میں رکھتے اور آسمان کی طرف لے جاتے۔ آخر ایک کجاوہ باقی رہ گیا۔ میں سمجھ گیا کہ یہ کجاوہ میرے لیے ہے اور جنگ میں مشغول ہو گیا۔ دورانِ جنگ وہی گبر جس نے میرے ساتھیوں کو شہید کیا تھا میرے پاس آیا اور کہا: ابو القاسم ! یہ آخری کجاوہ میرے لیے ہے۔ توواپس بغداد چلا جا اور اپنی قوم کی قیادت و سیادت کر اور اپنا مذہب میرے سامنے پیش کر۔ میں نے اسے تلقین کی وہ مسلمان ہوا اور کفار سے لڑتا ہوا شہید ہو گیا۔ میں نے دیکھا کہ اس آخری کجاوے میں اس کی روح کو آسمان کی طرف لے گئے ہیں۔ (خزینۃ الاصفیاء،ص:142)"],[1276,"§جہادِ اکبر کے اس نظریہ کے اثرات\nخزینۃ الاصفیاء کی اس روایت سے درج ذیل نتائج سامنے آتے ہیں :\n1:\nاللہ تعالیٰ نے ابتدا ًایمان کا یہ معیار بتایا تھا کہ ایک مومن دس کافروں پر غالب ہونا چاہیے۔ بعد ازاں اس میں تخفیف کرکے یہ معیار مقرر ہوا کہ کم ازکم ایک مومن کو دو کافروں پر ضرور بھاری ہونا چاہیے۔ مگر یہاں یہ صورت حال ہے کہ شیخ جنید کے آٹھ کامل واکمل مرید ایک کافر کے ہاتھوں شہید ہو رہے ہیں چاہیے تو یہ تھا کہ اگر انہیں شہادت کا اتنا ہی شوق تھا تو بیس پچیس کافروں کو مار کر خود شہید ہوتے۔ مگر یہ سب ایک کافر کے ہاتھوں یوں مارے جا رہے ہیں جیسے قصاب بکروں کو ذبح کرتا ہے۔ اب اللہ تعالیٰ کے بیان کردہ معیار کے مطابق ان میں ایمان کا جتنا حصہ تھا اوہ آپ خود ہی اندازہ فرما لیجئے۔ یہی وہ قباحت ہے جس کی بنا پر اسلام نے رہبانیت یا طریقت کو مذموم قرار دیا۔\n2:\nشیخ جنید بغدادی کو خود اپنی شہادت کا بھی خطرہ لاحق ہو چلا تھا۔ وہ تو خیرت گزری کہ اس گبر کا نور فراست شیخ جنید کے نور فراست سے زیادہ تھا اور اس گبر کو شیخ جنید سے پہلے معلوم ہو گیا کہ نواں کجاوہ شیخ کے لیے نہیں بلکہ میرے لیے ہے۔\n3:\nاسلام لانے کا یہ بھی کیسا انوکھا طریقہ ہے کہ کافر خود کسی مسلمان کو کہے کہ میرے سامنے اسلام پیش کرتاکہ میں اسلام لائوں۔ بہر حال ولایت کی دنیا الگ ہے اور بمصداق ’’رموز مملکت خویش خسرواں دانند ‘‘ یہ بات بھی تسلیم کر ہی لینی چاہیے۔\n4:\nالبتہ اس بات کی سمجھ نہیں آئی کہ روم تو سارا عہد فاروقی اور عہد عثمانی میں فتح ہو چکا تھا اور شیخ جنید کے زمانہ میں بغداد سے لے کرروم تک سارا علاقہ اسلامی مملکت میں شامل تھا تو روم کے راستے میںان کو کفارکا لشکر کہاں ملا تھا ؟\n5:\nاس قصہ سے بہر حال یہ ضرور معلوم ہوجاتا ہے کہ صوفیاء کے اس ’’نظریہ جہاد اکبر‘‘ کے نظریہ نے مسلمانوں کو کس قدر نقصان پہنچایا ہے۔"],[1277,"§جنت میں داخلہ کے لیے جہاد شرط نہیں\nتیسری بات اس آیت سے یہ معلوم ہوئی کہ جنت میں داخلہ کے لیے جہاد لازمی شرط نہیں ہے بلکہ توحید پر ثابت قدم رہنے والے اور دوسرے احکام الٰہی بجالانے والے مسلمان بھی جنت میں ضرور جائیں گے اگرچہ ان کے درجات مجاہدین فی سبیل اللہ سے کم ہوں گے۔\nجب یہ آیت نازل ہوئی کہ اللہ تعالیٰ کی راہ میں جہاد کرنے والے اور گھروں میں بیٹھ رہنے والے برابر نہیں تو سیّدنا عبداللہ بن ام مکتوم رضی اللہ عنہ (نابینا صحابی) وغیرہ نے عرض کیا کہ ہم تو معذور ہیں جس کی وجہ سے ہم جہاد میں حصہ لینے سے مجبور ہیں۔ مطلب یہ تھا کہ گھر میں بیٹھ رہنے کی وجہ سے جہا دمیں حصہ لینے والوں کے برابر ہم اجر و ثواب حاصل نہیں کر سکیں گے درآں حالیکہ ہمارا گھر میں بیٹھ رہنا بطور شوق، یا جان کی حفاظت کے نہیں ہے بلکہ عذر شرعی کی وجہ سے ہے۔ اس پر اللہ تعالیٰ نے ﴿غَيْرُ اُولِي الضَّرَرِ﴾ ’’بغیر عذر کے ‘‘ کا استثنا ء نازل فرما دیا یعنی عذر کے ساتھ بیٹھ رہنے والے،مجاہدین کے ساتھ اجر میں برابر کے شریک ہیں کیوں کہ حَبَسَهُمُ الْعُذْرُ. ’’ان کو عذرنے روکا ہوا ہے۔‘‘ (صحیح البخاری)\n﴿وَلَوْ لَا دَفْعُ اللّٰهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ لَّفَسَدَتِ الْاَرْضُ﴾ (البقرۃ:251) ’’اگر اللہ تعالیٰ بعض لوگوں کی جانب سے مدافعت نہ فرماتا تو روئے زمین کا امن و امان غارت ہو جاتا۔‘‘\nیعنی طاغوتی قوتوں کے سبب اہل زمین فساد انگیزی کے سبب اپنا چین و آرام کھو بیٹھتے ہیں۔ ذہن نشین کریں کہ استطاعت کے ہوتے ہوئے جہاد نہ کرنا قابل مذمت ہے اور بخل کا آئینہ دار ہے البتہ کسی عذر کے سبب جیسے کہ ایک شخص بصارت سے محروم ہے یا معذور ہے چلنا پھر نا ممکن نہیں یا ایسا مریض ہے جس میں وہ خوددوسروں کا محتاج ہے تو انہیں مستثنیٰ کیا گیاہے۔ امام بخاری رحمہ اللہ نے اس آیت مبارکہ کے عنوان پر باب کا انعقاد کیا ہے اس کے ضمن میں تین احادیث ذکر کی ہیں پہلی حدیث میں زید بن ثابت رضی اللہ عنہ نے مروان کو بتایا کہ رسول اکرم صلی اللہ علیہ وسلم نے قرآن پاک کی تسوید کے موقع پر جب اس آیت مبارکہ کو تحریر فرمانے کا حکم دیا تو اس دوران ﴿غَيْرُ اُولِي الضَّرَرِ﴾ آنکھوں سے محروم انسان مستثنیٰ ہیں ابھی نازل نہ ہوئی تھی آپ صلی اللہ علیہ وسلم کے تحریر کروانے کے دوران عبداللہ بن اُم مکتوم رضی اللہ عنہ نابینا صحابی آئے اس نے عرض کیا اے اللہ کے رسول صلی اللہ علیہ وسلم! اللہ کی قسم ! اگر مجھ میں جہاد کی استطاعت ہوتی تو میں ضرور جہاد کے لیے نکلتا اس دوران اللہ تعالیٰ کے پیغمبر پر ﴿غَيْرُ اُولِي الضَّرَرِ﴾ ”معذور مستثنیٰ ہیں “نازل ہوئی آپ صلی اللہ علیہ وسلم کی ران میری ران پر تھی مجھ پر اتنا بوجھ پڑا کہ مجھے خطرہ لاحق ہو گیا کہیں میری ران ٹوٹ نہ جائے کچھ عرصہ بعد وحی کی کیفیت ختم ہو گئی۔ (فتح الباری : 259/8، صحیح البخاری)\nحافظ ابن کثیر رحمہ اللہ فرماتے ہیں کہ جب نابینا شخص مستثنیٰ ہے تو ہاتھ پائوں سے معذور اور بیمار لوگ بھی مستثنیٰ ہوں گے ان کو مجاہدین کے برابر ثواب حاصل ہوگا۔ (ابن کثیر : 820/1)\nنیز صحیح البخاری میں انس رضی اللہ عنہ سے روایت ہے آپ صلی اللہ علیہ وسلم نے فرمایا مدینہ طیبہ میںکچھ ایسے لوگ ہیں کہ تم جہاں کہیں سفر کرکے جاتے ہو یا تم کسی وادی کو عبور کرتے ہو تو وہ تمہارے ساتھ ہوتے ہیں یعنی ثواب میں برابر شریک ہیں اور دراصل انہیں عذر نے روک رکھاہے جب کہ اللہ پاک نے ہر ایک کے ساتھ جنت کا وعدہ فرمایا ہے معلوم ہوا جہاد فرض کفایہ ہے۔\n(صحیح البخاری، مسند احمد)\n﴿فَضَّلَ اللّٰهُ الْمُجٰهِدِيْنَ﴾ البتہ مجاہدین کو گھر میں بیٹھنے والو ں پر فضیلت ہے وہ اونچے محلات میں ہوں گے ان کے تمام گناہ اور لغزشیں معاف کر دی جائیں گی ان پر اللہ تعالیٰ کی مغفرت و رحمت سایہ افگن ہوگی۔ بخاری و مسلم میں ابو سعید خدری رضی اللہ عنہ سے حدیث مروی ہے ارشاد نبوی صلی اللہ علیہ وسلم ہے جنت کے سو (100) درجات ہیں جن کو اللہ تعالیٰ نے مجاہدین کے لیے تیار کر رکھا ہے ہر دو درجہ کے درمیان اتنا فاصلہ ہے جتنا کہ آسمان اور زمین کے درمیان فاسلہ ہے۔\n(صحیح البخاری، کتاب التوحید،ص:1555)\nنیز عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں آپ صلی اللہ علیہ وسلم نے فرمایا جس شخص نے اللہ تعالیٰ کی راہ میں تیر پھینکا اس کو ایک درجہ ثواب ہے ایک شخص نے استفسار کیا درجہ کیا ہے آپ صلی اللہ علیہ وسلم نے فرمایا درجہ سے مقصود گھر کی دہلیز نہیں بلکہ ہر دو (2) درجات کے درمیان ایک صد (100) سال کا فاصلہ ہے۔ (تفسیر ابن کثیر: 821/1، مسند احمد:2354)\nبوجہ عذر کے جہاد میں نہ شرکت کرنے والوں کی فضیلت میں انس رضی اللہ عنہ سے مروی ایک حدیث ملاحظہ فرمائیں : رسول اکرم صلی اللہ علیہ وسلم غزوۂ تبوک سے واپس لوٹے جب مدینہ کے قریب پہنچے تو آپ صلی اللہ علیہ وسلم نے فرمایا مدینہ میں کچھ لوگ ایسے ہیں تم نے جہاں کہیں سفر کیا ہے جس وادی کوعبور کیا ہے تو وہ تمہارے ساتھ تھے۔ صحابہ کرام رضی اللہ عنہم نے عرض کیااے اللہ کے رسول صلی اللہ علیہ وسلم! وہ تو مدینہ میں قیام پذیر رہے ہیں آپ صلی اللہ علیہ وسلم نے فرمایا ہاں وہ مدینہ میں ہی رہے ہیں لیکن عذر نے انہیں روک رکھاہے۔\n(صحیح، ابوداؤد)\n﴿اِنَّ الَّذِيْنَ تَوَفّٰىهُمُ الْمَلٰٓىِٕكَةُ ظَالِمِيْۤ اَنْفُسِهِمْ قَالُوْا فِيْمَ كُنْتُمْؕ قَالُوْا كُنَّا مُسْتَضْعَفِيْنَ۠ فِي الْاَرْضِؕ قَالُوْۤا اَلَمْ تَكُنْ اَرْضُ اللّٰهِ وَاسِعَةً فَتُهَاجِرُوْا فِيْهَاؕ فَاُولٰٓىِٕكَ مَاْوٰىهُمْ جَهَنَّمُؕ وَسَآءَتْ مَصِيْرًاۙ۰۰۹۷ اِلَّا الْمُسْتَضْعَفِيْنَ مِنَ الرِّجَالِ وَالنِّسَآءِ وَالْوِلْدَانِ لَا يَسْتَطِيْعُوْنَ۠ حِيْلَةً وَّلَا يَهْتَدُوْنَ سَبِيْلًاۙ۰۰۹۸ فَاُولٰٓىِٕكَ عَسَى اللّٰهُ اَنْ يَّعْفُوَ عَنْهُمْؕ وَكَانَ اللّٰهُ عَفُوًّا غَفُوْرًا۰۰۹۹ وَمَنْ يُّهَاجِرْ فِيْ سَبِيْلِ اللّٰهِ يَجِدْ فِي الْاَرْضِ مُرٰغَمًا كَثِيْرًا وَّسَعَةًؕ وَمَنْ يَّخْرُجْ مِنْۢ بَيْتِهٖ مُهَاجِرًا اِلَى اللّٰهِ وَرَسُوْلِهٖ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ اَجْرُهٗ عَلَى اللّٰهِؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًاࣖ۰۰۱۰۰﴾\nجن لوگوں کی اس حالت میں فرشتے جان قبض کرتے ہیں کہ وہ (جان بوجھ کر کافروں میں رہ کر) اپنی جانوں پر ظلم کرتے رہے ہوں، تو فرشتے پوچھتے ہیں کہ تم کس حال میں تھے؟ وہ کہتے ہیں: ہم زمین میں کمزور تھے۔ تب فرشتے کہتے ہیں: کیا اللہ کی زمین وسیع نہ تھی کہ تم اس میں ہجرت کر جاتے؟ چنانچہ یہی لوگ ہیں جن کا ٹھکانا جہنم ہے اور وہ بہت برا ٹھکانہ ہے\nمگر وہ مرد، عورتیں اور بچے جو واقعی بے بس ہوں اور وہ اس جگہ سے نکلنے کا کوئی وسیلہ اور کوئی راستہ نہیں پاتے\nاس لیے ان لوگوں کے بارے میں امید ہے کہ اللہ انہیں معاف کر دے گا، اور اللہ بہت معاف کرنے والا، نہایت بخشنے والا ہے\nاور جو شخص اللہ کی راہ میں ہجرت کرے وہ زمین میں پناہ لینے کے لیے بہت جگہ اور گنجائش پائے گا۔ اور جو شخص اللہ اور اس کے رسول کی طرف ہجرت کرنے کی خاطر اپنے گھر سے نکلے، پھر اسے راستے میں موت آ جائے تو اس کا اجر اللہ کے ذمے واجب ہو گیا۔ اور اللہ نہایت\nبخشنے والا، بہت رحم کرنے والا ہے"],[1278,"§ہجرت کی استطاعت رکھنے والوں کے لیے مشرکوں میں رہنے کی ممانعت\nامام بخاری رحمہ اللہ نے ابو اسود محمد بن عبدالرحمٰن رحمہ اللہ کی روایت کو بیان کیا ہے کہ اہل مدینہ کی طرف سے ایک لشکر (اہل شام سے جنگ کرنے کے لیے) بھیجنے کا فیصلہ کیا گیا اور اس میں میرا نام بھی لکھا گیا تو میں نے عکرمہ مولیٰ ابن عباس رضی اللہ عنہما سے ملاقات کرکے انہیں یہ بات بتائی تو انہوں نے مجھے اس سے سختی سے منع کر دیا۔ اور انہوں نے سیّدنا ابن عباس رضی اللہ عنہما کے حوالے سے بیان فرمایا: کہ کچھ مسلمان مشرکوں کے ساتھ تھے اور وہ رسول اللہ صلی اللہ علیہ وسلم کے بجائے کافروں کی تعداد میں اضافے کا باعث بنے ہوئے تھے۔ اور اس طرح میدانِ جنگ میں وہ تیر اور تلوار لگنے سے قتل بھی ہوجاتے تو ان لوگوں کے بارے میں اللہ تعالیٰ نے یہ نازل فرمایا:﴿اِنَّ الَّذِيْنَ تَوَفّٰىهُمُ الْمَلٰٓىِٕكَةُ ظَالِمِيْۤ اَنْفُسِهِمْ﴾ الآیۃ. ’’بلاشبہ جو لوگ اپنی جانوں پر ظلم کرتے ہیں، جب فرشتے ان کی جان قبض کرنے لگتے ہیں…۔ ‘‘(صحیح البخاری: 4596)\nامام ضحاک رحمہ اللہ کا قول ہے کہ یہ آیت کچھ ایسے منافقوں کے بارے میں نازل ہوئی ہے جو مکہ ہی میں رہ گئے تھے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہجرت نہیں کی تھی اور جنگ بدر کے دن وہ مشرکوں کے ساتھ نکلے اور ان میں سے کچھ لوگ مارے بھی گئے تو یہ آیت ان کے بارے میں نازل ہوئی تھی۔(تفسیرالطبری : 319/4)گو، یہ آیت عام ہے اور ہر اس شخص کے بارے میں ہے جو قدرت کے باوجود ہجرت نہ کرے اور اقامت ِ دین کے لیے کوشش نہ کرے تو وہ اپنی جان پر خود ظلم کرتا ہے۔\nاور اجماعِ اُمت سے ثابت ہے کہ وہ ایک حرام کام کا ارتکاب کر رہا ہے کیو ں کہ اللہ تعالیٰ نے فرمایا ہے : ﴿اِنَّ الَّذِيْنَ تَوَفّٰىهُمُ الْمَلٰٓىِٕكَةُ ظَالِمِيْۤ اَنْفُسِهِمْ﴾ ’’بلاشبہ جن لوگوں کی اس حالت میں فرشتے جان قبض کرتے ہیں کہ وہ (جان بوجھ کر کافروں میں رہ کر)اپنی جانوں پر ظلم کرتے رہے ہوں۔ ‘‘ یعنی جنہوں نے ترک ہجرت کی وجہ سے اپنی جانوں پر ظلم کیا ہوتا ہے تو جان قبض کرنے کے وقت فرشتے ﴿قَالُوْا فِيْمَ كُنْتُمْؕ﴾ ’’ان سے پوچھتے ہیں کہ تم کس حال میں تھے ؟‘‘ یعنی تم یہاں کیوں ٹھہرے رہے، تم نےہجرت کیوں نہ کی ؟ ﴿قَالُوْا كُنَّا مُسْتَضْعَفِيْنَ۠ فِي الْاَرْضِؕ﴾ ’’وہ کہتے ہیں کہ ہم زمین میں عاجز و ناتواں تھے۔‘‘ گویا ہم شہر سے نکل کر کسی دوسری جگہ جانے کی قدرت نہیں رکھتے تھے۔ ﴿قَالُوْۤا اَلَمْ تَكُنْ اَرْضُ اللّٰهِ وَاسِعَةً﴾ الآیۃ. ’’فرشتے کہتے ہیں کیا اللہ تعالیٰ کی زمین فراخ نہیں تھی ؟‘‘\nاللہ تعالیٰ کا فرمان ہے : ﴿اِلَّا الْمُسْتَضْعَفِيْنَ﴾ ’’ہاں، جو بے بس ہیں۔‘‘ سے لے کر آیت کے آخر تک ان لوگوں کا ذکر ہے جن کو اللہ تعالیٰ نے ترکِ ہجرت میں معذور قرار دیا ہے کیو ںکہ یہ لوگ مشرکوں کے ہاتھوں سے نجات حاصل کرنے کی استطاعت نہیں رکھتے اور اگر استطاعت رکھتے بھی ہوں تو انہیں رستے کا علم نہیں ہے، اس لیے فرمایا:﴿لَا يَسْتَطِيْعُوْنَ۠ حِيْلَةً وَّلَا يَهْتَدُوْنَ سَبِيْلًاۙ۰۰۹۸﴾ ’’وہ نہ تو کوئی چارہ کر سکتے ہیں اور نہ رستہ جانتے ہیں۔‘‘ امام مجاہد، عکرمہ اور سدی رحمہم اللہ فرماتے ہیں کہ یہاں ﴿سَبِيْلًاۙ۰۰۹۸﴾ سے مراد مدینہ کا رستہ ہے۔ (تفسیر الطبری : 322,321/5 و تفسیر ابن أبی حاتم:1048/3) ﴿فَاُولٰٓىِٕكَ عَسَى اللّٰهُ اَنْ يَّعْفُوَ عَنْهُمْؕ﴾ ’’تو قریب ہے کہ اللہ تعالیٰ ایسوں کو معاف کر دے۔ ‘‘ یعنی ان کے ہجرت نہ کرنے سے درگزر فرمائے۔ اللہ تعالیٰ کی طرف سے لفظ ِ ﴿عَسَى ﴾ کا استعمال وجوب اور یقین کے معنی میں ہوتا ہے۔ ﴿وَكَانَ اللّٰهُ عَفُوًّا غَفُوْرًا۰۰۹۹﴾ ’’اور اللہ تعالیٰ معاف کرنے والا (اور) بخشنے والا ہے۔ ‘‘\nامام بخاری رحمہ اللہ نے سیّدنا ابوہریرہ رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عشاء کی نماز ادا فرماتے ہوئے جب «سَمِعَ اللهُ لِمَنْ حَمِدَهُ» کہا تو پھر سجدہ کرنے سے پہلے یہ دعا کی: ’’اے اللہ ! عیاش بن ابو ربیعہ کو (ظلم سے) نجات عطا فرما، اے اللہ ! سَلَمَه بن ہشام کو نجات عطا فرما، اے اللہ ! ولید بن ولید کو نجات عطا فرما، اے اللہ ! بے بس مومنوں کو نجات عطا فرما اور قبیلۂ مضر پر اپنی گرفت سخت کر دے اور انہیں قحط سالی میں مبتلا کر دے جیسا کہ سیّدنا یوسف علیہ السلام کے زمانے میں قحط پڑا تھا۔ ‘‘(صحیح البخاری: 4598)\nامام بخاری رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ میں اور میری والدہ بھی ان لوگوں میں سے تھے جنھیں اللہ تعالیٰ نے ﴿اِلَّا الْمُسْتَضْعَفِيْنَ﴾ فرما کر معذور قرار دیا ہے۔ (صحیح البخاری: 4588)\nاور فرمانِ الٰہی ہے : ﴿وَمَنْ يُّهَاجِرْ فِيْ سَبِيْلِ اللّٰهِ يَجِدْ فِي الْاَرْضِ مُرٰغَمًا كَثِيْرًا وَّسَعَةًؕ﴾ ’’اور جو شخص اللہ تعالیٰ کی راہ میں گھر بار چھوڑ جائے، وہ زمین میں بہت سی جگہ اورکشائش پائے گا۔ ‘‘اس آیت میں ہجرت کے شوق کو ابھارا گیا ہے۔ اور مشرکوں سے علیحدگی اختیار کرنے کی ترغیب دی گئی ہےکیوں کہ مومن جہاں بھی جائے گا، وہ مشرکوں سے بے نیاز ہو جائے گا۔ اور ایسی جگہ پائے گا جہاں وہ ان سے محفوظ رہ سکے۔ مُرَاغَم مصدر ہے، عرب کہتے ہیں : (رَاغَمَ فُلَانٌ قَوْمَهٗ مُرَاغَمًا وَّمُرَاغَمَةً) ’’فلاں اپنی قوم کو چھوڑ کر نکل گیا۔ ‘‘(تفسیر الطبری : 322/5 ولسان العرب صفحہ نمبر:)سیّدنا ابن عباس رضی اللہ عنہما فرماتے ہیں کہ (اَلْمُرَاغَم) زمین میں ایک جگہ سے دوسری جگہ منتقل ہونے کو کہتے ہیں۔(تفسیر ابن أبی حاتم : 1049/3) امام ضحاک رحمہ اللہ، ربیع بن انس اور ثوری رحمہما اللہ سے بھی اسی طرح مروی ہے۔(تفسیر ابن أبی حاتم : 1049/3) امام مجاہد رحمہ اللہ فرماتے ہیں کہ اس کے معنی اس چیز سے نجات کے ہیں جسے وہ ناپسند کرتا ہو۔(تفسیر ابن أبی حاتم : 1049/3) اور﴿سَعَةً١ؕ﴾ کے معنی رزق کے ہیں جیسا کہ قتادہ رحمہ اللہ اور کئی ائمہ تفسیر سے منقول ہے کہ اللہ تعالیٰ اسے ضلالت کے بجائے ہدایت سے اور فقر کے بجائے غنی سے نواز دے گا۔ (تفسیر الطبری : 328/5)\n﴿وَمَنْ يَّخْرُجْ مِنْۢ بَيْتِهٖ مُهَاجِرًا اِلَى اللّٰهِ وَرَسُوْلِهٖ ثُمَّ يُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ اَجْرُهٗ عَلَى اللّٰهِؕ﴾ ’’اور جو شخص اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف ہجرت کی نیت سے اپنے گھر سے نکلے پھر رستے ہی میں اسے موت آجائے تو اس کا ثواب اللہ تعالیٰ کے ذمّے واجب ہو گیا۔ ‘‘یعنی اسے اللہ تعالیٰ کے ہاں سے ہجرت کرنے والے ہی کا اجر و ثواب ملے گا جیسا کہ صحیح بخاری و مسلم کے علاوہ دیگر کتب ِ صحاح، مسانید اور سنن میں بھی سیّدنا عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یقیناً تمام اعمال کا انحصار نیتوں پر ہے اور ہر شخص کے لیے صرف وہی ہے جو وہ نیت کرے جس کی ہجرت اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کے لیے ہو تو اس کی ہجرت اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم ہی کے لیے ہے اور جس کی ہجرت دنیا کے حصول یا کسی عورت سے شادی کرنے کے لیے ہو تو اس کی ہجرت اسی کی طرف ہے جس کی طرف اس نے ہجرت کی۔‘‘\n(صحیح البخاری :2529، صحیح مسلم :1907)"],[1279,"§ہجرت نہ کرنے والوں کے لیے وعید\nیہ آیت ایسے مسلمانوں سے متعلق ہے جنہوں نے ہجرت پر قادر ہونے کے باوجود ہجرت نہیں کی اور اپنا گھر بار چھوڑ کر دارالہجرت (مدینہ)جانے میں پس وپیش کرتے رہے۔ اور یہی ان کا اپنی جانوں پر ظلم تھا۔ اور مسلمانوں پر ظلم یہ تھا کہ جنگ کے موقعہ پر انہیں مشرکوں کا ساتھ دینا پڑتا تھا اور مشرک یہ چال چلتے تھے کہ ایسے مسلمانوں کو اپنی صفوں کے آگے کر دیتے تھے کہ وہ ان کے لیے ڈھال اور دفاع کا کام دیں۔ اب یہ مسلمانوں کے لشکر کے لیے بڑی الجھن بن جاتی تھی کہ اگر لڑائی لڑیں، تیر برسائیں، تلوار چلائیں تو ان کے مسلمان بھائی ہی مرتے تھے اور اگر ہاتھ روکے رکھیں تو خود انہیں نقصان پہنچ جاتا تھا۔ چنانچہ سیدنا ابن عباس رضی اللہ عنہما اس آیت کے شان نزول کے بارے میں فرماتے ہیں: کہ (مکہ میں) ’’ مسلمانوں میں سے کچھ ایسے لوگ تھے جو مُشرکوں کا ساتھ دیتےاور مقابلہ کے وقت ان کی جمعیت بڑھاتے پھر (مسلمانوں کی طرف سے) کوئی تیر ان کو بھی لگ جاتا یا کسی کو تلوار لگتی تو وہ زخمی ہوتا یا مر جاتا، ایسے ہی لوگوں کے بارے میں اللہ تعالیٰ نے یہ آیت نازل فرمائی۔ ‘‘ (صحیح البخاری)"],[1280,"§ہجرت نہ کرنے کا نقصان\nایسے مسلمانوں کے لیے اس آیت میں جو وعید آئی ہے اس سے ضمنًا یہ بھی معلوم ہوجاتا ہے کہ ایسا کمزور ایمان اللہ تعالیٰ کے ہاں مقبول نہیں۔ لہٰذا گر مشرکین انہیں ڈھال کے طور پر استعمال کریں تو مسلمانوں کے اجتماعی مفاد کی خاطر انہیں بے دریغ قتل کر دینا چاہیے اور ایسے لوگوں کے کمزور ہونے کے عذر کو اللہ تعالیٰ نے قبول نہیں فرمایا کیوں کہ یہ کمزوری نہیں بلکہ گھر بار کی محبت اور مال و دولت کی ہوس تھی جس کی وجہ سے وہ ہجرت نہیں کرتے تھے یا پھر اسے بزدلی پر محمول کیا جائے گا۔"],[1281,"§ہجرت نہ کر سکنے والے\nجو مسلمان فی الواقع کمزور تھے اور ہجرت کرنے کی کوئی راہ نہیں نظر نہیں آرہی تھی۔ مستضعفین یا کمزور سے مراد وہ لوگ ہیں جو فی الحقیقت معذور ہوں جیسے بیمار، بچے، بوڑھے، عورتیں اور کافروں کی قید میں پڑے ہوئے مسلمان۔ وسائل محدود ہونے سے یہ مراد ہے کہ ان کے پاس نہ تو کوئی سواری کا بندوبست ہو اور نہ وہ پیدل سفر کی مشقت اُٹھانے کے قابل ہوں۔ انہیں اللہ تعالیٰ نے مندرجہ بالا گروہ سے مستثنیٰ قرار دیا، اور ان کے ہجرت نہ کرنے کے قصور کی معافی کا وعدہ فرمایا۔ چنانچہ سیدنا ابن عباس رضی اللہ عنہما فرمایاکرتے تھے کہ ’’میں اور میری ماں ایسے ہی لوگوں میں سے تھے جنھیں اللہ تعالیٰ نے معذور رکھا۔ ‘‘(صحیح البخاری)نیز ولید بن ولید، سلمہ بن ہشام، عیاش بن ابی ربیعہ اور کئی دوسرے ناتواں مسلمان بھی تھے جن کی نجات کے لیے رسول اللہ صلی اللہ علیہ وسلم نماز میں رکوع کے بعد دعافرمایا کرتے۔‘‘ (صحیح البخاری)"],[1282,"§ہجرت کے مقاصد اور ضرورت\nہجرت اس لیے فرض کی گئی تھی کہ ایک تو مسلمان کفار کے تشدد سے آزاد ہو کر اپنے اسلامی شعائر آزادی کے ساتھ بجا لاسکیں۔ اور دوسرے اس لیے کہ مدینہ کی طرف ہجرت کرکے مسلمانوں کی اجتماعی قوت کے لیے مددگار ثابت ہوں۔ پھرجب مکہ فتح ہو گیا اور پورے خطہ عرب میں اسلام کا بول بالا ہو گیا تو پھر ہجرت کی ضرور ت نہ رہی۔ جیسا کہ کئی احادیث صحیحہ سے ثابت ہے لیکن اس کا مطلب یہ بھی نہیں کہ اب تا قیامت ہجرت فرض نہیں۔ بلکہ جب بھی دوبارہ ایسا موقع پیدا ہو جائے کہ کسی علاقہ میں مسلمانوں کو اپنے شعائر اسلام کو بجالانا بھی مشکل ہو رہا ہو تومسلمانوں کو کوئی ایسا خطہ تلاش کرنا چاہیے جہاں انہیں آزادی سے شعائر اسلام بجالانے کی سہولت میسر ہو اور اپنے میں سے کوئی امیر منتخب کرکے اس طرف ہجرت کرنا اور اپنی اجتماعی قوت کو مرکوز کرنا اور پھر جہاد کرنا سب کچھ فرض ہو جائے گا۔ بلکہ اگر بنظر غائر دیکھا جائے تو ہجرت بھی جہاد کا ہی ایک حصہ ہوتی ہے۔ پھر جب اس علاقہ میں اسلام کا غلبہ ہو جائے تو وہاں بھی ہجرت کی ضرورت باقی نہ رہے گی۔"],[1283,"§دارالکفر میں رہنے کی رخصت کی شرائط\nان آیات سے یہ بھی معلوم ہو گیا کہ مسلمانوں کا دارالکفر میں رہنے کا جواز صرف دو صورتوں میں ہے ایک یہ کہ کوئی شخص اس خطہ میں اسلام کو غالب کرنے اور نظام کفر کو نظام اسلام میں تبدیل کرنے کی جدوجہد میں لگا رہے۔ جیسا کہ انبیاء علیہم السلام اور ان کے ابتدائی پیرو کرتے رہے ہیں اور دوسرے یہ کہ وہ فی الواقع وہاں سے نکلنے کی کوئی راہ نہ پاتا ہو اور بیزاری اور نفرت سے مجبورًا وہاں رہ رہا ہو۔ ان صورتوں کے علاوہ دارالکفر میں رہنا مستقل معصیت ہے۔"],[1284,"§اللہ تعالیٰ کا غفور رحیم ہونا\nاس آیت میں صرف ہجرت کے سفر کا ذکر ہے۔ جب کہ کئی احادیث صحیحہ سے ثابت ہے کہ اللہ تعالیٰ کی راہ میں کوئی سفر کیا جائے خواہ یہ ہجرت کا سفر ہو یا جہاد کا سفر ہو یا حج و عمرہ کا سفر ہو یا دینی علوم کے حصول کے لیے سفر ہو، اور دوران سفر حصول مقصد سے بعد یا پہلے موت واقع ہو جائے تو اللہ تعالیٰ اس کا پورا پورا اجر عطا کر دیتا ہے جیسا کہ درج ذیل حدیث سے معلوم ہوتا ہے :\nسیدنا ابو سعید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ بنی اسرائیل میں سے ایک شخص نے ننانوے (99) قتل کیے تھے۔ پھر وہ اپنے متعلق مسئلہ پوچھنے لگا۔ وہ ایک راہب کے ہاں گیا اور اسے پوچھا: کیا میرے لیے (توبہ کی) گنجائش ہے؟‘‘ اس نے کہا’’نہیں‘‘ تواس نے راہب کو بھی مار ڈالا (اور سو(100)پورے کر دیے) پھرلوگوں سے یہی مسئلہ پوچھتا رہا۔ کسی آدمی نے اسے کہا کہ فلاں فلاں بستی میں (توبہ کے لیے) چلے جائو۔ راستہ ہی میں اسے موت نے آلیا۔ اس نے اپنا سینہ بستی کی طرف جھکا دیا۔ اب رحمت کے اور عذاب کے فرشتے آپس میں جھگڑنے لگے۔ جس بستی کی طرف وہ جا رہا تھا اللہ تعالیٰ نے زمین کو حکم دیا کہ نزدیک ہو جا اور جس بستی سے جا رہا تھا اسے حکم دیا کہ دور ہو جا۔ اورفرشتوں سے فرمایا: کہ فاصلہ ماپ لو۔ چنانچہ جہاں اسے جانا تھا وہ بستی ایک بالشت بھر قریب نکلی تو اسے بخش دیا گیا۔‘‘(صحیح البخاری)\nاس میں نیت کے مطابق اجر و ثواب ملنے کی یقین دہانی ہے چاہے موت کی وجہ سے وہ اس عمل کے مکمل کرنے سے قاصر رہا ہو۔ جیسا کہ گذشتہ اُمتوں میں سے ایک سو (100)افراد کے قاتل کاواقعہ حدیث میں بیان کیا گیا ہے۔ جو توبہ کے لیے نیکوں کی ایک بستی میں جا رہا تھا کہ راستے میں موت آگئی۔اللہ تعالیٰ نے نیکوں کی بستی کو، بہ نسبت دوسری بستی کے قریب تر کر دیا جس کی وجہ سے اسے ملائکہ رحمت اپنے ساتھ لے گئے۔ (صحیح البخاری و صحیح مسلم) اسی طرح جو شخص ہجرت کی نیت سے گھر سے نکلے راستے میں ہی اسے موت آجائے تو اسے اللہ تعالیٰ کی طرف سے ہجرت کا ثواب ضرورملے گا، گو ابھی وہ ہجرت کے عمل کو پایہ تکمیل تک بھی نہ پہنچا سکا ہو۔ جیسے حدیث میں بھی ہے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:«اِنَّمَا الْاَعْمَالُ بِالنِّيَاتِ»’’عملوں کا دار و مدار نیتوں پر ہے۔‘‘ «وَاِنَّمَا لِكُلِّ امْرِئٍ مَّانَويٰ»’’آدمی کے لیے وہی ہے جس کی اس نے نیت کی۔ ‘‘ جس نے اللہ تعالیٰ اور ا س کے رسول صلی اللہ علیہ وسلم کے لیے ہجرت کی پس، اس کی ہجرت ان کے لیے ہے اور جس نے دنیا حاصل کرنے یا کسی عورت سے شادی کرنے کی نیت سے ہجرت کی پس اس کی ہجرت اسی کے لیے ہے جس نیت سے اس نے ہجرت کی۔(صحیح البخاری) یہ حکم عام ہے جو دین کے ہر کام کو شامل ہے۔ یعنی اس کو کرتے وقت اللہ تعالیٰ کی رضا پیش نظر ہوگی تو وہ مقبول، ورنہ مردود ہوگا۔\n﴿اِنَّ الَّذِيْنَ تَوَفّٰىهُمُ الْمَلٰٓىِٕكَةُ ظَالِمِيْۤ اَنْفُسِهِمْ﴾ بلاشبہ وہ لوگ جن کی ارواح فرشتے قبض کرتے ہیں جب ان کی زندگی کی مدت ختم ہو جاتی ہے ان کی کیفیت یہ ہے کہ وہ خود پر ظلم کر رہے ہیں کہ وہ ذلت اور مظلومیت کے ساتھ زندگی بسر کرتے ہیں جب کہ دینی اُمور کے سر انجام دینے میں بھی انہیں آزادی حاصل نہیں ہے اور نہ ان میں دین اسلام کا داعیہ اُجاگرہے۔\n﴿قَالُوْا فِيْمَ كُنْتُمْؕ﴾ ان کے فوت ہونے کے بعد فرشتے ان سے استفسار کرتے ہیں تم دینی معاملات میں کیسے تھے جب کہ انہیں ہجرت کرنے پر قدرت حاصل تھی لیکن انہوں نے وطن نہ چھوڑا۔\n﴿قَالُوْا كُنَّا مُسْتَضْعَفِيْنَ۠ فِي الْاَرْضِؕ﴾ جب انہیں ڈانٹ دی گئی تو اپنی کوتاہی کا اعتراف کرتے ہوئے معذرت کرتے ہوئے بتایا کہ ہم میں کچھ استطاعت نہ تھی اس لیے کہ کفار ہمیں کمزور سمجھتے تھے اس بناء پر ہم مکہ والوں میں رہتے ہوئے دین اسلام کے واجبات کو ادا کرنے سے قاصرتھے لیکن ان کی معذرت کو فرشتوں نے ٹھکر ا دیا اور انہیں کہا کیا اللہ تعالیٰ کی زمین فراخ نہ تھی تم وہاں سے کسی اور جگہ ہجرت کرکے چلے جاتے جہا ں تم اقامت دین کے کام کر سکتے اور تم خو د کو ذلت کی غلامی سے چھٹکارا دلاتے یقیناً کسی ایماندار کے لیے لائق نہیں کہ وہ ذلت کی زندگی بسر کرے۔\n﴿فَاُولٰٓىِٕكَ مَاْوٰىهُمْ جَهَنَّمُؕ﴾ جن کی خوفناک کیفیت کو بیان کیا جا رہا ہے آخرت میں ہم انہیں دوزخ میں رہائش دیں گے اس لیے کہ انہوں نے اپنی ذمہ داریوں کو ادا نہ کیا جب کہ شروع اسلام سے ہی ہجر ت کو مشروع قر ار دیا گیا تھا۔\n﴿وَسَآءَتْ مَصِيْرًاۙ۰۰۹۷﴾ جہنم تو بہت ہی براٹھکانہ ہے اس کی ہر چیز انہیں بری معلوم ہوگی اس مفہوم میں اس جانب اشارہ ہے کہ اگر کوئی شخص کسی ملک یا شہر میں اقامت دین کا فریضہ سر انجام نہیں دے سکتا یا سمجھتا ہے کہ اس کے علاوہ بعض دوسرے مقامات میں اقامت دین کے فریضہ کوبہتر ادا کیا جا سکتا ہے تو ا س کے لیے ضروری ہے کہ وہاں سے ترک سکونت کرکے اس جگہ اقامت اختیار کرے جہاں اچھے انداز کے ساتھ وہ اقامت دین کے فریضہ کو ادا کر سکتا ہے۔ ہاں اگر کوئی شخص دارالکفر میں رہائش پذیر ہے لیکن اسے تکلیف میں مبتلا نہیں کیا جاتا جب وہ دین اسلام کے اُصولوں کے مطابق زندگی گزارتا ہے تو اس کے لیے وہاں سے ہجرت کرنا ضروری نہیں بلکہ بعض اوقات ایسے مقام میں اقامت اختیار کرنے سے اسلام کے محاسن کا چرچا ہوتا ہے اور لوگوں کی توجہ اسلام کی جانب مبذول ہوتی ہے۔\n﴿اِلَّا الْمُسْتَضْعَفِيْنَ مِنَ الرِّجَالِ وَالنِّسَآءِ وَالْوِلْدَانِ﴾ وہ لوگ جو اقامت دین کی استطاعت نہیں پاتے ہیں اور وہاں سے راہ فرار بھی اختیار نہیں کر سکتے تو ان کا عذر مقبول ہے جیسا کہ بوڑھے کمزور لوگ اور بچے اور عورتیں جیسے ام الفضل عبداللہ بن عباس رضی اللہ عنہما کی والدہ اور بوڑھے جیسا کہ عیاش بن ابی ربیعہ، سلمہ بن ہشام اور بچے جیسا کہ عبداللہ بن عباس رضی اللہ عنہما وغیرہ ہیں۔\n(صحیح البخاری)\n﴿لَا يَسْتَطِيْعُوْنَ۠ حِيْلَةً وَّلَا يَهْتَدُوْنَ سَبِيْلًاۙ۰۰۹۸﴾ ان میں استطاعت نہیں وہ کوئی بھی حیلہ نہیں پاتے ہیں ان کا عذر بیمار ہونا، بڑھاپا، احتیاج فقر و افلاس۔ سفر کے راستوں سے ناواقفیت کہ اگر وہ وہا ں سے نکلیں گے تو راستہ معلوم نہ ہونے کے سبب مشکلات سے دو چار ہوں گے یا راستہ میں ہلاک ہو جائیں گے۔ چنانچہ ابن عباس رضی اللہ عنہما سے منقول ہے کہ انہوں نے اپنا نام لیا کہ میں اور میری والدہ ان کمزور لوگوں سے تھے جن کے پاس کوئی حیلہ نہ تھا اور نہ راستہ کی واقفیت تھی۔\n(صحیح البخاری)\n﴿فَاُولٰٓىِٕكَ عَسَى اللّٰهُ اَنْ يَّعْفُوَ عَنْهُمْؕ﴾ ان کمزور لوگوں کے بارے میں بتایا جو ہجرت نہیں کر سکتے تھے اُمید ہے کہ اللہ تعالیٰ ان کو معاف فرمائے گا اور دارالکفر میں رہنے کے سبب ان کا مؤاخذہ نہیں کرے گا لفظ ”عَسٰی“میں اشارہ ہے کہ عفو کی اُمید کی جا سکتی ہے یقینی نہیں ہے نیز ہجرت کرنا ضروری ہے اگرچہ کوئی حیلہ کیوں نہ استعمال کیا جائے اور گزرگاہوں کے بارے میں معلومات حاصل کیے جائیں۔ (المراغی : 134,133/5)\nتناسب : بالکل واضح ہے قبل ازیں ایسے مقام سے ہجرت کرنے کا حکم دیا گیا تھا جہاں اسلام کے احکام پر عمل کرناممکن نہیں تھا جب کہ اس آیت میں بھی ترغیب دلائی گئی ہے کہ مشرکین آبادی سے دور رہنا چاہیے اور مومن شخص جہاں بھی اقامت اختیار کرے گا وہاں اسے تحفظ حاصل ہوگا نفرت کے کاموں سے بچائو حاصل ہوگا اور وافر رزق عطا ہوگا۔ چنانچہ مشہور حدیث جس کے راوی عمر بن خطاب رضی اللہ عنہ ہیں وہ بیان کرتے ہیں رسول اکرم صلی اللہ علیہ وسلم نے فرمایا اعمال کا دار و مدار نیت پر ہے ہر شخص کی نیت کے مطابق اس کو اجر و ثواب سے نوازا جائے گا جس شخص نے ایک جگہ سے ترک سکونت کرکے دوسری جگہ رہائش اختیار کی ہے تو دیکھا جائے کہ اس نے انتقال آبادی کو اللہ تعالیٰ او راللہ تعالیٰ کے رسول صلی اللہ علیہ وسلم کی رضا کے لیے اختیار کیا ہے تو اس کا ہجرت کرنا درست ہے باعث ثواب ہے اور جس شخص نے دنیوی مفادات کو ملحوظ رکھتے ہوئے تبادلہ آبادی اختیار کی ہے یا کسی عورت کے ساتھ نکاح اس کا سبب بنا ہے تو اس کی ہجرت اس کے ارادہ کے موافق ہے۔\nاس سلسلہ میں حافظ ابن کثیر رحمہ اللہ نے مشہور حدیث کا ذکر کیا ہے جس میں اس انسان کا تذکرہ ہے جس نے ننانوے (99) انسانوں کو قتل کیا تھا پھر اس نے زاہد،عابد شخص کو بھی قتل کر دیا جس نے کہا کہ تیری توبہ قبول نہیں اس نے سو (100) انسانوں کے قتل کے بعد ایک عالم سے استفسار کیا اب ان حالات میں اس کی توبہ کی قبولیت کی کوئی صورت ہے اس نے کہا تیری توبہ کی قبولیت میں کوئی چیز حائل نہیں ہو سکتی ہے اس نے بتایا کہ آپ فلاں شہر جائیں وہاں ایک عالم دین ہے اس سے دریافت کریں جب وہ وہاں سے اس شہر کی جانب روانہ ہوا توراستہ میں اس پر موت طاری ہو گئی اس کی روح کو لے جانے والے فرشتوں کے درمیان جھگڑا کھڑ اہو گیا رحمت ے فرشتے اس کی روح کو لے جانا چاہتے تھے اس لیے کہ وہ تائب ہو گیا تھا جبکہ عذاب کے فرشتوں نے کہا اس کی توبہ قبول نہیں ہے۔ چنانچہ اللہ تعالیٰ کی جانب سے انہیں حکم دیا گیا کہ دونوں علاقوں کے درمیان کی زمین کی پیمائش کریں جس بستی کی جانب فاصلہ کم ہو اس شخص کو ان سے شمار کیا جائے اس دوران اللہ نے اس زمین کو حکم دیا جدھر وہ ہجرت کرکے جا رہا تھا اس کا فاصلہ ایک بالشت بہ نسبت اس بستی کے کم تھا جدھر سے وہ روانہ ہوا تھا چنانچہ رحمت کے فرشتے اس کی روح کو لے جاتے ہیں ہجرت کا عمل اسے نجات عطا کرتا ہے۔ (ابن کثیر : 824/1، صحیح مسلم)\nشانِ نزول : قتادہ رحمہ اللہ بیان کرتے ہیں ایک صحابی رضی اللہ عنہ بیمار تھے اس نے مدینہ کی جانب ہجرت کی لیکن تنعیم مقام میں فوت ہو گیا آپ صلی اللہ علیہ وسلم سے اس کے بارے میں دریافت کیا گیا اس پریہ آیت نازل ہوئی۔ ذہن نشین کریں جس طرح دارالحرب سے دارالسلام کی جانب ہجرت کرنے کا حکم دیا ہے اس طرح جس زمین میں بدعات کا فروغ ہو وہاں اسلاف کو برا بھلا کہاجاتا ہو جب کہ آپ میں استطاعت نہیں کہ انہیں اس سے روکا جائے تو پھر وہاں سے ہجرت کرنا درست ہے، ارشاد ربانی ہے :\n﴿وَاِذَا رَاَيْتَ الَّذِيْنَ يَخُوْضُوْنَ فِيْۤ اٰيٰتِنَا فَاَعْرِضْ عَنْهُمْ﴾ (الانعام:68) ’’اور جب آپ لوگوں کے بارے میں معلوم کریں کہ وہ ہماری آیات میں بلا جوازبحث کر رہے ہیں تو آپ ان سے روگردانی کریں۔ ‘‘\nچنانچہ ابراہیم علیہ السلام کے بارے میں وارد ہے : ﴿اِنِّيْ مُهَاجِرٌ اِلٰى رَبِّيْؕ﴾ (العنکبوت:26) ’’بلاشبہ میں اپنے پروردگار کی طرف ہجرت کرنے والا ہوں۔‘‘\nاور موسیٰ علیہ السلام کے بارے میں وارد ہے : ﴿فَخَرَجَ مِنْهَا خَآىِٕفًا يَّتَرَقَّبُ١ٞ﴾ (القصص:21) ’’پس وہ ان سے خوفزدہ حالت میں نکلا اور لوگوں (کے آنے کا) انتظار کرتا رہا۔ ‘‘\nلیکن جب مکہ فتح ہو گیا جزیرۃ العرب میں اسلام کو غلبہ حاصل ہو ااور لوگ کثرت کے ساتھ دین اسلام میں داخل ہونا شروع ہو گئے اور آپ صلی اللہ علیہ وسلم نے اطراف و اکناف میں اسلامی تعلیم کے لیے اہل علم کا تعین فرمایا تو آپ صلی اللہ علیہ وسلم نے واضح کیا فتح مکہ کے بعد ہجرت کا حکم نہیں ہے البتہ جہاد اور اس کی نیت کا ثواب حاصل ہو گا اور جب بھی تمہیں کہیں جانے کا حکم دیا جائے تو تمہیں جانا ہوگا۔ (صحیح البخاری، صحیح مسلم)\nہاں اگر کفار اسلامی علاقوں پر ظلم کر رہے ہوں او رخطرہ ہو کہ وہ کہیں غالب نہ آجائیں تو ایسی صورت میں ہجرت کرناضروری ہے۔ (المراغی : 137,136/5)\n﴿وَاِذَا ضَرَبْتُمْ فِي الْاَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَقْصُرُوْا مِنَ الصَّلٰوةِࣗۖ اِنْ خِفْتُمْ اَنْ يَّفْتِنَكُمُ الَّذِيْنَ كَفَرُوْاؕ اِنَّ الْكٰفِرِيْنَ كَانُوْا لَكُمْ عَدُوًّا مُّبِيْنًا۰۰۱۰۱﴾\nاور جب تم زمین میں سفر کرو تم تم پر کوئی گناہ نہیں کہ تم نماز قصر کر لو، اگر تمہیں ڈر ہو کہ کافر (حملہ کر کے) تمہیں فتنے میں ڈال دیں گے، بے شک کافر تمہارے کھلے دشمن ہیں"],[1285,"§نمازِقصر\nارشاد باری تعالیٰ ہے : ﴿وَاِذَا ضَرَبْتُمْ فِي الْاَرْضِ﴾ ’’اور جب تم زمین میں سفر کرو۔‘‘ جیسا کہ فرمایا:﴿عَلِمَ اَنْ سَيَكُوْنُ مِنْكُمْ مَّرْضٰىۙ وَاٰخَرُوْنَ يَضْرِبُوْنَ فِي الْاَرْضِ يَبْتَغُوْنَ مِنْ فَضْلِ اللّٰهِۙ …﴾ الآیۃ.(المزمل:20) ’’اس نے جانا کہ تم میں بعض بیمار بھی ہوتے ہیںاور بعض اللہ تعالیٰ کے فضل (معاش) کی تلاش میں زمین میں سفر کرتے ہیں…۔‘‘ ﴿فَلَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَقْصُرُوْا مِنَ الصَّلٰوةِࣗۖ﴾ ’’تو تم پر کچھ گناہ نہیں کہ نماز میں سے کچھ کم کرو۔ ‘‘یعنی نماز کی کمیت میں کمی کر لو اور چار رکعتوں والی نماز کو دور کعتیں پڑھ لو۔ ﴿اِنْ خِفْتُمْ اَنْ يَّفْتِنَكُمُ الَّذِيْنَ كَفَرُوْاؕ﴾ ’’اگر تمہیں خوف ہو کہ کافر (حملہ کرکے) تمہیں فتنے میں ڈال دیں گے۔ ‘‘\nاس آیت کے نزول کے وقت جو اکثر و بیشتر صورت حال تھی، یہ (خوف کی شرط) اسی کے مطابق ہے کیوں کہ اسلام کے آغاز میں ہجرت کے بعد مسلمانوں کو اپنے اکثر سفروں میں خطرات درپیش رہتے تھے بلکہ ان کے سفر ہوتے ہی عام جنگوں یا خصوصی مہموں کے لیے تھے۔ اور تمام قبائل عرب نے اسلام اور مسلمانوں کے خلاف جنگ برپا کر رکھی تھی۔ اور قاعدہ یہ ہے کہ منطوق جب اکثر و بیشتر صورت حال یا کسی خاص واقعے پر مبنی ہو تو اس کا کوئی مفہوم نہیں ہوتا۔(لہٰذا آیت کا یہ مطلب نہیں کہ اگر سفر میں کافروں کی طرف سے ایذا کا خوف نہ ہو تو پھر نماز قصر نہ کی جائے۔) جیسا کہ اللہ تعالیٰ نے فرمایا ہے :﴿وَلَا تُكْرِهُوْا فَتَيٰتِكُمْ عَلَى الْبِغَآءِ اِنْ اَرَدْنَ تَحَصُّنًا﴾ (النور:33) ’’اور تمہاری لونڈیاں اگر پاک دامن رہناچاہیں تو تم دنیاوی زندگی کا سامان تلاش کرنے کی خاطر انہیں بدکاری پر مجبور نہ کرو۔‘‘ (اس کا یہ مطلب نہیں کہ اگر وہ پاک دامن نہ رہنا چاہیں تو پھر تم انہیں بدکاری پر مجبور کر سکتے ہو) اسی طرح فرمانِ باری تعالیٰ ہے :﴿وَرَبَآىِٕبُكُمُ الّٰتِيْ فِيْ حُجُوْرِكُمْ مِّنْ نِّسَآىِٕكُمُ الّٰتِيْ دَخَلْتُمْ بِهِنَّ١ٞ﴾ (النسآئ:23) ’’اور جن عورتوں سے تم مباشرت کر چکے ہو ان کی لڑکیاں جن کو تم پرورش کرتے ہو وہ بھی تم پر حرام ہیں۔‘‘ (اس کا یہ مطلب نہیں کہ ان عورتوںکی جو لڑکیاں تمہاری پرورش میں نہ ہوں، وہ حرام نہیں ہیں۔)\nامام احمد رحمہ اللہ نے یعلٰی بن اُمیہ کی روایت بیان کی ہے کہ میں نے سیّدنا عمر بن خطاب رضی اللہ عنہ کی خدمت میں عرض کی : ارشاد باری تعالیٰ ہے : ﴿فَلَيْسَ عَلَيْكُمْ جُنَاحٌ اَنْ تَقْصُرُوْا مِنَ الصَّلٰوةِࣗۖ اِنْ خِفْتُمْ اَنْ يَّفْتِنَكُمُ الَّذِيْنَ كَفَرُوْاؕ﴾ ’’تو تم پر کچھ گناہ نہیں کہ نماز میں سے کچھ کم کرو اگر تمہیں خوف ہو کہ کافر (حملہ کرکے) تمہیں فتنے میں ڈال دیں گے۔‘‘ لیکن اب تو اللہ تعالیٰ نے مسلمانوں کو امن عطا فرما دیا ہے ؟ سیّدنا عمر رضی اللہ عنہ نے جواب دیا کہ مجھے بھی اس بات سے تعجب ہوا تھا جس سے تم تعجب کر رہے ہو تو میں نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:«صَدَقَةٌ تَصَدَّقَ اللهُ بِهَا عَلَيْكُمْ فَاقْبَلُوا صَدَقَتَهُ» ’’اب یہ تخفیف صدقہ ہے جو اللہ تعالیٰ نے تم پر کر دیا ہے، لہٰذا اس کے صدقے کو قبول کرو۔‘‘ (مسند أحمد)اس حدیث کو امام مسلم رحمہ اللہ اور اہل سنن نے بھی روایت کیا ہے۔(صحیح مسلم: 686 وسنن أبی داؤد :1199) امام ترمذی رحمہ اللہ فرماتے ہیں کہ یہ حدیث حسن صحیح ہے۔ امام علی بن مدینی رحمہ اللہ فرماتے ہیں کہ سیّدنا عمر رضی اللہ عنہ سے مروی یہ حدیث حسن صحیح ہے اور یہ روایت اسی سند سے محفوظ ہے۔ اس کے رجال معروف ہیں۔\nامام ابو بکر بن ابو شیبہ نے ابو حنظلہ حذاء کی روایت کو بیان کیا ہے کہ میں نے سیّدنا ابن عمر رضی اللہ عنہما سے نماز سفر کے بارے میں پوچھا تو انہوں نے فرمایا:(کہ نماز سفر کی دو رکعتیں ہیں، میںنےعرض کی کہ اللہ تعالیٰ نے تو فرمایا ہے : بشرطیکہ تم کوخوف ہو کہ کافر لوگ تم کو ایذا دیں گے اور اب ہم تو حالت امن میں ہیں۔ انہوں نے فرمایا:) رسول اللہ صلی اللہ علیہ وسلم کی سنت یہی ہے کہ سفر میں دو رکعتیں پڑھی جائیں۔ (المصنف لابن أبی شیبۃ:8158)\nامام بخاری رحمہ اللہ نے سیّدنا انس رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ سے مکہ روانہ ہوئے تو آپ صلی اللہ علیہ وسلم نماز کی دو دو رکعتیں ادا فرمایا کرتے تھے حتی کہ ہم مدینہ میں واپس آگئے۔ میں نے عرض کی : آپ لوگوں نے مکہ میں کتنا قیام کیا تھا ؟ انہوں نے جواب دیا کہ ہم نے دس دن قیام کیا تھا۔(صحیح البخاری: 1081)اسی طرح اس حدیث کو دیگر محدثین نے بھی بیان کیا ہے۔ (صحیح مسلم : 693 وسنن أبی داؤد:1233)\nامام احمد رحمہ اللہ نے حارثہ بن وہب خزاعی کی روایت کو بیان کیا ہے کہ میں نے نبی ٔ اکرم صلی اللہ علیہ وسلم کے ساتھ منٰی میں نمازِ ظہر اور عصر کی دو رکعتیں ادا کی تھیں، حالانکہ یہاں مسلمانوں کی تعداد بھی بہت زیادہ تھی اور وہ بے حد امن میں تھے۔ (مسند أحمد)\nچونکہ ہجرت بغیر سفر کے ناممکن تھی، اسی لیے ہجرت کے احکام کے ساتھ سفر میں نماز کا حکم بیان کرنا مناسب ہوا، کہ مسلمان جب سفرمیں ہوں تو چار رکعت والی نمازیں دو رکعت پڑھیں۔ اور آیت میں ﴿فَلَيْسَ عَلَيْكُمْ جُنَاحٌ﴾ یعنی ’’تمہارے لیے کوئی حرج نہیں ہے ‘‘ سے جمہور نے استدلال کیاہے کہ سفر میں قصر کرنا سنت ہے، واجب نہیں، مسلم، احمد، ابوداؤد اور ترمذی رحمہم اللہ نے یعلی بن اُمیہ سے روایت کی ہے کہ سیّدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس آیت کے بارے میں پوچھا : کیا امن ہو جانے کے بعد بھی نماز قصر پڑھی جا ئے گی؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ اللہ تعالیٰ کا صدقہ ہے، مسلمان اسے قبول کریں۔‘‘اور رسول اللہ صلی اللہ علیہ وسلم کا عمل بھی یہی تھا کہ سفر میںآپ صلی اللہ علیہ وسلم نے بغیر حالت ِ خوف کے قصر کیا۔ اسی لیے علماء نے کہا ہے کہ ﴿اِنْ خِفْتُمْ﴾ ’’اگر خوف ہو تو قصرکرو ‘‘ کی قید اُس زمانہ میں مسلمانوں کا حال بیان کرنے کے لیےہے۔ ورنہ قصر ہر سفر میں جائز ہے۔ ترمذی، نسائی اور ابن ابی شیبہ رحمہم اللہ نے ابن عباس رضی اللہ عنہما سے روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم مدینہ منورہ سے سفر کے لیے نکلے، اور انہیں رب العالمین کے علاوہ کسی کا خوف نہیںتھا، اور آپ صلی اللہ علیہ وسلم نے دو دو رکعت نماز پڑھی۔ اور بخاری اور دوسرے محدثین رحمہم اللہ نے انس رضی اللہ عنہ سے روایت کی ہے کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ سے مکہ کے لیے روانہ ہوئے، اور آپ صلی اللہ علیہ وسلم دو دو رکعت نمازپڑھتے رہے، یہاں تک کہ ہم مدینہ لوٹ کر آگئے۔\nاس آیت میں اگرچہ سفر کے ساتھ دشمن کے اندیشہ کا بھی ذکر ہے تاہم سنت رسول اللہ صلی اللہ علیہ وسلم سے ثابت ہے کہ ہر طرح کے سفر میںنماز قصر کی جا سکتی ہے۔ نیز یہ بھی ضروری نہیں کہ یہ سفر فی سبیل اللہ ہی ہو بلکہ ہر سفر میں قصر کی جا سکتی ہے رہی یہ بات کہ کتنے فاصلہ کو سفر کہہ سکتے ہیں اس میں بھی اگرچہ اختلافات موجود ہیں۔ تاہم ہمارے لیے یہ امر کافی اطمینان کا باعث ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کہ ’’کوئی عورت ایک رات بھی محرم کے بغیر سفر نہ کرے۔ ‘‘ (صحیح البخاری) گویا اتنی مسافت جہاں سے ایک انسان پیدل رات کو اپنے گھر واپس نہ پہنچ سکتا ہو، وہ سفر ہے اور سیدنا عمر رضی اللہ عنہ نے اسے اپنے دورِ خلافت میں ایک عورت کے سفرپر محمول کرتے ہوئے اس دور کے 9میل کی مسافت کو سفر قرار دیا تھا جو آج کل کے پیمانہ کے لحاظ سے 15کلومیٹر بنتا ہے۔ یعنی ایک کمزور انسان پیدل ایک دن میں 15کلومیٹر جانے کا اور اتنا ہی آنے کا کل 30کلومیٹرمسافت طے نہیں کر سکتا۔ لہٰذا اتنی مسافت پر سفرکااطلاق ہوگا۔ سفر میں اگر قصرنہ کی جائے تو بھی کوئی مضائقہ نہیں۔ تاہم قصر کرنا ہی افضل ہے۔ پھر سفر میں دو نمازیں اکٹھے کرکے پڑھنے کا موقع آجاتا ہے۔ ایسی تفصیلات کے لیے درج ذیل احادیث ملاحظہ فرمائیے :\n1:\nسفرمیں قصر جمع اور سفر کی تعیین :سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں :’’ابتداء ً سفر و حضر میں نماز دو رکعت فرض کی گئی تھی۔ پھر سفر کی نماز تو اتنی ہی برقرار رکھی گئی اور حضر کی نماز میں اضافہ کیا گیا۔ (صحیح البخاری، صحیح مسلم)\n2:\nحارث بن وہب فرماتے ہیں کہ منٰی میں ہمیں نبی اکرم صلی اللہ علیہ وسلم نے دو رکعت (نماز قصر) پڑھائی۔ حالانکہ آپ صلی اللہ علیہ وسلم بالکل امن میں تھے۔‘‘ (صحیح البخاری)\n3:\nیعلٰی بن اُمیہ کہتے ہیں کہ میں نے سیدنا عمر رضی اللہ عنہ سے کہا کہ ’’ اللہ تعالیٰ فرماتا ہے کہ اگر تمہیں (کافروںکا) خوف ہو تو نماز میں قصر کرو اور اب تو ہم امن میں ہیں۔‘‘سیدنا عمر رضی اللہ عنہ نے جواب دیا ’’اسی بات پر میں نے بھی تعجب کیا اور رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:’’ یہ ایک صدقہ ہے جو اللہ تعالیٰ نے آپ پر کیا لہٰذا اس کا صدقہ قبول کرو۔ ‘‘ (ترمذی)\n4:\nسیدنا عبداللہ بن عمر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ جب آپ صلی اللہ علیہ وسلم کو سفر میں جلدی ہوتی تو مغرب کو مؤخر کرکے تین رکعت پڑھتے پھر سلام پھیرتے۔ پھر تھوڑی دیر بعد عشاء کی اقامت ہوتی تو آپ صلی اللہ علیہ وسلم دو رکعت پڑھتے پھر سلام پھیرتے۔ ‘‘(صحیح البخاری)\n5:\nسیّدنا عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے مدینہ میں رہ کر (یعنی بلا سفر) سات رکعتیں مغرب اور عشاء کی اور آٹھ رکعتیں ظہر اور عصر کی (ملا کر) پڑھیں۔‘‘ ایوب سختیانی نے جابر بن زید سے کہا’’ شاید بارش کی رات میں ایسا کیاہو؟‘‘ انہوں نے کہا’’ شاید‘‘۔(صحیح البخاری)\n﴿وَاِذَا كُنْتَ فِيْهِمْ فَاَقَمْتَ لَهُمُ الصَّلٰوةَ فَلْتَقُمْ طَآىِٕفَةٌ مِّنْهُمْ مَّعَكَ وَلْيَاْخُذُوْۤا اَسْلِحَتَهُمْ١۫ࣞ فَاِذَا سَجَدُوْا فَلْيَكُوْنُوْا مِنْ وَّرَآىِٕكُمْ١۪ࣕ وَلْتَاْتِ طَآىِٕفَةٌ اُخْرٰى لَمْ يُصَلُّوْا فَلْيُصَلُّوْا مَعَكَ وَلْيَاْخُذُوْا حِذْرَهُمْ وَاَسْلِحَتَهُمْۚ وَدَّ الَّذِيْنَ كَفَرُوْا لَوْ تَغْفُلُوْنَ عَنْ اَسْلِحَتِكُمْ وَاَمْتِعَتِكُمْ فَيَمِيْلُوْنَ عَلَيْكُمْ مَّيْلَةً وَّاحِدَةًؕ وَلَا جُنَاحَ عَلَيْكُمْ اِنْ كَانَ بِكُمْ اَذًى مِّنْ مَّطَرٍ اَوْ كُنْتُمْ مَّرْضٰۤى اَنْ تَضَعُوْۤا اَسْلِحَتَكُمْۚ وَخُذُوْا حِذْرَكُمْؕ اِنَّ اللّٰهَ اَعَدَّ لِلْكٰفِرِيْنَ عَذَابًا مُّهِيْنًا۰۰۱۰۲﴾\nاور (اے نبی صلی اللہ علیہ وسلم!) جب آپ مومنوں کے درمیان ہوں، پھر انہیں نماز پڑھانے کے لیے کھڑے ہوں تو ان میں سے ایک گروہ اپنے ہتھیار لگائے ہوئے آپ کے ساتھ جماعت میں کھڑا ہو، پھر جب وہ سجدے کر لے تو پیچھے چلا جائے اور دوسرا گروہ جس نے ابھی نماز نہیں پڑھی وہ آپ کے ساتھ نماز ادا کرے اور اپنا بچائو ساتھ لے اور اپنے ہتھیار (لگائے رکھے۔) کافر چاہتے ہیں کہ تم اپنے ہتھیاروں اور اپنے سامان کی طرف سے ذرا غافل ہو جائو تو وہ تم پر یکبارگی دھاوا بول دیں اور اگر تمہیں بارش سے تکلیف ہو یا تم بیمار ہو تو تم پر کوئی گناہ نہیں کہ اپنے ہتھیار (ایک طرف) رکھ دو، اور اپنا بچائو ساتھ لو۔ بے شک اللہ نے\nکافروں کے لیے رسوا کر دینے والا عذاب تیار کر رکھا ہے"],[1286,"§نمازِ خوف اور اس کی اقسام\nنمازِ خوف کی بہت سی اقسام ہیں کیوں کہ دشمن کبھی تو قبلہ کے سامنے ہوتا ہے اور کبھی وہ کسی اور طرف ہوتا ہے، پھر نماز کبھی چار رکعتوں والی ہوتی ہے اور کبھی تین والی، مثلاً: نماز مغرب اور کبھی دو رکعتوں والی، مثلاً: نماز صبح اور نماز سفر، پر کبھی مسلمان اسے باجماعت ادا کرتے ہیں۔ اور کبھی جنگ اس قدر گھمسان کی ہوتی ہے کہ وہ باجماعت ادا کرہی نہیں سکتے الگ الگ پڑھتے ہیں کبھی قبلہ رخ ہو کر اور کبھی غیر قبلہ رخ۔ کبھی سوار ہو کر اور کبھی سواری سے نیچے اتر کر۔ حتی کہ اس حالت میں وہ چلتے ہوئے اور دشمن پر پے درپےوار کرتے ہوئے بھی نماز ادا کرسکتے ہیں۔\nبعض علماء نے کہا ہے کہ اس حالت میں وہ صرف ایک رکعت پڑھیں گے کیو ںکہ حدیث ابن عباس رضی اللہ عنہما میں ہے کہ اللہ تعالیٰ نے تمہارے نبی صلی اللہ علیہ وسلم کی زبانی حضر میں نماز کی چار رکعات،سفر میں دو رکعتیں اور خوف کی حالت میں ایک رکعت فرض قرار دی ہے۔(صحیح مسلم: 687 وسنن أبی داؤد :1247) امام احمد رحمہ اللہ کا بھی یہی قول ہے۔ امام منذری رحمہ اللہ نے حواشی میں لکھا ہے کہ عطاء، جابر، حسن، مجاہد، حکم، قتادہ اور حماد رحمہم اللہ کا بھی یہی قول ہے۔ طاؤس اور ضحاک رحمہما اللہ کا بھی یہی مذہب ہے۔ (مختصر سنن أبی داؤد للحافظ المنذری : 1202) ابو عاصم عبادی نے بیان کیا ہے کہ امام محمد بن نصر مَرْوزِي کی رائے میں حالت ِ خوف میں نماز صبح کی ایک رکعت ہے، امام ابن حزم رحمہ اللہ کا بھی یہی مذہب ہے۔ (المُحَلّٰى : 33/5-35) امام اسحاق بن راہویہ رحمہ اللہ فرماتے ہیں کہ شمشیر زنی کے وقت ایک رکعت ہی کافی ہوگی اور اسے اشارے کے ساتھ ادا کر لو اور اگر ایک رکعت پڑھنے کی بھی استطاعت نہ ہو تو پھر صرف ایک سجدہ کرلو کیوں نماز ذکر الٰہی کا نام ہے۔ ہم نماز خوف کی کیفیت سے قبل اس آیت کریمہ کا سبب نزول بیان کریں گے۔ امام احمد رحمہ اللہ نے ابو عَيَّاش زُرَقِي کی روایت کو بیان کیا ہے کہ ہم عُسْفَان میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ مشرک ہمارے سامنے آگئے، ان کی قیادت خالد بن ولید رضی اللہ عنہ کر رہے تھے اور وہ ہمارے اور قبلہ کے مابین تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نمازِ ظہر پڑھائی تو مشرکوں نے کہا کہ مسلمان ایک ایسی حالت میں تھے کہ ہمیں ان پر اچانک حملہ کر دینا چاہیے تھا، پھر کہنے لگے کہ ابھی ان کی ایک ایسی نماز کا وقت آنے لگا ہے جو انہیں اپنے بیٹوں اور اپنی جانوں سے بھی عزیز ہے تو ظہر وعصر کے درمیان جبریل علیہ السلام ان آیات کو لے کر نازل ہو گئے :﴿وَاِذَا كُنْتَ فِيْهِمْ فَاَقَمْتَ لَهُمُ الصَّلٰوةَ …﴾ .\nجب نمازِ عصر کا وقت ہوا تو رسو ل اللہ صلی اللہ علیہ وسلم نے صحابہ رضی اللہ عنہم کو حکم دیا اور انہوں نے اپنے ہتھیار پکڑ لیے اور ہم نے آپ صلی اللہ علیہ وسلم کے پیچھے دو صفیں بنالیں، پھر آپ صلی اللہ علیہ وسلم نے جب رکوع کیا تو ہم سب نے بھی رکوع کیا،پھر آپ صلی اللہ علیہ وسلم نے رکوع سے سر اُٹھایا تو ہم سب نے بھی سر اُٹھایا، پھر جب نبی اکرم صلی اللہ علیہ وسلم نے سجدہ کیا تو آپ صلی اللہ علیہ وسلم کے ساتھ والی صف نے سجدہ کیا اور دوسری صف کے لوگ کھڑے ہو کر ان کا پہرہ دیتے رہے۔ انہوں نے جب سجدہ کر لیا تو وہ کھڑے ہو گئے اور دوسرے بیٹھ گئے اور انہوں نے اپنی جگہ پر سجدہ کیا، پھر یہ ان کی جگہ پر اور وہ ان کی جگہ پر آگئے، پھر آپ صلی اللہ علیہ وسلم نے رکوع کیا تو سب نے رکوع کیا، پھر آپ صلی اللہ علیہ وسلم نے رکوع سے سر اُٹھایا تو سب نے سر اُٹھایا، پھر نبی اکرم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے ساتھ والی صف نے سجدہ کیا اور دوسرے لوگوں نے کھڑے ہو کر پہرہ دیا جب یہ بیٹھ گئے تو دوسرے بھی بیٹھ گئے۔ اور انہوں نے سجدہ کیا، پھر آپ صلی اللہ علیہ وسلم سلام پھیر کر نماز سے فارغ ہو گئے۔ راوی کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس طرح دو مرتبہ نماز پڑھائی ایک مرتبہ عُسْفَان میں اور دوسری مرتبہ بنو سُلَيم کے علاقے میں۔ (مسند أحمد)اسی طرح اس کی روایت کو امام ابوداؤد اور نسائی رحمہما اللہ نے بھی بیان کیا ہے۔ (صحیح: سنن أبی داؤد : 1236)\nاور صلاۃ ِ خوف کی بابت دیگرکئی احادیث بھی موجود ہیں، مثلاً: امام بخاری رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما کی روایت کو بیان کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے تو لوگ بھی آپ صلی اللہ علیہ وسلم کے ساتھ کھڑے ہوگئے، آپ صلی اللہ علیہ وسلم نے تکبیر کہی تو ان سب نے بھی آپ صلی اللہ علیہ وسلم کے ساتھ تکبیر کہی، آپ صلی اللہ علیہ وسلم نے رکوع کیا تو ان میں سے کچھ لوگوں نے آپ صلی اللہ علیہ وسلم کے ساتھ رکوع کیا، پھر آپ صلی اللہ علیہ وسلم نے سجدہ کیا تو انہوں نے بھی آپ صلی اللہ علیہ وسلم کے ساتھ سجدہ کیا، پھرآپ صلی اللہ علیہ وسلم دوسری رکعت کے لیے کھڑے ہوئے تو جن لوگوں نے سجدہ کر لیا تھا وہ اُٹھ گئے اور انہوں نے اپنے بھائیوں کا پہرہ دینا شروع کر دیا اور دوسرے لوگ آگئے اور انہوں نے آپ صلی اللہ علیہ وسلم کے ساتھ رکوع اور سجدہ کیا اور اس طرح سب لوگو ں نے ایک دوسرے کا پہرہ دیتے ہوئے نماز ادا کر لی۔ (صحیح البخاری : 944)\nامام احمد رحمہ اللہ نے حضر ت جابر بن عبداللہ رضی اللہ عنہما کی حدیث کو بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں نماز خوف اس طرح پڑھائی کہ ایک صف آپ صلی اللہ علیہ وسلم کے آگے کھڑی ہو گئی اور دوسری آپ صلی اللہ علیہ وسلم کے پیچھے تو جوصف آپ صلی اللہ علیہ وسلم کے پیچھے تھی اسے آپ صلی اللہ علیہ وسلم نے پوری ایک رکعت پڑھائی، پھر یہ صف آگے بڑھ گئی اور اپنے ساتھیوں کی جگہ پر جا کھڑی ہوئی اور وہ لوگ ان کی جگہ پر آکر کھڑے ہوگئے، انہیں بھی رسول اللہ صلی اللہ علیہ وسلم نے ایک مکمل رکعت پڑھائی اور سلام پھیر دیا، اس طرح نبی اکرم صلی اللہ علیہ وسلم کی تو دو رکعتیں تھیں مگر صحابۂ کرام رضی اللہ عنہم نے ایک ہی رکعت پڑھی۔ (مسند أحمد) اس حدیث کو امام نسائی رحمہ اللہ نے بھی روایت کیا ہے۔(سنن النسائی : 1546) اور صحیح مسلم میں ایک دوسر ی سند سے بالفاظ دیگر منقول ہے۔ (صحیح مسلم: 840) علاوہ ازیں محدثین کی ایک بڑی جماعت نے اس حدیث کو اپنی کتب صحاح، سنن اور مسانید میں سیّدنا جابر بن عبداللہ رضی اللہ عنہما ہی سے روایت کیا ہے۔ (صحیح ابن خزیمۃ :1347 والسنن الکبرٰی للبیہقی)\nامام ابن ابو حاتم رحمہ اللہ نے سالم کی اپنے باپ سے روایت کو بیان کیا ہے کہ یہ آیت کریمہ :﴿وَاِذَا كُنْتَ فِيْهِمْ فَاَقَمْتَ لَهُمُ الصَّلٰوةَ﴾ نمازِ خوف کے بارے میں نازل ہوئی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے دو میں سے ایک جماعت کو ایک رکعت پڑھائی اور دوسری جماعت اس وقت دشمن کے بالمقابل تھی، تو رسول اللہ صلی اللہ علیہ وسلم نے اس جماعت کو بھی ایک رکعت پڑھائی جو دشمن کے بالمقابل تھی،پھر آپ صلی اللہ علیہ وسلم نے سلام پھیر دیا اور دونوں جماعتوں نے کھڑے ہو کر اپنے طور پر ایک ایک رکعت پڑھ لی۔ (تفسیر ابن أبی حاتم : 1054/4) اس حدیث کو محدثین رحمہم اللہ کی ایک جماعت نے بطریق ِ معمر اپنی کتابو ں میں روایت کیا ہے۔(صحیح البخاری : 4133، صحیح مسلم :839) علاوہ ازیں یہ حدیث صحابۂ کرام رضی اللہ عنہم کی ایک جماعت سے بہت سی سندوں کے ساتھ مروی ہے۔ (ان صحابۂ کرام رضی اللہ عنہم میں سیّدنا جابر، حذیفہ، زید بن ثابت، ابن عباس، ابوہریرہ، ابن مسعود، سہل بن ابوحثمہ اور ابو عیاش زُرَقِي رضی اللہ عنہم شامل ہیں۔) حافظ ابو بکر بن مَرْدُويهَ نے اس کی سندوں اور الفاظ کو بہت احسن انداز میں یکجا بیان کر دیا ہے، نیز امام ابن جریر رحمہ اللہ نے بھی اسی طرح اس کے تمام طرق و الفاظ ایک ہی جگہ بیان کر دیے ہیں۔\n(تفسیر الطبری : 340/5،341)\nآیت کریمہ کے بظاہر الفاظ کے مطابق نمازِ خوف میں ہتھیار اُٹھانے کا حکم علماء کی ایک جماعت کے نزدیک وجوب پر محمول ہے۔ اور اس کی دلیل یہ ارشاد باری تعالیٰ ہے : ﴿وَلَا جُنَاحَ عَلَيْكُمْ اِنْ كَانَ بِكُمْ اَذًى مِّنْ مَّطَرٍ اَوْ كُنْتُمْ مَّرْضٰۤى اَنْ تَضَعُوْۤا اَسْلِحَتَكُمْۚ وَخُذُوْا حِذْرَكُمْؕ﴾ ’’اگر تم بارش کے سبب تکلیف میں ہو یا بیمار ہو تو تم پر کچھ گناہ نہیں کہ ہتھیار اتار رکھو، مگر ہوشیار ضرور رہنا۔‘‘یعنی ہر وقت اس طرح چوکنے رہنا کہ جب بھی تمہیں ہتھیار پہننے کی ضرورت محسوس ہو تو بلا تکلف پہن سکو۔ ﴿اِنَّ اللّٰهَ اَعَدَّ لِلْكٰفِرِيْنَ عَذَابًا مُّهِيْنًا۰۰۱۰۲﴾ ’’بلاشبہ اللہ تعالیٰ نے کافروں کے لیے ذلت کا عذاب تیار کر رکھا ہے۔‘‘\nاس آیت میں نماز خوف کا طریقہ بیان کیا گیا ہے۔ نماز خوف کی کئی صورتیں ممکن ہیں۔ اور احادیث میں ایسی چھ سات صورتیں مذکور بھی ہیں۔ وہ صورتیں اس طرح بنتی ہیں کہ مقتدی جس نے ایک رکعت امام کے ساتھ ادا کی ہے تو آیا وہ دوسری رکعت خود موقع ملنے پر ادا کرے گا یا نہیں ؟ یا اگر کرے گا تو کیسے کرے گا اور نماز مغرب جس کی قصر بھی تین رکعت ہے اس کی صورت کیا ہوگی؟ اور غالبًا یہ طریقہ صرف اس ہنگامی حالت کے لیے ہے جب کہ معرکہ کا ر راز گرم نہ ہوا ہو۔ کیوں کہ معرکہ گرم ہونے کی صورت میں تو جماعت کا موقع ہی نہیں آتا۔ جیسا کہ جنگ خندق میں رسول اللہ صلی اللہ علیہ وسلم سمیت اکثر مسلمانوں کی نماز عصرقضا ہو گئی جو آپ صلی اللہ علیہ وسلم نے اور مجاہدین نے سورج غروب ہونے کے بعد قضا کے طور پر ادا کی۔ پھر اس کے بعد نماز مغرب ادا کی۔ (صحیح البخاری)دراصل نماز خوف کے طریق کار کا انحصار بہت حد تک جنگی حالات پر ہے۔ اگر جماعت کا موقع ہی میسر نہ آئے تو انسان اکیلا بھی پڑھ سکتا ہے۔ سواری پر بھی پڑھ سکتا ہے اور اشارے سے بھی پڑھ سکتا ہے۔ بس دو باتوں کو ملحوظ رکھنا ضروری ہے۔ ایک یہ کہ موجودہ جنگی حالات میں کون سا طریقہ بہتر ہے پھر اسے اختیار کیا جائے اور دوسرے یہ کہ ایسے حالات میں اللہ تعالیٰ کی یاد کو بھلانا نہیں چاہیے۔ ا ب اس ضمن میں درج ذیل احادیث ملاحظہ فرمایے :\n1:\nسیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ ’’اللہ تعالیٰ نے تمہارے نبی صلی اللہ علیہ وسلم کی زبان سے حضر میںچار، سفر میں دو اور خوف میں ایک رکعت نماز فرض کی ہے۔ ‘‘ (صحیح مسلم)\n2:\nنماز خوف کی مختلف صورتیں :سیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ضجنان اور عسفان کے درمیان پڑائو کیا۔ مشرکوں نے کہا:ان مسلمانوں کی ایک نماز ہے جسے وہ اپنے باپ اور بیٹوں سے زیادہ محبوب رکھتے ہیں اور وہ عصر کی نماز ہے لہٰذا تم اپنے اسباب جمع کرو اور اس وقت یکبارگی ان پر حملہ کردو۔ اتنے میں جبریل علیہ السلام نازل ہوئے اور نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا کہ وہ اپنے اصحاب رضی اللہ عنہم کے دو حصے کریں۔ ایک حصے کو نماز پڑھائیں اور دوسرا حصہ دشمن کے مقابل ان کے پیچھے کھڑارہے اور اپنی ڈھالیں اور اپنے ہتھیار پہنے رہیں۔ پھر دوسرا حصہ آئے اور آپ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھے اور پہلے حصے والے اپنی ڈھالیں اور ہتھیار پہن لیں۔ اس طرح ہر گروہ کی ایک ایک رکعت، اور نبی اکرم صلی اللہ علیہ وسلم کی دو رکعتیں ہوں گی۔ (سنن ترمذی)\n3:\nسیدنا عبداللہ بن عمر رضی اللہ عنہ سےجب کوئی پوچھتا کہ ہم نماز خوف کیسے پڑھیں ؟ تووہ کہتے کہ ’’امام آگے بڑھے کچھ لوگ اس کے ساتھ نماز ادا کریں۔ امام انہیں ایک رکعت پڑھائے۔ باقی لوگ ان کے اور دشمنوں کے درمیان کھڑے رہیں۔نماز نہ پڑھیں۔جب یہ لوگ امام کے ساتھ ایک رکعت پڑھ چکیں تو سرک کر پیچھے چلے جائیں اور جنھوںنے نماز نہیں پڑھی اب وہ لوگ آجائیں اور امام کے ساتھ ایک رکعت پڑھیں۔ امام تو اپنی نماز (دو رکعت) سے فارغ ہو گیا۔ اب یہ دونوں گروہ باری باری ایک ایک رکعت پوری کر لیں تو ان کی بھی دو دو رکعت ہو جائیں گی اور اگر خوف اس سے زیادہ ہو تو پائوں پر کھڑے کھڑے، پیدل یا سواری پر رہ کر نماز ادا کر لیں۔ منہ قبلہ رخ ہو یا نہ ہو۔ ‘‘ امام مالک رحمہ اللہ کہتے ہیں کہ نافع رحمہ اللہ نے کہا کہ عبداللہ بن عمر رضی اللہ عنہ نے یہ رسول اللہ صلی اللہ علیہ وسلم سے نقل کیا ہے۔ (صحیح البخاری)\nآیت مذکورہ میں صرف دو صورتوں میں ہتھیار اتارنے کی اجازت ہے۔ پہلی یہ کہ بارش ہو رہی ہو کپڑے اور ہتھیار بھیگ رہے ہوں۔ دوسری یہ کہ کوئی شخص بیماری کی وجہ سے ہتھیار بند رہنے کا متحمل نہ ہو۔ ان صورتوںکے علاوہ ہتھیار اُتارنے کی اجازت نہیں۔ اس لیے آخر میں تاکیدی طور پر دوبارہ سہ بارہ اس حکم کو دہرایا۔\n﴿خُذُوْا حِذْرَكُمْ﴾ کے الفاظ بڑے وسیع مفہوم میں استعمال ہوتے ہیں، اس کے معنی ہوشیار اور چوکنا رہنا مسلح رہنا اور اپنے بچائو کے تمام ذرائع اختیار کیے رکھنا ہے۔ مثلاً: مورچوں کی حفاظت کرنا اور ان میں پناہ پکڑنا، لڑائی سے پہلے سامان جنگ تیار رکھنا۔ دشمن کی نقل و حرکت سے باخبر رہنا، اس کا مداوا سوچنا بے خبری میں دشمن کے حملے کے لیے تیار رہنا سب کچھ ﴿خُذُوْا حِذْرَكُمْ﴾ کے مفہوم میں سما جاتا ہے۔ دورِ نبوی صلی اللہ علیہ وسلم میں اسلحہ جنگ ہر مجاہد کی انفرادی ملکیت ہوتا تھا مگر آج اسلحہ جنگ مہیا کرنا حکومت کی ذمہ داری ہے لہٰذا اسلحہ جنگ کے تیار کرنے والے کارخانوں، اسلحہ کے ذخائر اور دشمن سے ان کا بچائو بھی ﴿خُذُوْا حِذْرَكُمْ﴾ میں شامل ہے۔ غرض قوم و ملک کا تحفظ، افراد فوج کے تحفظ کی تدابیر، آلات جنگ کا تحفظ، لڑائی کے منصوبوں کو صیغہ راز میں رکھنا سب کچھ اس حکم میں داخل ہے۔ آج دشمن سب سے پہلے اسلحہ کے محفوظ ذخائر کو یا اسلحہ ساز فیکٹریوں کو اچانک حملے کے ذریعے تبا ہ کر دیتا ہے۔ ان سب اُمور کی طرف مسلمانوں کو اس آیت میں متوجہ کیا گیا ہے۔\nاس آیت میں صلٰوۃ الخوف کی اجازت بلکہ حکم دیا جا رہا ہے۔ صلٰوۃ الخوف کے معنی ہیں، خوف کی نماز۔ یہ اس وقت مشروع ہے جب مسلمانوں او رکافروں کی فوجیں ایک دوسرے کے مقابل جنگ کے لیےتیا رکھڑی ہوں اور ایک لمحے کی بھی غفلت مسلمانوں کے لیے سخت خطرناک ثابت ہو سکتی ہو۔ ایسے حالات میں اگر نماز کا وقت ہو جائے تو صلٰوۃ الخوف پڑھنے کا حکم ہے،جس کی مختلف صورتیں حدیث میں بیان کی گئی ہیں۔ مثلاً فوج دو حصو ں میں تقسیم ہو گئی۔ ایک حصہ دشمن کے بالمقابل کھڑارہا تاکہ کافروں کو حملہ کرنے کی جسارت نہ ہو اور ایک حصے نے آکر نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی۔ جب یہ حصہ نماز سے فارغ ہو گیا تو پہلے کی جگہ مورچہ زن ہو گیا اور مورچہ زن حصہ نماز کے لیے آگیا۔ بعض روایات میں آتا ہے کہ آپ صلی اللہ علیہ وسلم نے دونوں حصوں کو ایک ایک رکعت نماز پڑھائی، اس طرح آپ صلی اللہ علیہ وسلم کی دو رکعت اور باقی فوجیوں کی ایک ایک رکعت ہوئی۔ بعض میں آتا ہے کہ دو دو رکعات پڑھائیں، اس طرح آپ صلی اللہ علیہ وسلم کی چار رکعت اور فوجیوںکی دو دو رکعت ہوئیں اور بعض میں آتا ہے کہ ایک رکعت پڑھ کر التحیات کی طرح بیٹھے رہے، فوجیوں نے کھڑے ہو کر اپنے طو رپر ایک رکعت اور پڑھ کر دو رکعات پوری کیں اور دشمن کے سامنے جا کر ڈٹ گئے۔ دوسرے حصے نے آکر نبی صلی اللہ علیہ وسلم کے پیچھے نما زپڑھی، آپ صلی اللہ علیہ وسلم نے انہیں بھی ایک رکعت پڑھائی اور التحیات میں بیٹھ گئے اور اس وقت تک بیٹھے رہے جب تک فوجیوں نے دوسری رکعت پوری نہیں کر لی۔ پھر ان کے ساتھ آپ صلی اللہ علیہ وسلم نے سلام پھیر دیا۔ اس طرح آپ صلی اللہ علیہ وسلم کی بھی دو رکعت اور فوج کی دونوں حصوں کی بھی دو دو رکعات ہوئیں۔\nشانِ نزول : تفسیر ابن جریر میں وضاحت ہے سلیمان بن قیس یشکری نے جا بر بن عبداللہ رضی اللہ عنہ سے استفسار کیاقصر نماز کا حکم کب نازل ہوا جابر رضی اللہ عنہ نے بیان کیا کہ ہم سفر کر رہے تھے ہمارا مقصود قریش کا ایک قافلہ تھا جو ملک شام سے واپس آرہا تھا جب ہم نخلہ مقام میں پہنچے تو دشمن لوگوں سے ایک شخص آپ صلی اللہ علیہ وسلم کے پاس پہنچا اس نے آپ صلی اللہ علیہ وسلم کو مخاطب کرکے کہا اے محمد صلی اللہ علیہ وسلم ! آپ صلی اللہ علیہ وسلم مجھے سے ڈرتے ہیں آپ صلی اللہ علیہ وسلم نے نفی میں جواب دیا پھر اس نے آپ صلی اللہ علیہ وسلم سے دریافت کیا کون آپ صلی اللہ علیہ وسلم کو مجھ سے تحفظ عطا کرے گا ؟ آپ صلی اللہ علیہ وسلم نے جواب دیا مجھے اللہ پاک بچائے گا اس کے بعد اس نے تلوار کو میان سے نکالا آپ صلی اللہ علیہ وسلم کو دھمکی دی اور اپنے حملہ کا وقت بتایا بعد ازاں اس نے کوچ کا علان کیا ہتھیاروں کو سنبھالا اور چلا گیا اس وقت نماز کی اذان دی گئی تھی آپ صلی اللہ علیہ وسلم نے اپنے لشکر کو دوحصوںمیں تقسیم کیا ایک جماعت آپ صلی اللہ علیہ وسلم کے ساتھ نماز ادا کر رہی تھی اور دوسری جماعت حفاظت کر رہی تھی آپ صلی اللہ علیہ وسلم نے دونوں گروہوں کو دودو رکعت نماز پڑھائی اس واقعہ میں آپ صلی اللہ علیہ وسلم کی نماز چار رکعت تھی جب کہ صحابہ کرام رضی اللہ عنہم نے دو رکعت ادا کی اس وقت نماز قصر کا حکم نازل ہوا آپ صلی اللہ علیہ وسلم نے حکم دیا کہ نماز ادا کرتے وقت اسلحہ ساتھ ہو۔ (تفسیر ابن کثیر : 833/1، تفسیر ابن جریر)"],[1287,"§نمازِ خوف کی صورتیں\nمختلف ہیں کبھی دشمن قبلہ کی جانب ہوتا ہے اور کبھی دوسری جہت میں ہوتا ہے اور نماز کبھی چار رکعات کبھی دو رکعات کبھی تین رکعات والی ہوتی ہے کبھی باجماعت کبھی شدت کی جنگ میں بلا جماعت اکیلے اکیلے نماز ادا کرنے کا حکم ہے رُخ قبلہ کی جانب ہو یا نہ ہو سواری پر ہوں یا پیادہ ہوں بلکہ ضرورت کے پیش نظر نمازادا کرتے وقت چلے پھریں لیکن شدید خوف کے وقت نماز صرف ایک رکعت ہے اس میں اگر اشارہ کے بغیر ممکن نہ ہو تواشارہ کی صورت میں ادا کی جائے۔ ضرورت کے پیش نظر نماز کی ادائیگی میں تاخیر کرنا بھی جائز ہے جیسا کہ جنگ احزاب میں آپ صلی اللہ علیہ وسلم نے ظہر، عصر کی نمازیں سورج کے غروب ہونے کے بعد ادا کیں۔ پھر بنو قریظہ کے محاصرہ کے وقت آپ صلی اللہ علیہ وسلم نے حکم دیا کہ ہر ساتھی عصر کی نماز بنو قریظہ میں ادا کرے چنانچہ بعض صحابہ کرام رضی اللہ عنہم نے اپنے اوقات پر ظہر، عصر کی نماز اد اکی جب کہ بعض صحابہ رضی اللہ عنہم نے سورج کے غروب ہونے کے بعد بنو قریظہ میں عصر کی نماز ادا کی آپ صلی اللہ علیہ وسلم نے کسی کو ڈانٹ دی۔ (ابن کثیر : 830/1، صحیح البخاری)\nہجرت اور سفر کی مناسبت کے پیش نظر سفر میں نماز قصر دو رکعت ادا کرنے کا حکم دیا گیا ہے جب تم زمین میں سفر کر رہے ہو تو تم پر کچھ گناہ نہیں، تنگی نہیں کہ تم نماز قصر ادا کرو جب تمہیں دشمن کا خطرہ ہو جب کہ سنت مطہرہ نے واضح کر دیا ہے کہ مسافر شخص کو اگرچہ کوئی خوف نہ ہوا من و اطمینان ہو تو وہ نماز قصر ادا کرے تو خوف کی قید اغلب حال پر ہے۔ آخر میں اس کا سبب بیان کیا ہے کہ کفار تو تمہارے دشمن ہیں اس لیے رخصت عطا کی ہے اس کے بعد والی دونوں آیات میں نماز خوف کی مکمل تصویر کشی کی گئی ہے۔ اسلامی لشکر کو دو حصوں میں تقسیم کر دیا جائے ایک حصہ دشمن کے سامنے رہے اور دوسرا حصہ لشکر کے قائد کی معیت میں ایک رکعت ادا کرے پھر امام اپنی جگہ پر کھڑا رہے اس کے مقتدی دوسری رکعت اکیلے ادا کریں اور سلام پھیرنے کے بعد دشمن کے سامنے کھڑے ہو جائیں۔ لشکر کا دوسرا حصہ آئے جو دشمن کے سامنے کھڑا تھا ان کو امام ایک رکعت پڑھائے گا امام سلام پھیر دے گا اس کے مقتدی اپنی اپنی ایک رکعت اکیلے ادا کرکے سلام پھیر دیں گے۔\nان دونوں حالتوں میں وہ اپنا اسلحہ اپنےساتھ رکھیں گے اسے زمین پر نہیں رکھیں گے اس خطرہ کے پیش نظر کہ کہیں دشمن ان کی جانب جھکائو کرکے انہیں نقصان نہ پہنچا سکے۔ اللہ پاک کے اس ارشاد :\n﴿وَاِذَا كُنْتَ فِيْهِمْ فَاَقَمْتَ لَهُمُ الصَّلٰوةَ فَلْتَقُمْ طَآىِٕفَةٌ مِّنْهُمْ مَّعَكَ وَلْيَاْخُذُوْۤا اَسْلِحَتَهُمْ١۫ࣞ فَاِذَا سَجَدُوْا فَلْيَكُوْنُوْا مِنْ وَّرَآىِٕكُمْ١۪﴾ کا یہی مفہوم مقصود ہے اسلامی لشکر کا وہ حصہ جو دشمن کے سامنے ہے تاکہ اسلامی لشکر کو دشمن سے تحفظ حاصل رہے۔\n﴿وَلْتَاْتِ طَآىِٕفَةٌ اُخْرٰى لَمْ يُصَلُّوْا فَلْيُصَلُّوْا مَعَكَ وَلْيَاْخُذُوْا حِذْرَهُمْ وَاَسْلِحَتَهُمْۚ﴾ نیز ارشادِ الٰہی ﴿وَدَّ الَّذِيْنَ كَفَرُوْا لَوْ تَغْفُلُوْنَ عَنْ اَسْلِحَتِكُمْ وَاَمْتِعَتِكُمْ فَيَمِيْلُوْنَ عَلَيْكُمْ مَّيْلَةً وَّاحِدَةًؕ﴾ اس کلام کے لانے سے مقصود یہ بتانا ہے کہ نماز کی ادائیگی کے لیے لشکر کو دو حصوں میں کیوں تقسیم کیا گیا ہے اور نماز کی ادائیگی کی حالت میں بھی احتیاط اور اسلحہ کو اپنے ساتھ رکھنے کا حکم دیا گیا ہے لیکن اگر فوج کے کچھ مجاہد بیمار ہیں زخمی ہیں یا بارش کی کیفیت ہے ہتھیاروں کا اُٹھانا مشکل ہے تو وہ اپنے اسلحہ کو زمین پر رکھیں۔ ارشادِ الٰہی ہے :\n﴿وَلَا جُنَاحَ عَلَيْكُمْ اِنْ كَانَ بِكُمْ اَذًى مِّنْ مَّطَرٍ اَوْ كُنْتُمْ مَّرْضٰۤى اَنْ تَضَعُوْۤا اَسْلِحَتَكُمْۚ وَخُذُوْا حِذْرَكُمْؕ اِنَّ اللّٰهَ اَعَدَّ لِلْكٰفِرِيْنَ عَذَابًا مُّهِيْنًا۰۰۱۰۲﴾ یہاں محذوف کلام کو ذکر کیا گیا ہے۔ وضاحت یوں ہے کہ کفار تو فاجر وفاسق ہیں ان کی طرف سے امن نہیں ہے یہی وجہ ہے کہ اللہ تعالیٰ نے ان کے لیے ایسا عذاب تیار کررکھا ہے جو انہیں رسوا کرے گا۔\n﴿فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيٰمًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِكُمْۚ فَاِذَا اطْمَاْنَنْتُمْ فَاَقِيْمُوا الصَّلٰوةَۚ اِنَّ الصَّلٰوةَ كَانَتْ عَلَى الْمُؤْمِنِيْنَ كِتٰبًا مَّوْقُوْتًا۰۰۱۰۳ وَلَا تَهِنُوْا فِي ابْتِغَآءِ الْقَوْمِؕ اِنْ تَكُوْنُوْا تَاْلَمُوْنَ فَاِنَّهُمْ يَاْلَمُوْنَ كَمَا تَاْلَمُوْنَۚ وَتَرْجُوْنَ مِنَ اللّٰهِ مَا لَا يَرْجُوْنَؕ وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًاࣖ۰۰۱۰۴﴾\nپھر جب تم نماز ادا کر چکو تو کھڑے ہوئے، بیٹھے ہوئے اور لیٹے ہوئے (ہر حال میں) اللہ کو یاد کرتے رہو، پھر جب تمہیں اطمینان ہو جائے تو (پوری) نماز پڑھو، بے شک مومنوں پر مقررہ وقتوں میں نماز فرض ہے اور تم دشمن قوم کا پیچھا کرنے میں کمزوری نہ دکھائو۔ اگر تم تکلیف اٹھاتے ہو تو بے شک وہ بھی تکلیف اٹھاتے ہیں جیسے تم تکلیف اٹھاتے ہو۔ اور تم اللہ سے جس چیز کی امید\nرکھتے ہو، وہ اس کی امید نہیں رکھتے۔ اور اللہ خوب جاننے والا، بہت حکمت والا ہے"],[1288,"§نمازِ خوف کے بعد کثرت سے ذکر ِ الٰہی کا حکم\nاللہ تعالیٰ نے حکم دیا ہے کہ نمازِ خوف کے بعد کثرت سے اس کا ذکر کیاجائے گوذکرِ الٰہی دیگر تمام نمازوں کے بعد بھی مشروع اور مرغوب ہے لیکن نمازِ خوف کے بعد اس کی زیادہ تاکید ہے کیوں کہ اس نماز کے ارکان میں تخفیف کر دی گئی ہے۔ اور اس میں آنے جانے کی بھی رخصت ہے، علاوہ ازیں او ربھی کئی سہولتیں ہیں جو دیگر نمازوں میں نہیں ہیں جیسا کہ اللہ تعالیٰ نے حرمت والے مہینوں کے بارے میں فرمایا ہے : ﴿فَلَا تَظْلِمُوْا فِيْهِنَّ اَنْفُسَكُمْ﴾ (التوبۃ:36) ’’تو ان (مہینوں) میں اپنے آپ پر ظلم نہ کرنا۔‘‘\nاگرچہ دوسرے مہینوں میں بھی ظلم کرنا منع ہے لیکن حرمت والے مہینوں کی سخت حرمت و عظمت کی وجہ سے اس کی ممانعت کی زیادہ تاکید ہے، اسی وجہ سے اللہ تعالیٰ نے یہاں فرمایاہے : ﴿فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيٰمًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِكُمْۚ﴾ ’’پھر جب تم نماز تمام کر چکو تو کھڑے اور بیٹھے اور لیٹے اللہ تعالیٰ کو یاد کرو۔ ‘‘ یعنی ہر ہر حالت میں اللہ تعالیٰ کا ذکر کرو۔ ﴿فَاِذَا اطْمَاْنَنْتُمْ فَاَقِيْمُوا الصَّلٰوةَۚ﴾ ’’پھر جب خوف جاتا رہے تو (اس طرح سے) نما زپڑھو (جس طرح امن کی حالت میں پڑھتے ہو)۔‘‘ یعنی جب امن حاصل ہو جائے، خوف جا تا رہے اور طمانیت حاصل ہو جائے تو پوری نماز پڑھو اور اسے اس طرح پڑھو جس طرح تمہیں اس کی حدود، خشوع، رکوع، سجود اور دیگر تمام ارکان کے ساتھ ادا کرنے کا حکم دیا گیاہے۔\n﴿اِنَّ الصَّلٰوةَ كَانَتْ عَلَى الْمُؤْمِنِيْنَ كِتٰبًا مَّوْقُوْتًا۰۰۱۰۳﴾ ’’بے شک نماز کا مومنوں پر اوقات (مقررہ) میں ادا کرنا فرض ہے۔‘‘ سیّدنا ابن عباس رضی اللہ عنہما فرماتے ہیں : ﴿كِتٰبًا مَّوْقُوْتًا۰۰۱۰۳﴾ کے معنی ہیں مفروضًا، یعنی اسے اپنے اوقات میں ادا کرنا فرض ہے۔(تفسیر ابن أبی حاتم : 1057/4) مجاہد، سالم بن عبداللہ، علی بن حسین، محمدبن علی، حسن، مُقاتِل، سدی اور عطیہ عوفی رحمہم اللہ سے بھی اسی طرح مروی ہے۔(تفسیر ابن أبی حاتم : 1057/4) سیّدنا عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا ہے کہ نماز کا وقت بھی حج کے وقت کی طرح مقرر ہے۔ (تفسیر الطبری : 355/5)"],[1289,"§زخمی ہونے کے باوجود دشمن کے تعاقب کی ترغیب\nارشادِ باری تعالیٰ ہے : ﴿وَلَا تَهِنُوْا فِي ابْتِغَآءِ الْقَوْمِؕ﴾ ’’اور کفار کا پیچھا کرنے میں سستی نہ کرنا۔ ‘‘ یعنی دشمن کی تلاش میں کسی کمزوری کاثبوت نہ دو بلکہ ان کا تعاقب کرو، ان سے خوب لڑو، اور گھات کی جگہ ان کی تاک میں بیٹھے رہو۔ ﴿اِنْ تَكُوْنُوْا تَاْلَمُوْنَ فَاِنَّهُمْ يَاْلَمُوْنَ كَمَا تَاْلَمُوْنَۚ﴾ ’’اگر تم بے آرام ہوتے ہو تو اسی طرح وہ بھی بے آرام ہوتے ہیں جیسے تم بے آرام ہو تے ہو۔ ‘‘یعنی اگر تم زخمی اور قتل ہوتے ہو وہ بھی تو اسی طرح زخمی اور قتل ہوتے ہیں جیسا کہ اللہ تعالیٰ نے فرمایا ہے :﴿اِنْ يَّمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِّثْلُهٗؕ﴾ (آل عمران:140) ’’اگر تمہیں زخم (شکست) لگا ہے تو ان لوگوں کو بھی ایسا زخم لگ چکا ہے۔ ‘‘\nپھر اللہ تعالیٰ نے فرمایا:﴿وَتَرْجُوْنَ مِنَ اللّٰهِ مَا لَا يَرْجُوْنَؕ﴾ ’’اور تم اللہ تعالیٰ سے (ایسی ایسی) اُمیدیں رکھتے ہو جو وہ نہیں رکھ سکتے۔‘‘ مطلب یہ ہے کہ جو تمہیں اور انہیں زخم اور دکھ پہنچتے ہیں، اس اعتبار سے تو تم سب برابر ہو مگر تم اللہ تعالیٰ سے ثواب اور نصرت و حمایت کی اُمید رکھتے ہو جیسا کہ اس نے تم سے اپنی کتاب میں اور اپنے رسول صلی اللہ علیہ وسلم کی زبانی وعدہ فرمایا ہے اور اس کا وعدہ برحق اور اس کی خبر سچی ہے لیکن تمہارے دشمنوں کو اس طرح کی کسی چیز کی اُمید نہیں ہے، لہٰذا تم ہی ان کی نسبت جہا دکرنے کے زیادہ حق دار ہو اور تمہیں ہی اللہ تعالیٰ کے کلمے کی اقامت اور سربلندی کی زیادہ شدید رغبت ہونی چاہیے۔﴿وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًاࣖ۰۰۱۰۴﴾ ’’اور اللہ تعالیٰ سب کچھ جانتا (اور) خوب حکمت والا ہے۔ ‘‘ اللہ تعالیٰ زیادہ علم و حکمت والا ہے اپنے ان تکوینی اور شرعی احکام کے بارے میں جن کا وہ فیصلہ فرما دیتا اور جنھیں نافذ کر دیتا ہے، اس کی ذات ِ گرامی ہر حال میں قابلِ ستائش ہے۔"],[1290,"§نمازوں کے اوقات\nجنگ میں نماز اسی وقت ہی ادا کی جا سکتی ہے جب موقع ملے، اس دور ان بھی اللہ تعالیٰ کو ہر وقت یاد رکھنا چاہیے پھر جب حالات معمول پر آجائیں تو نماز بھی معمول کے مطابق پڑھی جائے اور نمازوں کے اوقات کا بھی خیال رکھا جائے۔ احادیث کی رُو سے نمازوں کے اوقات درج ذیل ہیں :\n1:\nآپ صلی اللہ علیہ وسلم نے فرمایا:’’ ظہر کا وقت سورج ڈھلنے سے لے کر آدمی کا سایہ اس کے برابر ہونے تک ہے۔ اور عصر کا وقت (سایہ برابر ہونے سے لے کر) دھوپ میں زردی آنے تک ہے۔ اور نماز مغرب کا وقت (سورج غروب ہونے سے لے کر) شفق غائب ہونے تک ہے اور عشاء کا وقت (شفق غائب ہونے سے لے کر ٹھیک آدھی رات تک ہے اور صبح کا وقت طلوع فجر سے لے کر طلوع آفتاب تک ہے۔ ‘‘ (صحیح مسلم)\n2:\nسیّدنا عبداللہ بن عمر رضی اللہ عنہما اور ابوہریرہ رضی اللہ عنہ دونوں فرماتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:’’ گرمی کے موسم میں ظہر کی نماز کو ٹھنڈا کرکے پڑھا کرو اس لیے کہ گرمی کی سختی دوزخ کی بھاپ سے ہوتی ہے۔ ‘‘ (صحیح البخاری، صحیح مسلم)\n3:\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ ہم عورتیں چادروں میںلپٹی ہوئی جب نماز صبح سے فارغ ہو کر مسجد سے نکلتیں تو اندھیرے کی وجہ سے کوئی ان کو پہچان نہ سکتا تھا۔ (صحیح البخاری)\n4:\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک دفعہ آپ صلی اللہ علیہ وسلم نے عشاء کی نماز اس وقت پڑھائی جب رات کا کافی حصہ گزر چکا تھا۔ پھر فرمایا:’’ اگر میری اُمت پر یہ بات شاق نہ ہوتی تو عشاء کی نماز کا اصل وقت یہی وقت ہے۔ ‘‘ (صحیح البخاری)\n5:\nسیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ ’’آپ صلی اللہ علیہ وسلم صبح کی نماز اس وقت پڑھاتے جب ہم میں سے کوئی شخص (فراغت کے بعد) اپنے ساتھ والے کو پہچان لیتا اور آپ صلی اللہ علیہ وسلم اس نماز میں ساٹھ سے لے کر سو تک آیتیں پڑھتے۔ اور ظہر اس وقت پڑھتے جب سورج ڈھل جاتا۔ اور عصر اس وقت کہ کوئی شخص عصر پڑھ کر شہر کے پرلے حصہ (تقریباً چار میل) تک اپنے گھر جاتا تو سورج ابھی تیز ہوتا اور شام سورج غروب ہونے پر اور عشاء کی نماز میں تہائی رات تک دیر کرنے کی پروا نہیں کرتے تھے۔ (صحیح البخاری)\n6:\nسیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ جب کوئی شخص سورج ڈوبنے سے پہلے عصر کی ایک رکعت پالے وہ اپنی نماز پوری کرے (اس کی نماز ادا ہوئی یا قضا) اور جو سورج نکلنے سے پہلے فجر کی ایک رکعت پالے وہ بھی اپنی نماز پوری کرے۔ ‘‘(صحیح البخاری)\n7:\nسیدنا ابن عباس رضی اللہ عنہما فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے صبح کی نماز کے بعد سورج چڑھنے تک نماز پڑھنے سے منع کیا۔ اور عصر کی نما زکے بعد سورج ڈوبنے تک۔ (صحیح البخاری)\n8:\nعبداللہ بن ابی قتادہ رضی اللہ عنہ اپنے باپ سے روایت کرتے ہیں کہ ہم (خیبر سے واپسی پر) رات کو آپ صلی اللہ علیہ وسلم کے ہمراہ سفر کر رہے تھے۔ بعض لوگوں نے کہا’’یا رسول اللہ صلی اللہ علیہ وسلم! کیا اچھا ہو جو یہاں اتر پڑیں۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ مجھے خطرہ ہے کہ تم سو جائو گے اور نماز فجر کے لیے نہ اُٹھو گے۔‘‘ سیدنا بلال رضی اللہ عنہ نے فرمایا:’’ میں جگادوں گا۔ ‘‘ چنانچہ سب لوگ سو گئے۔ اور بلال رضی اللہ عنہ نے اپنی اونٹنی سے پیٹھ لگائی تو نیند نے غلبہ کیا اور وہ بھی سو گئے پھر آپ صلی اللہ علیہ وسلم اس وقت اُٹھے جب سورج کا کنارہ نکل آیا تھا۔ آپ صلی اللہ علیہ وسلم نے بلال رضی اللہ عنہ سے پوچھا :’’ تمہارا قول کہاں گیا؟‘‘ بلال رضی اللہ عنہ کہنے لگے :’’ مجھے توایسی نیند آئی جیسے پہلے کبھی نہ آئی تھی۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ اللہ تعالیٰ نے جب چاہا تمہاری روحیں قبض کر لیں اور جب چاہا تمہیں واپس دے دیں۔ اے بلال رضی اللہ عنہ ! اُٹھ اور نماز کے لیے اذان دے۔ ‘‘ چنانچہ بلال رضی اللہ عنہ نے اذان دی۔ آپ صلی اللہ علیہ وسلم نے وضو کیا اور جب سورج ذرا بلند اور سفید ہو گیا تو آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور نما زپڑھی۔ (صحیح البخاری)\n9:\nسیدنا انس رضی اللہ عنہ فرماتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ جو شخص نماز ادا کرنا بھول جائے یا اس وقت سویا ہوا ہو تو اس کا کفارہ یہ ہے کہ یاد آتے ہی ادا کر لے۔ ‘‘(صحیح البخاری، صحیح مسلم)\n10:\nآپ صلی اللہ علیہ وسلم نے فرمایا:’’ منافق کی نماز یہ ہے کہ وہ سورج کو دیکھتا رہتا ہے یہاں تک کہ وہ شیطان کے دو سینگوں کے درمیان آجاتا ہے تو اُٹھتا ہے اور چار ٹھونگیں مار لیتا ہے اور اللہ تعالیٰ کا ذکر تھوڑا بہت ہی کرتا ہے۔(صحیح مسلم)\n11:\nسیدہ ام فروہ رضی اللہ عنہا کہتی ہیں کہ کسی نے آپ صلی اللہ علیہ وسلم سے پوچھا کہ کون ساعمل افضل ہے ؟ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ نماز اول وقت پر ادا کرنا۔ ‘‘ (سنن ترمذی)\n12:\nسیدنا عبداللہ بن عمر رضی اللہ عنہ کہتےہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:’’ اللہ تعالیٰ کی خوشنودی نماز کا اول وقت ادا کرنے میں ہے اور آخر وقت میں ادا کرنا اللہ تعالیٰ کی طرف سے معافی ہے۔ ‘‘ (سنن ترمذی)\n13:\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ’’ رسول اللہ صلی اللہ علیہ وسلم نے کوئی بھی نماز آخر وقت میں نہ پڑھی مگر صرف دوبار۔ یہا ں تک کہ وفات پائی۔ ‘‘ (سنن ترمذی)\n14:\nسیدنا علی رضی اللہ عنہ بن ابی طالب فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا:’’ علی رضی اللہ عنہ تین باتوں میں تاخیر نہ کرنا(1)نماز میں جب اس کا وقت آجائے (2)جنازہ کی تدفین میں جب تو وہاں موجود ہو (3)اور رنڈوے مرد یا رنڈوی عورت کے نکاح میں جب کہ اس کا بر(کفو) مل رہا ہو۔ ‘‘ (سنن ترمذی)\n﴿فَاِذَا قَضَيْتُمُ الصَّلٰوةَ﴾ اللہ پاک ایمان والوں کو حکم دے رہے ہیں کہ ہر لمحہ اللہ تعالیٰ کے ذکر میں مشغول رہیں بالخصوص جب دشمن کے ساتھ جنگ کی کیفیت ہو اس وقت تو روحانی قوت کا مادی قوت پر تغلب ہونا چاہیے اسے شکست سے دوچار کیا جائے۔ اس لیے مجاہدین نہ صرف یہ کہ نماز کی ادائیگی کے وقت ذکر الٰہی میںمشغو ل رہیں بلکہ جب نماز کی ادائیگی سے فارغ ہو جائیں تو پھر بھی اللہ تعالیٰ کے ذکر سے غافل نہ رہیں۔\n﴿فَاِذَا اطْمَاْنَنْتُمْ فَاَقِيْمُوا الصَّلٰوةَۚ﴾ جب دشمن کا ڈر نہ رہے امن کی فضا چھا جائے اور اطمینان کی لہر رونما ہو تو نماز کی ادائیگی میں اس کے حدود، شرائط، ارکان کی تکمیل کا خیال رکھو۔ تخفیف کو ختم کیا جائے جب کہ خوف کے وقت تو ایک رکعت نماز کی ادائیگی بھی درست ہے بلکہ اشارات کے ساتھ بھی نماز صحیح ہے جب کہ مجاہدین اور دشمنوں میں مڈبھیڑ کی جنگ ہو۔\n﴿اِنَّ الصَّلٰوةَ كَانَتْ عَلَى الْمُؤْمِنِيْنَ كِتٰبًا مَّوْقُوْتًا۰۰۱۰۳﴾ نماز قائم کرنے کی علت ہے کہ نماز کی ادائیگی تو ایمان داروں پر لازم ہے اور ادائیگی کے لیے بھی وقت مقرر ہے اسی کے وقت میں ہی اس کی ادائیگی ہو۔"],[1291,"§سفر میں نماز قصر کی ادائیگی کا بیان\nرسول اکرم صلی اللہ علیہ وسلم سفر میں ظہر، عصر اور عشاء کی نماز دو رکعت ادا فرماتے۔ صحیح بخاری میں ہے آپ صلی اللہ علیہ وسلم ابو بکر، عمر رضی اللہ عنہما دو رکعت نماز ادا کرتے رہے لیکن سیّدنا عثمان رضی اللہ عنہ اپنی خلافت کے آغاز میں دو رکعت نماز ادا کرتے تھے بعد میں انہوں نے پوری نماز ادا کی۔ اس کا سبب یہ تھا کہ عثمان رضی اللہ عنہ نے منیٰ میں نکاح کر لیا تھا۔ (صحیح البخاری)\nسفر کی نماز میں تخفیف اللہ پاک کی جانب سے صدقہ ہے اس لیے اسے قبول کیا جائے البتہ سفر میں نماز قصر کا بیان قرآن پاک میں نہیں ہے۔ مغرب کی نماز حضر، سفر میں تین رکعت ہی ہے جب کہ خوف کی نماز ایک رکعت ہے نیز دو نمازوں کو جمع کرکے ادا کرنا درست ہے۔ ظہر، عصر کو جمع کیا جائے مغرب عشاء کو جمع کیا جائے نماز قصر اللہ پاک کی جانب سے صدقہ اور تخفیف ہے صحیح مسلم میں مروی حدیث کے مطابق سفر کی مسافت 9 میل 3 میل ہے۔ (المنار : 372/2، صحیح مسلم)\nشانِ نزول : آیت مبارکہ جنگ احد کے موقعہ پر نازل ہوئی جب آپ صلی اللہ علیہ وسلم نے ابو سفیان اور اس کے رفقاء کی تلاش میں چھوٹا سا لشکربھیجا انہوں نے زخموں کی تکالیف کا شکوہ کیا تو اللہ پاک نے فرمایا:” تم درد و الم کا تذکرہ نہ کرو تم مستقل مزاجی اور عزیمت کے ساتھ دشمن کا تعاقب کرو انہیں ڈھونڈنے کی کوشش کرو اگر تم زخموں کی تکلیف سے دو چار ہو تو کچھ شک نہیں کہ وہ بھی تمہاری طرح درد و کرب کی کیفیت میں ہیں۔ جب کہ تمہیں اللہ پاک کی جانب سے کامیابی یا جنت کی اُمید ہے چونکہ وہ مشرک ہیں اس لیے وہ مایوس ہیں ان میں جرأت نہیں، اعتماد نہیں تمہارے لیے مناسب یہی ہے کہ تم ان پر حملہ آور ہوجائو اور اللہ تعالیٰ کا وصف علیم ہے کہ اس کو علم ہے اور وہ حکمت والا ہے۔ چنانچہ اللہ تعالیٰ کا علم اس کی حکمت اور اس کی سنت کا تقاضا ہے کہ ایمان والوں کو کفار پرغلبہ حاصل ہوتا ہے جب تک وہ اللہ کی راہ نمائی کے مطابق رواں دواں رہیں۔ (المنار : 388/5)\n﴿اِنَّاۤ اَنْزَلْنَاۤ اِلَيْكَ الْكِتٰبَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَاۤ اَرٰىكَ اللّٰهُؕ وَلَا تَكُنْ لِّلْخَآىِٕنِيْنَ خَصِيْمًاۙ۰۰۱۰۵ وَّاسْتَغْفِرِ اللّٰهَؕ اِنَّ اللّٰهَ كَانَ غَفُوْرًا رَّحِيْمًاۚ۰۰۱۰۶ وَلَا تُجَادِلْ عَنِ الَّذِيْنَ يَخْتَانُوْنَ اَنْفُسَهُمْؕ اِنَّ اللّٰهَ لَا يُحِبُّ مَنْ كَانَ خَوَّانًا اَثِيْمًاۚۙ۰۰۱۰۷ يَّسْتَخْفُوْنَ مِنَ النَّاسِ وَلَا يَسْتَخْفُوْنَ مِنَ اللّٰهِ وَهُوَ مَعَهُمْ اِذْ يُبَيِّتُوْنَ مَا لَا يَرْضٰى مِنَ الْقَوْلِؕ وَكَانَ اللّٰهُ بِمَا يَعْمَلُوْنَ مُحِيْطًا۰۰۱۰۸ هٰۤاَنْتُمْ هٰۤؤُلَآءِ جٰدَلْتُمْ عَنْهُمْ فِي الْحَيٰوةِ الدُّنْيَا١۫ࣞ فَمَنْ يُّجَادِلُ اللّٰهَ عَنْهُمْ يَوْمَ الْقِيٰمَةِ اَمْ مَّنْ يَّكُوْنُ عَلَيْهِمْ وَكِيْلًا۰۰۱۰۹﴾\n(اے نبی صلی اللہ علیہ وسلم!) بے شک ہم نے آپ کی طرف یہ کتاب حق کے ساتھ نازل کی ہے، تاکہ آپ کو اللہ نے جو سیدھی راہ دکھائی ہے اس کے مطابق لوگوں کے درمیان فیصلہ کریں، اور آپ خیانت کرنے والوں کے حمایتی نہ بنیں اور اللہ سے بخشش مانگیں۔ بے شک اللہ بہت بخشنے والا، نہایت رحم کرنے والا ہے\nاور آپ ان لوگوں کی طرف سے جھگڑا نہ کریں جو اپنے آپ سے خیانت کرتے ہیں۔ بے شک اللہ اس شخص کو پسند نہیں کرتا جو خیانت کرنے والا، گناہ گار ہو\nوہ لوگوں سے (تو اپنی حرکتیں) چھپا سکتے ہیں، مگر اللہ سے نہیں چھپا سکتے اور وہ اس وقت بھی ان کے ساتھ ہوتا ہے جب وہ رات کو چھپ کر ایسا مشورہ کرتے ہیں جو اللہ کو پسند نہیں، اور وہ جو بھی عمل کرتے ہیں اللہ اسے گھیرے ہوئے ہے\nہاں، تم لوگوں نے یہاں دنیا کی زندگی میں تو ان (مجرموں) کی طرف سے جھگڑا کر لیا، پھر قیامت کے دن اللہ کے ہاں ان کی طرف سے کون جھگڑے گا؟ یا (وہاں) کون ان کا\nوکیل ہو گا؟"],[1292,"§اللہ تعالیٰ کی نازل کردہ کتاب کے مطابق فیصلے کرنے کا حکم\nاللہ تعالیٰ نے اپنے رسول سیّدنا محمد صلی اللہ علیہ وسلم کو مخاطب کرتے ہوئے فرمایا ہے : ﴿اِنَّاۤ اَنْزَلْنَاۤ اِلَيْكَ الْكِتٰبَ بِالْحَقِّ﴾ ’’اے پیغمبر صلی اللہ علیہ وسلم!) ہم نے آپ صلی اللہ علیہ وسلم پر یہ کتاب حق کے\nساتھ نازل کی ہے۔‘‘ یعنی یہ اللہ تعالیٰ کی طرف سے نازل ہونے والی سچی کتاب ہے جو حالات وواقعات کے بیان کرنےمیں بھی سچی ہے اور لوگوں سے مطالبات کرنے میں بھی سچی ہے۔ ﴿لِتَحْكُمَ بَيْنَ النَّاسِ بِمَاۤ اَرٰىكَ اللّٰهُؕ﴾ ’’تاکہ آپ صلی اللہ علیہ وسلم کو اللہ تعالیٰ نے جو ہدایت دی ہے (اس کے مطابق) لوگوں (کے مقدمات) کا فیصلہ کریں۔‘‘ صحیح بخاری و مسلم میں زینب بنت امِ سلمہ کی سیّدہ اُمّ سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے حجرے کے دروازے پر جھگڑنے والوں کی آواز کو سنا تو آپ صلی اللہ علیہ وسلم کا شانۂ نبوت سے نکل کر ان کے پاس تشریف لے آئے اور فرمایا: ’’میں بھی ایک بشر ہوں اور جس طرح سنتا ہوں اس کے مطابق فیصلہ کر دیتا ہوں، ہو سکتا ہے کہ تم میں سے ایک شخص اپنی دلیل کو دوسرے کی نسبت زیادہ اچھے طریقے سے پیش کرے اور میں اس کے حق میں فیصلہ کردوں تو جسے میں فیصلہ کرکے کسی مسلمان کا حق دے دوں تو وہ جہنم کی آگ کا ٹکڑا ہے، خواہ وہ اسے لے لے یا چھوڑ دے۔ ‘‘ امام احمد رحمہ اللہ نے سیّدہ ام سلمہ رضی اللہ عنہا کی روایت کو بیان کیا ہے کہ دو انصاری رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور وہ آپ صلی اللہ علیہ وسلم سے اپنی اس میراث کے بارے میں فیصلہ کرانا چاہتے تھے جس (کی حد بندی) کے نشانات مٹ چکے تھے لیکن دونوں کے پاس کوئی گواہی نہ تھی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ تم اپنے جھگڑے میرے پاس لے کرآتے ہو اور میں تو صرف ایک بشر ہوں، ہو سکتا ہے تم میں سے بعض لوگ بعض لوگوں کی نسبت اپنی بات (دلیل) زیادہ چر ب زبانی سے پیش کر سکیں۔ لیکن میں تو اسی کے مطابق فیصلہ کرتا ہوں جو میں سنتا ہوں، لہٰذا اگر میں نے فیصلہ کرتے ہوئےکسی کو اس کے بھائی کے حق میں کچھ دے دیا تو وہ اسے نہ لے کیوں کہ یہ تو میں اسے جہنم کی آگ کا ٹکڑا دے رہا ہوں جسے وہ قیامت کے دن اپنی گردن پر بھڑکاتا ہوا لے کر آئے گا۔ یہ ارشاد نبوی سن کر وہ دونوں انصاری رونے لگے اور دونوں میں سے ہر ایک نے کہا میرا حق بھی میرے بھائی ہی کے لیے ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سنو ! جب تم نے یہ بات کہی ہے تو جائو اور اسے آپس میں تقسیم کر لو، صرف اپنے اپنے حق کی جستجو کرو اور قرعہ ڈال لو، پھر تم میں سے ہر ایک اپنے ساتھی (کے حقوق) سے بری الذمہ ہو جائے۔ ‘‘(مسند أحمد)اس حدیث کو امام ابوداو د رحمہ اللہ نے بھی بیان کیا ہے۔(سنن أبی داؤد : 3584) اور اس میں یہ الفاظ بھی ہیں :’’جن احکام کے متعلق مجھ پر کوئی چیز نازل نہیں ہوئی،\nان میں تو میں یقیناً اپنی رائے ہی سے فیصلہ کرتا ہوں۔ ‘‘ (سنن أبی داؤ: 3585) ارشاد باری تعالیٰ:﴿يَّسْتَخْفُوْنَ مِنَ النَّاسِ وَلَا يَسْتَخْفُوْنَ مِنَ اللّٰهِ…﴾ الآیۃ ’’یہ لوگوں سے تو چھپتے ہیں اور اللہ تعالیٰ سے نہیں چھپتے …۔‘‘یہ منافقوں کی تردید ہے کہ اپنے برے اعمال کی وجہ سے لوگوں سے تو چھپتے ہیں تاکہ وہ انہیں برابھلا نہ کہیں مگر وہ اپنے ان برے اعمال کے ساتھ اللہ کے سامنے آجاتے ہیں جب کہ وہ تو ان کی مخفی باتوں سے بھی آگاہ ہے اور وہ ان کے دلوں کے بھیدوں کو بھی جانتا ہے۔ اسی لیے فرمایا: ﴿وَهُوَ مَعَهُمْ اِذْ يُبَيِّتُوْنَ مَا لَا يَرْضٰى مِنَ الْقَوْلِؕ وَكَانَ اللّٰهُ بِمَا يَعْمَلُوْنَ مُحِيْطًا۰۰۱۰۸﴾ ’’حالانکہ جب وہ رات کو ایسے مشورے کرتے ہیں جن کو وہ پسند نہیں کرتا تو وہ ان کے ساتھ ہوا کرتا ہے اور اللہ تعالیٰ ان کے (تمام) کاموں کا احاطہ کیے ہوئے ہے۔‘‘ یہ منافقوں کے لیے زبردست سرزنش اور وعید ہے۔ پھر اللہ نے فرمایا ہے :﴿هٰۤاَنْتُمْ هٰۤؤُلَآءِ جٰدَلْتُمْ عَنْهُمْ فِي الْحَيٰوةِ الدُّنْيَا١۫﴾ ’’ہاں ! تم لوگ دنیا کی زندگی میں تو ان (مجرموں) کی طرف سے بحث کرلیتے ہو۔‘‘ فرض کرو کہ یہ لوگ اگر اس کی وجہ سے دنیا میں کامیاب بھی ہو جائیں جو یہ ظاہر کرتے ہیں یا جسے ان حکام کے سامنے ظاہر کیا جاتا ہےجو ظاہری حالات کے مطابق فیصلے کرتے ہیں اور وہ اسی بات کے مکلف ہیں تو کل روزِ قیامت اللہ تعالیٰ کے سامنے کیا کریں گے جو ظاہر اور خفیہ تمام حالات کو جانتا ہے؟ اس دن ا ن کے دعوے کو سچا ثابت کرنے کے لیے کون ان کی وکالت کرے گا ؟ یعنی اس دن کوئی ان کا وکیل بننے کے لیے تیار نہ ہوگا، اسی لیے فرمایا: ﴿اَمْ مَّنْ يَّكُوْنُ عَلَيْهِمْ وَكِيْلًا۰۰۱۰۹﴾ ’’یا کون ان کا وکیل بنے گا ؟‘‘"],[1293,"§گمشدہ سامان… کی برآمدگی سے چوری ثابت نہیں ہوتی\nاس آیت اور اس سے اگلی چند آیات کا پس منظر یہ ہے کہ\nانصار کے قبیلہ بنی ظفر کے ایک آدمی بشیر بن ابیرق نے کسی دوسرے انصاری کے گھر سے آٹے کا تھیلا اور ایک زرہ چوری کی۔ اور چالاکی یہ کی کہ آٹے کا تھیلا اور زرہ راتوں رات ایک یہودی کے ہاں امانت رکھ آیا۔ تھیلا اتفاق سے کچھ پھٹا ہوا تھا جس سے آٹا تھوڑا تھوڑا گرتا گیا جس سے سراغ لگانے میں بہت آسانی ہو گئی۔ اصل مالک نے پیچھا کیا تو بشیر بن ابیرق کے گھر پہنچ گیا اور اس سے اپنی چوری کا ذکر کیا لیکن وہ صاف مکر گیا اور خانہ تلاشی بھی کرادی جہاں سے کچھ برآمد نہ ہو سکا۔ اب مالک پیچھا کرتا ہوا اس یہودی کے ہاں پہنچا اور اپنی چوری کا ذکر کیا تو یہودی کہنے لگا ایسی زرہ تو میرے پاس موجود ہے لیکن وہ تو فلاں شخص نے میرے پاس بطور امانت رکھی ہے۔ لہٰذا میں تمہیں نہیں دے سکتا۔ بالآخر مالک یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کی عدالت میں لے گیا۔ اب چور اور اس کے خاندان والوں نے آپس میں یہ طے کیا کہ اصل مجرم اس یہودی کو ہی ثابت کیا جائے اور امانت کا درمیان میں نام ہی نہ آنے دیا جائے اور اس واقعہ سے قطعی لاعلمی کا اظہار کر دیا جائے اور وہ یہ سمجھے کہ آپ صلی اللہ علیہ وسلم یہود کی بات کا اعتبار نہیں کریں گے اس طرح ہم بری ہو جائیں گے۔ چنانچہ فی الواقع ایسا ہی ہوا۔ انصاری چور اور اس کے حمایتیوں نے اس واقعہ سے قطعًا لا علمی کا اظہار کیا اور قسمیں بھی کھانے لگے جس کے نتیجہ میں آپ صلی اللہ علیہ وسلم ان خائنوں کی باتوں میں آگئے اور یہودی کو جھوٹا سمجھا اور قریب تھا کہ آپ صلی اللہ علیہ وسلم اس انصاری چورکو بری قرار دے دیں اور یہودی کو مجرم قرار دے دیں اور یہودی کے حق میں قطع ید کا فیصلہ سنا دیں کہ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو بذریعہ وحی اصل صورت حال سے مطلع فرما دیا اور تنبیہ فرمائی، کہ آپ صلی اللہ علیہ وسلم کو ایسے بددیانت لوگوں کی قطعًا حمایت نہ کرنا چاہیے۔\nاس آیت میں ایسے مسلمانوں کو خائن قرار دیا گیا ہے جنہوں نے محض خاندان اور قبیلہ کی عصبیت کی بنا پر مجرم کی حمایت کی تھی اور تمام لوگوں کو یہ بتا دیا گیا ہے کہ انصاف کے معاملہ میں کسی قسم کا تعصب برداشت نہیں کیا جائے گا۔ اگر ایک فریق دشمن قوم سے تعلق رکھتا ہے اور وہ حق پر ہے تو اسی کی حمایت کی جائے گی۔ مسلمانوں کی نہیں کی جائے گی۔ قاضی ظاہری شہادات کی بناپر فیصلہ کرنے کا پابند ہے اس لحا ظ سے اگر آپ صلی اللہ علیہ وسلم انصاری کے حق میں فیصلہ دے بھی دیتے تو آپ صلی اللہ علیہ وسلم کا کچھ قصور نہ تھا۔ تاہم آپ صلی اللہ علیہ وسلم کی عظمت شان کی وجہ سے آپ صلی اللہ علیہ وسلم کو بخشش طلب کرنے کی ہدایت کی گئی کہ ایک غلط سوچ آپ صلی اللہ علیہ وسلم کے ذہن میں راہ پانے لگی تھی۔ ان لوگوں سے مراد وہی چور انصاری کے خاندان کے لوگ ہیں جنہوں نے محض خاندانی تعصب کی بنا پر چور کی حمایت کی۔ پھر آپ صلی اللہ علیہ وسلم کے سامنے چورکے مجرم نہ ہونے کے متعلق قسمیں بھی کھائی تھیں اور سارا الزام بے گناہ یہودی کے سر تھوپ دیا تھا اور مجرم کے گناہ دو تھے، ایک چوری، دوسرے اس یہودی کو مورد الزام ٹھہرانا۔ زرہ کا چور دراصل سچا مسلمان نہیں بلکہ منافق آدمی تھا اور اس کے خاندان والے بھی کچھ پختہ ایمان والے نہ تھے۔ جب یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے ہاں چلا گیا تو ان لوگوں کے مشورے کا موضوع یہ ہوتا تھا کہ چورکس طرح چوری کے اس جرم سےبچ سکتا ہے اور یہ جرم اس یہودی کے سر کیسے تھوپاجائے۔ دراصل اس طرح راتوں کو مشورے کرنا اوریہ سمجھنا کہ اس طرح ان کے جرم پر پردہ پڑا رہے گا، یہی ان لوگوں کے ایمان کی کمزوری کی دلیل ہے اور اللہ تعالیٰ سے کوئی معاملہ بھلا کیسے چھپا رہ سکتا ہے ؟ یہ خطاب اس منافق چور کے حمایتیوں سے ہے کہ اگر آج تم چورکے حمایتی بن بھی گئے تو کل قیامت کے دن اللہ تعالیٰ کے رو برو تم میں سے کون اس کی وکالت کرے گا جب کہ تمہارے لیے تمھار ااپنا ہی یہ گناہ کافی ہوگا۔ ضمناً اس واقعہ سے یہ معلوم ہوا کہ کسی شخص کے پاس سے چوری کا مال برآمد ہوجانا اس بات کا یقینی ثبوت نہیں ہوتا کہ وہ فی الواقع چور ہے لہٰذا ایسے معاملات میں انتہائی تحقیق اور احتیاط کی ضرورت ہوتی ہے۔ اسی لیے آپ صلی اللہ علیہ وسلم نے حدود قائم کرنے کے سلسلہ میں بہت سی ہدایات فرمائی ہیں جن کا ذکر کسی دوسرے مناسب مقام پر کر دیا گیا ہے۔\nان آیات (104 سے 113 تک) کی شان نزول میں بتایا گیا ہے کہ انصار کے قبیلہ بنی ظفر میں ایک شخص طعمہ یا بشیر بن ابیرق نے ایک انصاری کی زرہ چرالی، جب اس کا چرچاہوا اور اس کو اپنی چوری کے بے نقاب ہونے کا خطرہ محسوس ہوا تو اس نے وہ ذرہ ایک یہودی کے گھر پھینک دی اور بنی ظفر کے کچھ آدمیوں کو ساتھ لے کر نبی صلی اللہ علیہ وسلم کی خدمت میں پہنچ گیا، ان سب نے کہا کہ زرہ چوری کرنے والا فلاں یہودی ہے۔ یہودی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس نے کہا کہ بنی ابیرق نے زرہ چوری کرکے میرے گھر پھینک دی ہے۔ بنی ظفر اور بنی ابیرق (طعمہ یا بشیر وغیرہ) ہوشیار تھے اور نبی صلی اللہ علیہ وسلم کو باور کراتے رہے کہ چور یہودی ہے اور وہ طعمہ پر الزام لگانے میں جھوٹا ہے۔ نبی صلی اللہ علیہ وسلم بھی ان کی چکنی چپڑی باتوں سے متاثر ہو گئے اور قریب تھا کہ اس انصاری کو چوری کے الزام سے بری کرکے یہودی پر چوری کی فرد جرم عائد فرما دیتے کہ اللہ تعالیٰ نے یہ آیت نازل فرما دی۔ جس سے ایک بات یہ معلوم ہوئی کہ نبی صلی اللہ علیہ وسلم بھی بہ حیثیت ایک انسان کے غلط فہمی میں پڑ سکتے ہیں۔ دوسری بات یہ معلوم ہوئی کہ آپ صلی اللہ علیہ وسلم عالم الغیب نہیں تھے، ورنہ آپ صلی اللہ علیہ وسلم پر فورًا صورتحال واضح ہو جاتی۔ تیسری بات یہ معلوم ہوئی کہ اللہ تعالیٰ اپنے پیغمبر صلی اللہ علیہ وسلم کی حفاظت فرماتا ہے اور اگر کبھی حق کےپوشیدہ رہ جانے اور اس سے ادھر ادھر ہوجانے کامرحلہ آجائے تو فورًا اللہ تعالیٰ اسے متنبہ فرما دیتااور اس کی اصلاح فرما دیتا ہے جیسا کہ عصمت انبیاء علیہم السلام کا تقاضا ہے۔ یہ وہ مقام عصمت ہے جو انبیاء علیہم السلام کے علاوہ کسی اور کو حاصل نہیں۔\n﴿وَمَنْ يَّعْمَلْ سُوْٓءًا اَوْ يَظْلِمْ نَفْسَهٗ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوْرًا رَّحِيْمًا۰۰۱۱۰ وَمَنْ يَّكْسِبْ اِثْمًا فَاِنَّمَا يَكْسِبُهٗ عَلٰى نَفْسِهٖؕ وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًا۰۰۱۱۱ وَمَنْ يَّكْسِبْ خَطِيْٓئَةً اَوْ اِثْمًا ثُمَّ يَرْمِ بِهٖ بَرِيْٓـًٔا فَقَدِ احْتَمَلَ بُهْتَانًا وَّاِثْمًا مُّبِيْنًاࣖ۰۰۱۱۲ وَلَوْ لَا فَضْلُ اللّٰهِ عَلَيْكَ وَرَحْمَتُهٗ لَهَمَّتْ طَّآىِٕفَةٌ مِّنْهُمْ اَنْ يُّضِلُّوْكَؕ وَمَا يُضِلُّوْنَ اِلَّاۤ اَنْفُسَهُمْ وَمَا يَضُرُّوْنَكَ مِنْ شَيْءٍؕ وَاَنْزَلَ اللّٰهُ عَلَيْكَ الْكِتٰبَ وَالْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُؕ وَكَانَ فَضْلُ اللّٰهِ عَلَيْكَ عَظِيْمًا۰۰۱۱۳﴾\nاور جو شخص برا عمل کرے یا اپنی جان پر ظلم کرے، پھر وہ اللہ سے بخشش مانگے تو وہ اللہ کو بہت بخشنے والا، نہایت رحم کرنے والا پائے گا اور جو شخص کوئی گناہ کرتا ہے تو بے شک اس کی یہ کمائی اسی کے لیے وبال ہو گی، اور اللہ خوب جاننے والا، بہت حکمت والا ہے اور جو شخص کوئی خطا یا گناہ کرتا ہے، پھر کسی بے گناہ پر اس کا الزام لگا دیتا ہے تو (ایسا کر کے) وہ ایک بڑے بہتان اور کھلے گناہ کا بوجھ اٹھاتا ہے\nاور اگر آپ پر اللہ کا فضل اور اس کی رحمت نہ ہوتی تو لوگوں کے ایک گروہ نے یقینا ارادہ کر لیا تھا کہ وہ آپ کو بہکا دے، اور وہ اپنے آپ کے سوا کسی کو نہیں بہکاتے، اور وہ آپ کو ذرا بھی نقصان نہیں پہنچا سکتے، اور اللہ نے آپ پر یہ کتاب اور حکمت نازل کی ہے اور آپ کو وہ کچھ سکھایا ہے جو آپ نہیں جانتے تھے۔ اور آپ پر اللہ کا فضل بہت زیادہ ہے"],[1294,"§توبہ و استغفار کی ترغیب\nاللہ تعالیٰ اپنے جود و کرم کا تذکرہ کرتے ہوئے فرما رہا ہے کہ جو شخص توبہ کرے، خواہ اس نے کوئی بھی گناہ کیا ہو تو وہ اس کی توبہ کو قبول فرما لیتا ہے۔ ارشاد باری تعالیٰ ہے : ﴿وَمَنْ يَّعْمَلْ سُوْٓءًا اَوْ يَظْلِمْ نَفْسَهٗ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوْرًا رَّحِيْمًا۰۰۱۱۰﴾ ’’اور جو شخص کوئی برا کام کر بیٹھے یا اپنے حق میں ظلم کر لے، پھر اللہ تعالیٰ سے بخشش مانگے تو اللہ تعالیٰ کو بخشنے والا (اور) مہربان پائے گا۔ ‘‘علی بن ابو طلحہ رحمہ اللہ نے روایت کیا ہے کہ سیّدنا ابن عباس رضی اللہ عنہما نے اس آیت کے بارے میں بھی فرمایا: کہ اس میں اللہ تعالیٰ نے اپنے بندوں کو اپنے عفو، حلم و کرم، وسعت ِ رحمت اور مغفرت کے بارے میں بتایا ہے کہ جو شخص کوئی بھی چھوٹا یا بڑا گناہ کر بیٹھے ﴿ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوْرًا رَّحِيْمًا۰۰۱۱۰﴾ ’’پھر اللہ تعالیٰ سے بخشش مانگے تو اللہ تعالیٰ کو بخشنے والا (اور) مہربان پائے گا۔ ‘‘ خواہ اس کے گناہ آسمانوں، زمین اور پہاڑوں سے بھی بڑے کیو ں نہ ہوں۔\n(تفسیر الطبری : 371/5)\nامام احمد رحمہ اللہ نے سیّدنا علی رضی اللہ عنہ کی روایت کو بیان کیا ہے کہ میں جب بھی رسول اللہ صلی اللہ علیہ وسلم کے کسی فرمان کو سنتا تو اللہ تعالیٰ جس قدر چاہتا مجھے اس سے نفع پہنچا دیتا۔مجھ سے یہ ابو بکر رضی اللہ عنہ نے بیان کیا- اور ابو بکر رضی اللہ عنہ نے سچ بیان کیا - کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو مسلمان کوئی بھی گناہ کر بیٹھے، پھر وضو کرکے دو رکعت نماز پڑھ لے اور اللہ تعالیٰ سے اس گناہ کی معافی مانگے تو اللہ تعالیٰ اسے معاف فرما دیتا ہے۔ ‘‘\nپھر آپ صلی اللہ علیہ وسلم نے یہ دو آیتیں پڑھیں :﴿وَمَنْ يَّعْمَلْ سُوْٓءًا اَوْ يَظْلِمْ نَفْسَهٗ ثُمَّ يَسْتَغْفِرِ اللّٰهَ يَجِدِ اللّٰهَ غَفُوْرًا رَّحِيْمًا۰۰۱۱۰﴾ ’’اور جو شخص کوئی برا کام کر بیٹھے یا اپنے حق میں ظلم کر لے، پھر اللہ تعالیٰ سے بخشش طلب کرے تو اللہ تعالیٰ کو غفور و رحیم پائے گا۔ ‘‘اور ﴿وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْۤا اَنْفُسَهُمْ …﴾ الآیۃ. (آل عمران:135) ’’اور وہ جب کوئی کھلا گناہ یا اپنے حق میں کوئی اور برائی کر بیٹھتے ہیں …۔‘‘ (مسند أحمد)\n﴿وَمَنْ يَّكْسِبْ اِثْمًا فَاِنَّمَا يَكْسِبُهٗ عَلٰى نَفْسِهٖؕ﴾ ’’اور جو کوئی گناہ کرتا ہے تو اس کا وبال اسی پر ہے۔ ‘‘ جیسا کہ اس نے فرمایا ہے :﴿وَلَا تَزِرُ وَازِرَةٌ وِّزْرَ اُخْرٰىۚ﴾ (الأنعام:164) ’’اور کوئی اُٹھانے والا دوسرے کا بوجھ نہیں اُٹھائے گا۔‘‘ یعنی کوئی کسی کے کام نہیں آئے گا۔ ہر شخص کو اپنے اعمال کا خود حساب دینا ہوگا، کوئی کسی کے اعمال کا بوجھ نہیںاُٹھائے گا، اسی لیےتو اس نے فرمایا ہے :﴿وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًا۰۰۱۱۱﴾ ’’اور اللہ تعالیٰ جاننے والا (اور) حکمت والا ہے۔ ‘‘ اوریہ اس کے علم و حکمت اور عدل و رحمت ہی کا تقاضا ہے کہ ہر شخص کے گناہ کا وبال اسی پر ہو اور اس کے سوا کسی اور پر نہ ہو۔ ﴿وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُؕ﴾ ’’اور آپ صلی اللہ علیہ وسلم کو وہ باتیں سکھائی ہیں جو آپ صلی اللہ علیہ وسلم نہیں جانتے تھے۔ ‘‘ یعنی ان کے نازل ہونے سے پہلے جانتے نہیں تھے جیسا کہ فرمایا:﴿وَكَذٰلِكَ اَوْحَيْنَاۤ اِلَيْكَ رُوْحًا مِّنْ اَمْرِنَاؕ مَا كُنْتَ تَدْرِيْ مَا الْكِتٰبُ﴾ (الشورٰی:52) ’’اور اسی طرح ہم نے اپنے حکم سے آپ صلی اللہ علیہ وسلم کی طرف (وحی) بھیجی ہے، آپ صلی اللہ علیہ وسلم کتاب کو نہ جانتے تھے۔‘‘ یہ آخر سورت تک۔ اور فرمایا: ﴿وَمَا كُنْتَ تَرْجُوْۤا اَنْ يُّلْقٰۤى اِلَيْكَ الْكِتٰبُ اِلَّا رَحْمَةً مِّنْ رَّبِّكَ﴾ (القصص:86) ’’اور آپ صلی اللہ علیہ وسلم کو اُمید نہ تھی کہ آپ صلی اللہ علیہ وسلم پر یہ کتاب نازل کی جائے گی مگر آپ صلی اللہ علیہ وسلم کے رب کی مہربانی سے (نازل ہوئی۔)‘‘ اسی لیے تو اللہ تعالیٰ نے یہاں فرمایا ہے :﴿وَكَانَ فَضْلُ اللّٰهِ عَلَيْكَ عَظِيْمًا۰۰۱۱۳﴾ ’’اور آپ صلی اللہ علیہ وسلم پر اللہ تعالیٰ کا بڑا فضل ہے۔ ‘‘"],[1295,"§اپنے گناہ دوسروں کے ذمہ لگانا اور بہتان تراشی\nاصل چورکی حمایت کی دو صورتیں تھیں: ایک یہ کہ چورنے جھوٹ بول کر اپنے حمایتیوں کو مطمئن کر دیا ہو کہ میں فی الواقع مجرم نہیں ہوں یعنی ان کا یہ گناہ نادانستہ یا غلطی کی بنا پر ہو۔ اور دوسری صورت یہ تھی کہ حمایتیوں کو ٹھیک طرح معلوم ہو چکا ہو کہ جس کی حمایت کر رہے ہیں وہ فی الواقع مجرم ہے اور اس کا یہ گناہ دیدہ دانستہ ہو۔ پہلی صورت کو اللہ تعالیٰ نے سُوْٓءًا سے تعبیر فرمایااور دوسری صورت کو اپنے آ پ پر ظلم سے۔ ان دونوں صورتوں میں اگریہ حمایتی لوگ مجرم کی حمایت سے دستبردار ہوجاتے اور اللہ تعالیٰ سے بخشش مانگتے تو یقیناً اللہ تعالیٰ ان کا گناہ معاف کر دیتا۔ واضح رہے کہ ان آیات میں اگرچہ خطاب مذکورہ بالا لوگوں سے ہے تاہم ایسی سب آیتوں کا حکم عام ہوتا ہے۔ غلطی سے یا نادانستہ کوئی گناہ کسی بے قصور کے سرتھوپ دینے کی ایک مثال حدیث میں مذکور ہے جو درج ذیل ہے :"],[1296,"§بہتان تراشی، کالی عورت اور کمر بند\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ کسی عرب قبیلے کے پاس ایک کالی لونڈی تھی۔ جسے انہوں نے آزاد کر دیا تھا مگر وہ ان کے ساتھ ہی رہا کرتی۔ ایک دفعہ اسی قبیلے کی ایک لڑکی جو دلہن تھی، نہانے کونکلی او راپنا لال تسموں والا کمر بند اتار کر رکھ دیا۔ ایک چیل نے اسے جوپڑا دیکھا تو گوشت سمجھ کر جھپٹ لے گئی۔ لوگوں نے کمر بند تلاش کیا مگر وہ نہ ملا۔ آخر انہوں نے اس کالی لونڈی پر تہمت لگادی۔ وہ کہنے لگی کہ ’’ان لوگوں نے میری تلاشی لینا شروع کی حتی کہ میری شرمگاہ بھی دیکھی۔ اللہ کی قسم ! میں ان کے پاس ہی کھڑی تھی کہ وہی چیل گزری جس نے کمر بند پھینک دیا اور وہ ان کے درمیان گرا۔ میں نے کہایہ ہے وہ کمر بند جس کی تم مجھ پر تہمت لگا رہے تھے۔ حالانکہ میں اس سے بری تھی۔ اب سنبھالواسے۔‘‘ پھر وہ لڑکی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور اسلام لے آئی۔ اس کا خیمہ مسجد میں تھا۔ کبھی کبھی وہ میرے پاس آکر باتیں کیا کرتی اورجب بھی وہ میرے آتی، وہ یہ شعر ضرور پڑھتی تھی:\nویوم الوشاح من تعاجیب ربنا\nالا انہ من بلدۃ الکفر انجانی\n’’کمر بند کا دن ہمارے رب کے عجائبات میں سے ہے۔ اسی واقعہ نے تو مجھے کفر کی سرزمین سے نجات بخشی تھی۔‘‘\n(صحیح البخاری)\nکیوں کہ اس نے دو جرم کیے ہیں۔ ایک وہ جو خود گناہ کا کام کیا اور دوسرا گناہ اس سے بڑا ہے کہ اس گناہ کو کسی بے قصور کے سر تھوپ کر اسے مجرم بنا دینے کی کوشش کی جائے۔"],[1297,"§آپ پر اللہ تعالیٰ نے بہت بڑا فضل کیا تھا\nاللہ تعالیٰ کا فضل اور اس کی رحمت یہ تھی کہ اس نے رسول اللہ صلی اللہ علیہ وسلم کو اصل صورت حال سے بذریعہ وحی مطلع فرما دیا۔ ورنہ اس کے نتائج صرف یہی نہ تھے کہ مجرم بچ جاتا اور ایک بے قصور مجرم قرار پاتا بلکہ اس کے نتائج بڑے دور رس تھے جو عوام الناس کی نظروں میں مسلمانوں کی ساکھ اور ان کے کردار کومجروح بنا سکتے تھے، ایسے لوگ جو آپ صلی اللہ علیہ وسلم کو بہکا کر اپنے حق میں فیصلہ کرانا چاہتے تھے اپنی ہی عاقبت خراب کر رہے تھے۔ اس سے آپ صلی اللہ علیہ وسلم کو کوئی نقصان نہیں پہنچ سکتا تھا۔ اور اللہ تعالیٰ کے ہاں مجرم وہ تھے نہ کہ آپ صلی اللہ علیہ وسلم۔"],[1298,"§مقدمہ میں چالاکی سے دوسرے کا مال ہتھیانا\nجو شخص کسی حاکم کو دھوکہ دے کر اپنے حق میں فیصلہ کرالیتا ہے۔ وہ دراصل خود اپنے آپ کو اس غلط فہمی میں مبتلا کرتا ہے کہ ان تدبیروں سے وہ فی الواقع اس چیز کا حقدار بن گیا۔ حالانکہ اللہ تعالیٰ کے نزدیک حق جس کا ہوتا ہے اسی کا رہتا ہے اور فریب خوردہ حاکم کے فیصلہ سے حقیقت پرکوئی اثر نہیں پڑتا۔ چنانچہ آپ صلی اللہ علیہ وسلم نے فرمایا: کہ ’’ میں بھی تمہاری طرح ایک انسان ہی ہوں۔ تم لوگ میرے پاس جھگڑے لے کر آتے ہو اور ممکن ہے کہ تم میں سے کوئی زیادہ چرب زبان ہو اور میں اس کے دلائل سن کر اس کے حق میں فیصلہ دے دوں تو اس طرح اگر میں اس کے بھائی کے حق سے کوئی چیز اس چرب زبان کے حق میں فیصلہ کرکے دے دوں تو یاد رکھو کہ میں اسے آگ کا ٹکڑاکاٹ کر دے رہا ہوں۔‘‘(صحیح البخاری) ربط مضمون کے لحاظ سے اس جملہ کا وہی مطلب ہے جو اوپر مذکور ہوا تاہم اس کا حکم عام ہے اور اس کا مطلب ایسے فضائل ہیں جو دوسرے کسی پیغمبر علیہ السلام کو بھی نہیں ملے اور وہ فضائل آپ صلی اللہ علیہ وسلم نے خود ان الفاظ میں بتائے ہیں : جابر رضی اللہ عنہ بن عبداللہ (انصاری) کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔ مجھے پانچ چیزیں ایسی ملی ہیں جو مجھ سے پہلے کسی پیغمبر علیہ السلام کو نہیں ملیں: ایک یہ کہ ایک ماہ کی مسافت پر دشمن پر میرا رعب طاری رہتا ہے دوسرا یہ کہ ساری زمین میرے لیے مسجد اور پاک بنائی گئی ہے۔ لہٰذا میری اُمت کا ہر شخص جہاں نماز کا وقت آئے نما زپڑھ لے، تیسرے یہ کہ اموال غنائم میرے لیے حلال ہوئے جو مجھ سے پہلے کسی کے لیے جائز نہیں تھے۔ چوتھے یہ کہ شفاعت کبرٰی (قیامت کے دن)ملی اور پانچویں یہ کہ پہلے ہرنبی علیہ السلام کسی خاص قوم کی طرف بھیجا جاتا تھا جب کہ میں تمام لوگوں کے لیے بھیجا گیا ہوں۔ (صحیح البخاری)اور سیدنا ابوہریرہ رضی اللہ عنہ کی حدیث میں مندرجہ ذیل چھ باتیں مذکور ہیں :\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کہ مجھے چھ باتوں میں دوسرے پیغمبروں علیہم السلام پر فضیلت دی گئی ہے مجھے جوامع الکلم عطا کیے گئے ہیں۔ یعنی ایسا کلام جس میں الفاظ کم اور معانی بہت ہوں اور دوسرے دشمن پر رُعب سے میری مدد کی گئی تیسرے مجھ پر غنیمتیں حلال کی گئیں۔ چوتھے میرے لیے ساری زمین پاک کرنے والی اور نماز کی جگہ بنائی گئی۔ پانچویں میں تمام لوگوں (جنوں اور انسانوں) کی طرف بھیجا گیا ہوں اور چھٹے مجھ پر نبوت ختم کی گئی۔ (صحیح مسلم)\nاس مضمون کی ایک دو سری آیت میں اللہ تعالیٰ فرماتا ہے ﴿وَلَا تَزِرُ وَازِرَةٌ وِّزْرَ اُخْرٰىۚ﴾ (بنی اسرائیل:15) ’’کوئی بوجھ اُٹھانے والا کسی دوسرے کا بوجھ نہیں اُٹھائے گا‘‘ یعنی کوئی کسی کا ذمہ دار نہیںہوگا، ہر نفس کو وہی کچھ ملے گا جو وہ کماکر ساتھ لے گیا ہوگا۔ یہ دوسرے فضل و احسان کا تذکرہ ہے جو آپ صلی اللہ علیہ وسلم پر کتاب و حکمت (سنت) نازل فرما کر اور ضروری باتوں کا علم دے کر فرمایا گیا۔ جس طرح دوسرے مقام پر فرمایا:﴿وَكَذٰلِكَ اَوْحَيْنَاۤ اِلَيْكَ رُوْحًا مِّنْ اَمْرِنَاؕ مَا كُنْتَ تَدْرِيْ مَا الْكِتٰبُ وَلَا الْاِيْمَانُ …﴾ (الشوری:52) ’’اسی طرح بھیجا ہم نے تیری طرف (قرآن لے کر) ایک فرشتہ اپنے حکم سے تو نہیں جانتا تھا کہ کتاب کیا ہے اور ایمان کیا ہے ؟ ‘‘ ﴿وَمَا كُنْتَ تَرْجُوْۤا اَنْ يُّلْقٰۤى اِلَيْكَ الْكِتٰبُ اِلَّا رَحْمَةً مِّنْ رَّبِّكَ﴾ (القصص:86) ’’تجھے یہ توقع نہیں تھی کہ تجھ پر کتاب اُتاری جائے گی، مگر تیرے رب کی رحمت سے (یہ کتاب اُتاری گئی)‘‘ ان تمام آیات سے معلوم ہو اکہ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم پر فضل و احسان فرمایا اور کتاب و حکمت بھی عطا فرمائی، ان کے علاوہ دیگر بہت سی باتوں کا آپ صلی اللہ علیہ وسلم کو علم د یا گیا جن سے آپ صلی اللہ علیہ وسلم بے خبر تھے۔ یہ بھی گویا آپ صلی اللہ علیہ وسلم کے عالم الغیب ہونے کی نفی ہے کیونکہ جو خود عالم الغیب ہو، اسے تو کسی اور سے علم حاصل کرنے کی ضرورت ہی نہیں ہوتی اور جسے دوسرے سے معلومات حاصل ہوں،وحی کے ذریعے سے یا کسی اور طریقے سے وہ عالم الغیب نہیں ہوتا۔\nشانِ نزول : جامع ترمذی میں قتادہ بن نعمان رضی اللہ عنہ بیان کرتے ہیں ہم میں سے ایک خاندان کو (بنو ابیرق) کے نام سے پکارا جاتا تھا جن کے افراد بشر، بشیر اور مبشر تھے۔ بشیر نامی انسان منافق تھا وہ اشعار میں نبی صلی اللہ علیہ وسلم کے صحابہ کرام رضی اللہ عنہم کی مذمت کرتا رہتا تھا بعد ازاں ان اشعار کی نسبت کسی عربی شخص کی جانب کر دیتا کہ ان اشعار کا قائل فلاں شخص ہے جب ان اشعار کو صحابہ کرام رضی اللہ عنہم نے سنا تو انہوں نے برملا کہا اللہ کی قسم ! ان اشعار کا کہنے والا یہی خبیث شخص ہے جس کا نام (ابن ابیرق) ہے۔ خیال رہے یہ خاندان معاشرہ میں پست ہمت او ر محتاج تھا فقر و فاقہ نے اسے گھیر رکھتا تھا ان دنوں مدینہ میں عام طور پر لوگوں کی خوراک کھجور اور جو تھے جب کہ کھاتا پیتا شخص تو شام کے تجارتی قافلہ سے میدہ خریدتا جس کو اپنے لیے مخصوص کر لیتا لیکن اس کے اہل و عیال کا گزر بسر بھی کھجور اور جو پر تھا۔\nقتادہ بن نعمان رضی اللہ عنہ بیان کرتے ہیں کہ شام سے تجارتی قافلہ آیاتو میرے چچا رفاعہ بن زید نے ان سے میدے کا ایک تھیلا خریدا اسے اپنے بالا خانہ میں رکھا جب کہ بالا خانہ میں اس تھیلے کے علاوہ لڑائی کے ہتھیار زرہ اور تلوار بھی تھی۔ چنانچہ گھر کی نچلی چھت میں سوراخ کرکے میدے کا تھیلا اور ہتھیار چوری کر لیے گئے جب دن ہوا تو میرا چچا میرے پاس آیا اس نے مجھے مخاطب کرتے ہوئے کہااے میرے بھتیجے ! گذشتہ رات ہمارے گھر میں چوری ہو گئی ہے میدے کا تھیلا اور ہتھیار اُٹھا لیے گئے ہیں۔ راوی نے بیان کیا کہ ہم نے اس واقعہ کی تفتیش شروع کر دی ہمیں بتایا گیا بعض لوگوں نے خبر دی کہ ہم نے گذشتہ رات بنو ابیرق کے گھر میں محسوس کیا کہ انہوں نے آگ جلا رکھی ہے ہمار ا خیال ہے کہ تمہارے ہاں سے جو میدہ چوری کیا گیا ہے۔ اسے ہی پکایا جا رہا ہوگا بنو ابیرق نے کہا ہم گھروں میں تفتیش کرتے ہیں اور ساتھ ہی کہا اللہ تعالیٰ کی قسم ! ہمارا خیال ہے کہ تمہارے تھیلے کا چور لبید بن سہل ہے جب کہ لبید شخص صحیح مسلمان تھا جب لبید نے ان کے الزام کو سنا تو اس نے میان سے تلوار نکال لی اور کہا آپ مجھے چور کہتے ہیں اللہ کی قسم ! تم پر اس تلوار سے حملہ کردوں گا اگر تم چوری کے بارے میں وضاحت نہ کرو گے انہوں نے دبی زبان سے کہا آپ چور نہیں ہیں آپ دور ہو جائیں۔ پھر ہم نے تفتیش کی ہمیں کچھ شک نہ رہا کہ چور تو بنو ابیرق ہی ہیں تو میرے چچا نے مجھ سے کہا آپ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں جائیں آپ صلی اللہ علیہ وسلم سے اس کا تذکرہ کریں۔ قتادہ رضی اللہ عنہ بیا ن کرتے ہیں میں آپ صلی اللہ علیہ وسلم کے ہاں پہنچا میں نے عرض کیا ہم میں ایک خاندان کچھ غلط مزاج کا ہے اس نے میرے چچا کے گھر نقب لگا کر اسلحہ اور غلہ چوری کرلیا ہے وہ اسلحہ ہمیں واپس کرائیں غلہ کی واپسی کا ہم مطالبہ نہیں کرتے آپ صلی اللہ علیہ وسلم نے فرمایا میں اس کے بارے میں جلد ہی مشورہ کرتا ہوں جب بنو ابیرق نے اس واقعہ کو سنا تو وہ اپنے خاندان کے ایک شخص کے پاس پہنچا جس کا نام ایسر بن عروہ تھا اس واقعہ کے بارے میں اس سے گفتگو ہوئی اس دوران کچھ اور لوگ بھی آگئے انہوں نے آپ صلی اللہ علیہ وسلم کی خدمت میں بیان دیا۔ اے اللہ کے رسول صلی اللہ علیہ وسلم! قتادہ بن نعمان رضی اللہ عنہ اور اس کے چچا نے ہمارے خاندان پر بلا دلیل چوری کا الزام لگایا ہے جب کہ جن پر الزام لگایا گیا ہے ان کا اسلام درست ہے۔ قتادہ رضی اللہ عنہ بیان کرتے ہیں میں اس سلسلہ میں آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور واقعہ سنایا آپ صلی اللہ علیہ وسلم نے فرمایا تم نے ایسے خاندان پر الزام لگایا ہے جن کے اسلام میں کچھ شبہ نہیں اور وہ اچھی صلاحیتوں والے ہیں تمہارے پاس کوئی دلیل بھی نہیں ہے۔ قتادہ رضی اللہ عنہ بیان کرتا ہے آپ صلی اللہ علیہ وسلم کی گفتگو سن کر میں حیرانی کے عالم میں واپس لوٹا اور میری آرزو تھی کاش میں آپ صلی اللہ علیہ وسلم کے پاس نہ جاتا اس کے بجائے اگرچہ میرا کچھ مال ضائع ہو جاتا وہ مجھے برداشت تھا اس دوران میرا چچا رفاعہ میرے پاس آیا اس نے دریافت کیا آپ صلی اللہ علیہ وسلم نے کیا کہا ہے ؟ میں نے اس کو سب کچھ بتا دیا اس نے جواب میں صرف یہ کلمہ کہا اللہ تعالیٰ ہی سے استعانت کی جائے اس کے بعد زیادہ عرصہ نہیں گزرا ہوگا کہ یہ آیات نازل ہوئیں۔ (صحیح ترمذی)\nاللہ تعالیٰ رسول اکرم صلی اللہ علیہ وسلم کو مخاطب کرتے ہوئے بتا رہے ہیں کہ ہم نے قرآن پاک کو آپ صلی اللہ علیہ وسلم کی جانب نازل کیا ہے اس میں واقعات اور احکام کے صحیح ہونے میں ہرگز شک و شبہ نہیں ہے آپ صلی اللہ علیہ وسلم لوگوں کے تنازعات میں اجتہاد کے ساتھ فیصلے کریں۔ چنانچہ بخاری، مسلم میں اُم سلمہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم نے اپنے حجرہ کے دروازے پر شور و شغب اور جھگڑے کو محسوس کیا آپ صلی اللہ علیہ وسلم ان کی جانب گئے اور واضح کیا کہ میں تو انسان ہوں اور جیسے میں واقعہ سنتا ہوں اس کے مطابق فیصلہ کرتا ہوں عین ممکن ہے کہ تم میں کوئی شخص اپنا موقف بیان کرنے میں زیادہ تیز ہو تو میں اس سے متاثر ہو کر اس کے حق میں فیصلہ کر دیتا ہوں۔ یاد رکھیں میں جس شخص کو اس کے بھائی مسلمان کا حق چھین کر دیتا ہوں تو اسے آگ کا ٹکڑاکاٹ کر دیتا ہوں قیامت کے روز وہ اس کی گردن میں لٹک رہا ہوگا آپ صلی اللہ علیہ وسلم کی گفتگو سے متاثر ہو کر دونوں شخص رونے لگ گئے ان میں سے ہر شخص نے بر ملا اس بات کا اظہار کیا کہ میں نے اپنا حق اپنے بھائی کے سپرد کر دیا۔ ا س کی بات سن کر آپ صلی اللہ علیہ وسلم نے فرمایا تمہاری گفتگوکاجائزہ لینے کے بعد میں تمہیں حکم دیتا ہوں کہ تم جائو اور قرعہ اندازی کرو پھر بھی تم میں سے ہر شخص اپنے بھائی سے کہے کہ میں اپنا حق آپ کے حوالہ کرتا ہوں۔ (ابن کثیر : 836,835/1)\nبعد ازاں اللہ تعالیٰ نے ان لوگوں کے بارے میں بتایا جو آپ صلی اللہ علیہ وسلم کے پاس آئے جھوٹ کے ساتھ خود کو چھپانے کی کوشش کر رہے تھے خیانت کرنے والوں کی جانب سے جھگڑا کر رہے تھے۔\n﴿وَمَنْ يَّكْسِبْ خَطِيْٓئَةً اَوْ اِثْمًا ثُمَّ يَرْمِ بِهٖ بَرِيْٓـًٔا فَقَدِ احْتَمَلَ بُهْتَانًا وَّاِثْمًا مُّبِيْنًاࣖ۰۰۱۱۲﴾ مقصود اس سے وہ شخص ہے جو چوری کا مرتکب ہو ا او روہ لوگ جو چورکی حمایت میں جھگڑا کر رہے تھے۔ شانِ نزول میں ان کا مکمل واقعہ بیان ہو چکا ہے کہ چوری کے ارتکاب کے ساتھ ساتھ خود چوری کے جرم سے انکار کرتےہیں اور ایک ایسے شخص کو مجرم بناتے ہیں جو درحقیقت مجرم نہیں تو گویا کہ چوری کے جرم کے ساتھ ساتھ الزام تراشی کے بھی مرتکب ہوئے اور یہ ایسا گناہ ہے جس کو معاشرہ میںنہایت گھنائونا جرم متصور کیاجاتا ہے لیکن اُمت محمدیہ پر اللہ پاک کا خاص احسان ہے کہ استغفار سے ان کے گناہ دھل جاتے ہیں جیساکہ گناہ ہوا ہی نہیں۔ بنو اسرائیل کو حکم تھا کہ جب ان کے کپڑے پر پیشاب کے چھینٹے پڑجاتے تھے تو وہ کپڑا دھونے سے پاک نہیں ہوتا تھا اُمت محمدیہ پر اللہ پاک کا خاص احسان ہے کہ کپڑا دھونے سے پاک ہوجاتا ہے بلکہ صحیح حدیث میں وارد ہے کہ وضو کرنے سے اس کے جسم کے گناہ معاف ہو جاتے ہیں۔\n﴿وَلَوْ لَا فَضْلُ اللّٰهِ عَلَيْكَ وَرَحْمَتُهٗ﴾ اگر اللہ پاک کا آپ صلی اللہ علیہ وسلم پر فضل نہ ہوتا اور اللہ تعالیٰ کی رحمت آپ صلی اللہ علیہ وسلم کے شامل حال نہ ہوتی تو ایک گروہ کا ارادہ تھا کہ آپ صلی اللہ علیہ وسلم کو صراط مستقیم سے دور ہٹا دیا جائے لیکن وہ ہر گز آپ صلی اللہ علیہ وسلم کو جا دۂ مستقیم سے منحرف نہیں کر سکتے وہ خود کو گمراہی کے گڑھے میں گرا رہے ہیں آپ صلی اللہ علیہ وسلم کو ہرگز ایذا نہیں پہنچا سکتے۔ اللہ پاک نے بنو ابیرق کے واقعہ کا تصفیہ فرما دیا ہے اور حقیقت کو واضح کر دیا ہے کوئی خفاباقی نہیں رہا۔\n﴿وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُؕ﴾ رسول اکرم صلی اللہ علیہ وسلم کے معلم اللہ تعالیٰ ہیں اللہ پاک نے ان واقعات سے آگاہ فرمایا جن کا آپ صلی اللہ علیہ وسلم کو علم نہ تھا ظاہر ہے کہ اللہ تعالیٰ کی ذات پر تو کوئی چیز مخفی نہیں وہ عالم الغیب ہے لیکن کوئی پیغمبر علیہ السلام بلکہ آپ صلی اللہ علیہ وسلم کو بھی علم غیب نہ تھا۔ اس کا تذکرہ نہایت عمدہ انداز میں متعدد آیات قرآنیہ میں موجود ہے۔ ایک مقام پر فرمایا:”ہم نے آپ صلی اللہ علیہ وسلم کی جانب جبریل علیہ السلام کو اپنے حکم کے ساتھ نازل فرمایا آپ صلی اللہ علیہ وسلم کو کتاب اور ایمان کے بارے میں کچھ علم نہ تھا بلکہ آپ صلی اللہ علیہ وسلم کو اُمید نہ تھی کہ آپ صلی اللہ علیہ وسلم کو کتاب کے عطیہ سے نوازا جائے گا۔ “اللہ پاک کاآپ صلی اللہ علیہ وسلم پر بہت بڑا فضل اور احسان ہے۔ (ابن کثیر : 841/1)\n﴿لَا خَيْرَ فِيْ كَثِيْرٍ مِّنْ نَّجْوٰىهُمْ اِلَّا مَنْ اَمَرَ بِصَدَقَةٍ اَوْ مَعْرُوْفٍ اَوْ اِصْلَاحٍۭ بَيْنَ النَّاسِؕ وَمَنْ يَّفْعَلْ ذٰلِكَ ابْتِغَآءَ مَرْضَاتِ اللّٰهِ فَسَوْفَ نُؤْتِيْهِ اَجْرًا عَظِيْمًا۰۰۱۱۴ وَمَنْ يُّشَاقِقِ الرَّسُوْلَ مِنْۢ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدٰى وَيَتَّبِعْ غَيْرَ سَبِيْلِ الْمُؤْمِنِيْنَ نُوَلِّهٖ مَا تَوَلّٰى وَنُصْلِهٖ جَهَنَّمَؕ وَسَآءَتْ مَصِيْرًاࣖ۰۰۱۱۵﴾\nان کی اکثر خفیہ سر گوشیوں میں کوئی بھلائی نہیں ہوتی مگر جو شخص صدقے یا نیکی یا لوگوں کے درمیان صلح کا حکم دے (تو یہ اچھی بات ہے) اور جو کوئی اللہ کی رضا حاصل کرنے کے لیے ایسا کرے، تو ہم اسے جلد بہت بڑا اجر عطا کریں گے اور جس شخص کے سامنے واضح شکل میں ہدایت آ جائے اور اس کے بعد وہ رسول کی مخالفت کرے، اور مسلمانوں کا راستہ چھوڑ کر دوسرے راستے کی پیروی کرے، تو ہم اسے اسی طرف پھیر دیں گے جس طرف وہ جانا چاہے اور ہم اسے جہنم میں ڈالیں گے، اور وہ بہت برا ٹھکانا ہے"],[1299,"§حسنِ گفتار\nارشادِ باری تعالیٰ ہے : ﴿لَا خَيْرَ فِيْ كَثِيْرٍ مِّنْ نَّجْوٰىهُمْ﴾ ’’ان لوگوں کی بہت سی سرگوشیاں اچھی نہیں۔‘‘ یعنی لوگوں کا بہت سا کلام اچھا نہیں ہوتا﴿اِلَّا مَنْ اَمَرَ بِصَدَقَةٍ اَوْ مَعْرُوْفٍ اَوْ اِصْلَاحٍۭ بَيْنَ النَّاسِؕ﴾ ’’ہاں، (اس شخص کی بات اچھی ہو سکتی ہے) جو خیرات یا نیک بات یا لوگوں میں صلح کرنے کو کہے۔‘‘\nامام احمد رحمہ اللہ نے اُمِّ کلثوم بنت عُقبہ رضی اللہ عنہا کی روایت کو بیان کیا ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کویہ فرماتے ہوئے سنا:’’وہ شخص جھوٹا نہیں ہے جو لوگوں میں صلح کر ادے اور اچھی خبر منسوب کرے یا اچھی بات کہے۔ ‘‘ (نیز انہوں نے یہ بھی بیان کیا ہے کہ میں نے نہیں سنا کہ لوگ جو باتیں کرتے ہیں، آپ صلی اللہ علیہ وسلم نے ان میں سے تین کے سوا کسی اور بات کی رخصت دی ہو (اور وہ تین باتیں یہ ہیں :) (1)جنگ اور (2)لوگوں میں صلح کے بار ےمیں بات۔ (3)مرد کی اپنی بیوی سے بات اور بیوی کی اپنے شوہر سے بات۔) امام احمد رحمہ اللہ بیان کرتے ہیں کہ یہ ام کلثوم بنت عقبہ رضی اللہ عنہا ان مہاجر خواتین میں سے تھیں جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کے دست ِ مبارک پر بیعت کی تھی۔(مسند أحمد) اور امام ابن ماجہ رحمہ اللہ کے سوامحدثین رحمہم اللہ کی ایک جماعت نے بھی اس حدیث کو بیان کیا ہے۔ (صحیح البخاری)\nامام احمد رحمہ اللہ ہی نے ابودرداء رضی اللہ عنہ کی روایت کو بھی بیان کیا ہے وہ کہتے ہیں :رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا میں تمہیں ایک ایسا عمل نہ بتائوں جو درجے کے اعتبار سے نماز، روزے اور صدقے سے بھی افضل ہو ؟ صحابۂ کرام رضی اللہ عنہم نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم ! ضرور ارشاد فرمائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: وہ عمل لوگوں میں صلح کر ادینا ہے۔ اور فرمایا: لوگوں کے باہمی تعلقات کو خراب کر دینا تو ایک ایسا عمل ہے جو تباہ وبرباد کر دینے والا ہے۔ ‘‘(مسند أحمد)اس حدیث کو امام ابوداؤد اور ترمذی رحمہما اللہ نے بھی روایت کیا ہے۔ (سنن أبی داؤد: 4919 وجامع الترمذی: 2509 بعض الفاظ میں تقدیم و تاخیر ہے۔)اور امام ترمذی رحمہ اللہ نے اس حدیث کو حسن صحیح قرار دیا ہے۔ اسی لیے اللہ تعالیٰ نے فرمایا ہے : ﴿وَمَنْ يَّفْعَلْ ذٰلِكَ ابْتِغَآءَ مَرْضَاتِ اللّٰهِ﴾ ’’اور جو ایسے کام اللہ تعالیٰ کی خوشنودی حاصل کرنے کے لیے کرے گا۔‘‘یعنی اخلاص کے ساتھ اور اللہ تعالیٰ کے ہاں ثواب کی اُمید سے کرے گا۔ ﴿فَسَوْفَ نُؤْتِيْهِ اَجْرًا عَظِيْمًا۰۰۱۱۴﴾ ’’تو ہم اس کو بڑا ثواب دیں گے۔ ‘‘"],[1300,"§پیغمبر علیہ السلام کی مخالفت کرنے والے کی سزا\nارشادِ باری تعالیٰ ہے : ﴿وَمَنْ يُّشَاقِقِ الرَّسُوْلَ مِنْۢ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدٰى﴾ ’’اور جو شخص سیدھا راستہ معلوم ہونے کے بعد پیغمبر علیہ السلام کی مخالفت کرے۔ ‘‘ یعنی جو شخص اس شریعت کے راستے کے علاوہ جسے رسول اللہ صلی اللہ علیہ وسلم لے کر تشریف لائے ہیں، کسی اور رستے پر چلے تو وہ ایک طرف ہے اور شریعت دوسری طرف ہے، پھر اگر وہ قصد وارادے سے ایسا کر رہا ہو کہ حق اس کے سامنے ظاہر، واضح اور روشن ہو گیا ہو ﴿وَيَتَّبِعْ غَيْرَ سَبِيْلِ الْمُؤْمِنِيْنَ﴾ ’’اور مومنوں کے رستے کے سوا اور رستے پر چلے۔‘‘ اگر چہ یہ پہلی صفت کے ساتھ لازم و ملزوم ہی ہے لیکن مخالفت کبھی تو شارع کی نص کی ہوتی ہے اورکبھی اس بات کی جس پر یقینی طور پر اُمت ِ محمدیہ صلی اللہ علیہ وسلم کا اجماع ہو۔ اس لیے کہ اُمت کی فضیلت اور اس کے نبی صلی اللہ علیہ وسلم کی عظمت کے پیش نظر اللہ نے اس اُمت کو اس بات سے محفوظ رکھا ہے کہ کسی غلط بات پر اس کا اجماع ہو جیسا کہ بہت سی احادیث ِ صحیحہ سے یہ بات ثابت ہے۔ (دیکھیے : سنن أبی داؤد: 4253 و جامع الترمذی:2167)\nاور جو شخص رسول اللہ صلی اللہ علیہ وسلم کی مخالفت کرے اور مومنوں کے رستے کے سو اکسی اور راہ کو اختیار کرے تو اسے اللہ تعالیٰ نے سرزنش کرتے ہوئے فرمایا ہے :﴿نُوَلِّهٖ مَا تَوَلّٰى وَنُصْلِهٖ جَهَنَّمَؕ وَسَآءَتْ مَصِيْرًاࣖ۰۰۱۱۵﴾ ’’تو جدھر وہ پھرتا ہے ہم اسے ادھر ہی پھیر دیتے ہیں اور (قیامت کے دن) جہنم میں داخل کریں گے اور وہ بری جگہ ہے۔ ‘‘ یعنی جو شخص ایسے رستے پر چلتا ہے تو ہم اسے اس پر چلنے دیتے ہیں اور اسے مہلت دیتے ہوئے ایسے رستے کو اس کے لیے اچھا اور مزین کرکے پیش کرتے ہیں جیسا کہ اللہ تعالیٰ نے فرمایا ہے : ﴿فَذَرْنِيْ وَمَنْ يُّكَذِّبُ بِهٰذَا الْحَدِيْثِؕ سَنَسْتَدْرِجُهُمْ مِّنْ حَيْثُ لَا يَعْلَمُوْنَۙ۰۰۴۴﴾ (القلم:44) ’’لہٰذا چھوڑ دیجئے مجھے اور اس کو جو اس حدیث (قرآن) کو جھٹلاتا ہے۔ ہم ان کو آہستہ آہستہ ایسے طریق سے پکڑیں گے کہ ان کو خبر بھی نہ ہوگی۔ ‘‘"],[1301,"§کون سے خفیہ مشورے بہترہیں؟\nمنافق لوگ جو راتوں کو الگ بیٹھ کر مشورے کرتے ہیں۔ وہ بسااوقات بری باتیں ہی سوچتے ہیں، جو خیر سے خالی ہوتی ہیں۔ کیوں کہ بھلائی کی اور صاف ستھری سچی بات کو چھپانے کی ضرورت ہی نہیں ہوتی البتہ کچھ اُمورایسے ہیں جو چھپا کر کرنا بہتر ہوتے ہیں، مثلاً کسی کو صدقہ دے تو چھپا کر دے تاکہ لینے والا شرمندہ نہ ہو۔ یاصدقہ دینے کے متعلق الگ مشورہ کرنا بھی اچھاکام ہے۔ اسی طرح بھلائی کے کاموں اور بالخصوص لوگوں کے درمیان صلح کرانے کے متعلق اگر خفیہ مشورہ بھی کیا جائے تو بھی یہ ایک نیکی کا کام ہے لیکن افسوس ہے کہ یہ لوگ ان اُمور میں سے تو کسی بات کا مشورہ نہیں کرتے۔ وہ ایسے مشورے کرتے ہیں جن سے شرپیدا ہو اور دوسروں کو نقصان پہنچے۔ اور جو شخص مذکورہ بالا اُمور کے متعلق محض اللہ تعالیٰ کی رضا کے لیے مشورہ کرے تو یہ بڑے نیکی کے کام ہیں۔"],[1302,"§لوگوں میں اصلاح کے لیے اپنی طرف سے کوئی اچھی بات کہہ دینا جھوٹ نہیں\nچنانچہ آپ صلی اللہ علیہ وسلم نے ایک دفعہ صحابہ کرام رضی اللہ عنہم سے فرمایا :’’ کیا میں تمہیں ایسے کام کی خبرنہ دوں جو نماز، روزہ اور صدقہ سے بھی افضل ہے ؟ ‘‘ صحابہ رضی اللہ عنہم نے عرض کیا :’’بتائیے ‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا ’’دو شخصوں کے درمیان صلح کرانا۔ کیوں کہ دو آدمیوں کے درمیان فساد ڈالنا (دین کو) مونڈنے والا (برباد کرنے والا) کام ہے۔‘‘ (سنن ترمذی)نیز آپ صلی اللہ علیہ وسلم نے فرمایا۔ ’’لوگوں کے درمیان صلح کرانے کے لیے اگر کوئی شخص (اپنی طرف سے) کوئی اچھی بات کسی فریق کی طرف منسوب کر دے یا کوئی اچھی بات کہہ دے تو وہ جھوٹا نہیں ہے۔‘‘ (صحیح البخاری)"],[1303,"§رسو ل اللہ صلی اللہ علیہ وسلم کی مخالفت کی صورتیں\nربط مضمون کے لحاظ سے تو اس آیت کا خطاب اسی منافق سے ہے جس نے چوری کی تھی۔ جب رسول اللہ صلی اللہ علیہ وسلم نے وحی الٰہی کی بنا پر مذکورہ مقدمہ کا فیصلہ بے گناہ یہودی کے حق میں دے دیا۔ تو اس منافق کو سخت صدمہ ہوا۔ وہ مدینہ سے نکل کر اسلام اور رسول اللہ صلی اللہ علیہ وسلم کے دشمنوں کے پاس مکہ چلا گیا اور کھلم کھلا مخالفت پر اُتر آیا۔ لیکن حکم کے لحاظ سے یہ خطاب سب لوگوں کے لیے ہے جس میں مسلمان بھی شامل ہیں اور یہ حکم قیامت تک کے لیے ہے۔ یعنی جو شخص بھی رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم کے طریق زندگی کو چھوڑ کر کوئی دوسرا طریق اختیار کرے گا وہ گمراہ ہو جائے گا اور جس قدر زیادہ مخالفت کرے گا اسی قدر گمراہی میں بڑھتا چلا جائے گا۔ اس کی یہ ذہنی اور عملی مخالفت اسے جہنم میں پہنچا کے چھوڑےگی۔ اب اس مخالفت یا گمراہی کی کئی صورتیں ہیں۔ مثلاً: شرکیہ عقائد و اعمال اپنالے یا سنت کو چھوڑ کر بدعات میں جا پڑے یا سنت رسول صلی اللہ علیہ وسلم کو حجت ہی نہ سمجھے، یا کوئی نیا نبی بھی تسلیم کر لے یا ایسے بدعی عقائد اپنے مذہب میں شامل کرے جن کا اس دور میں وجود نہ تھا وغیرہ وغیرہ۔ غرض مخالفت اور گمراہی کی بے شمار اقسام ہیں لہٰذا اس معاملہ میںمسلمان کو انتہائی محتاط رہنا چاہیے۔"],[1304,"§اجماع صحابہ رضی اللہ عنہم حجت ہے\nاس جملہ سے معلوم ہوتا ہے کہ اجماع اُمت یا صحابہ کرام رضی اللہ عنہم کا کسی مسئلہ پر متفق ہوجانا من جملہ ادلہ شرعیہ ایک قابل حجت امر ہے اور اس اجماع کی مخالفت کرنے والا اور اجماع کو تسلیم نہ کرنے والا گناہ گار ہوتا ہے تاہم اس سلسلہ میں دوباتوں کو ذہن نشین رکھنا چاہیے۔ ایک یہ کہ صحابہ کرام رضی اللہ عنہم کے اجماع کے حجت ہونے میں تو کسی کو کلام نہیں لیکن ما بعد کے ادوار کا حجت ہونا بذات خود مختلف فیہ مسئلہ ہے اور راجح قول یہی ہے کہ ما بعد کا اجماع اُمت کے لیے قابل حجت نہیں ہے۔ اور دوسرا یہ کہ صحابہ رضی اللہ عنہم کا اجماع تو ثابت کیا جا سکتا ہے کیوں کہ ان کازمانہ بھی محدود اور علاقہ بھی محدود تھا۔ لیکن ما بعد کے ادوار میں اجماع اُمت کا ثابت کرنا ہی بہت مشکل ہے جب کہ اُمت اقصائے عالم میں پھیل چکی ہے اور علماء بھی ہر جگہ موجودہیں۔ دور ِ صحابہ رضی اللہ عنہم کے بعد جتنے مسائل کے متعلق یہ دعویٰ کیا گیا ہے کہ ان پر اُمت کا اجماع ہے، ان میں سے زیادہ ایسے ہیں کہ ان کو فی الواقع ثابت نہیں کیاجاسکتا۔\nاحادیث میں اعمال مذکورہ کی بڑی فضیلت آئی ہے۔ اللہ تعالیٰ کی راہ میں حلال کمائی سے ایک کھجور کے برابر صدقہ بھی احد پہاڑ ہو جائے گا۔ (صحیح البخاری) نیک بات کی بھی بڑی فضیلت ہے۔ اسی طرح رشتے داروں، دوستوں اور باہم ناراض دیگر لوگوں کے درمیان صلح کر ادینا، بہت بڑا عمل ہے۔ ایک حدیث میں اسے نفلی روزوں، نفلی نمازوں اور نفلی صدقات و خیرات سے بھی افضل بتلایا گیا ہے۔ فرمایا: (ابوداؤد، ترمذی ومسند احمد) حتی کہ صلح کرانے والے کو جھوٹ تک بولنے کی اجازت دے دی گئی تاکہ اسے ایک دوسرے کو قریب لانے کے لیے دروغ مصلحت آمیز کی ضرور ت پڑے تو وہ اس میں بھی تامل نہ کرے۔ (صحیح البخاری، صحیح مسلم و الترمذی، وابوداؤد) ’’وہ شخص جھوٹا نہیں ہے جو لوگوں کے درمیان صلح کرانے کے لیے اچھی بات پھیلاتا یا اچھی بات کرتا ہے۔ ‘‘\nہدایت کے واضح ہوجانے کے بعد رسول اللہ صلی اللہ علیہ وسلم کی مخالفت اور مومنین کا راستہ چھوڑ کر کسی اور راستے کی پیروی، دین اسلام سے خروج ہے جس پر یہاں جہنم کی وعید بیان فرمائی گئی ہے۔ مومنین سے مراد صحابہ کرام رضی اللہ عنہم ہیں جو دین اسلام کے اولین پیرو اور اس کی تعلیمات کا کامل نمونہ تھے۔ اور ان کے نزول کے وقت جن کے سوا کوئی گروہ مومنین موجود نہ تھا کہ وہ مراد ہو۔ اس لیے رسول اللہ صلی اللہ علیہ وسلم کی مخالفت اور غیر سبیل المومنین کا اتباع دونوں حقیقت میں ایک ہی چیز کا نام ہے۔ اس لیے صحابہ کرام رضی اللہ عنہم کے راستے اور منہاج سے انحراف بھی کفر و ضلال ہی ہے۔ بعض علماء نے سبیل المومنین سے مراد اجماع اُمت لیا یعنی اجماعت اُمت سے انحراف بھی کفر ہے۔ اجماع اُمت کا مطلب ہے کسی مسئلے میں اُمت کے تمام علماء، فقہاء کا اتفاق۔ یا کسی مسئلے پر صحابہ کرام رضی اللہ عنہم کا اتفاق یہ دونوںصورتیں اجماع اُمت کی ہیں اور دونوں کا انکار یا ان میں سے کسی ایک کا انکار کفر ہے۔ تاہم صحابہ کرام رضی اللہ عنہم کا اتفاق تو بہت سے مسائل میں ملتا ہے یعنی اجماع کی یہ صورت تو ملتی ہے۔ لیکن اجماع صحابہ رضی اللہ عنہم کے بعد کسی مسئلے میں پوری اُمت کے اجماع و اتفاق کے دعوے تو بہت سے مسائل میں کیے گئے ہیں لیکن فی الحقیقت ایسے اجماعی مسائل بہت ہی کم ہیں۔ جن میں فی الواقع اُمت کے تمام علماء و فقہاء کا اتفاق ہو۔ تاہم ایسے جو مسائل بھی ہیں، ان کا انکار بھی صحابہ رضی اللہ عنہم کے اجماع کے انکار کی طرح، کفر ہے۔ اس لیے کہ صحیح حدیث میں ہے :’’اللہ تعالیٰ میری اُمت کو گمراہی پر اکٹھا نہیں کرے گا اور جماعت پر اللہ تعالیٰ کا ہاتھ ہے۔ ‘‘(صحیح، ترمذی)\nعام طو رپرسرگوشی کو بہتر قرار نہیں دیا گیا ہے چنانچہ قرآن پاک میں ایک دوسرے مقام پر سرگوشی کو گناہ کا مظنہ قرار دیا گیا ہے۔ اسی آیت میں حکم دیا گیا ہے کہ نیک کاموں اور پرہیز گاری کے معاملات میں سرگوشی کرنا مستحسن ہے۔ آیت مبارکہ ملاحظہ فرمائیں۔ ﴿يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْۤا اِذَا تَنَاجَيْتُمْ فَلَا تَتَنَاجَوْا بِالْاِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُوْلِ وَتَنَاجَوْا بِالْبِرِّ وَالتَّقْوٰىؕ وَاتَّقُوا اللّٰهَ الَّذِيْۤ اِلَيْهِ تُحْشَرُوْنَ۰۰۹﴾ (المجادلۃ:9) ’’ایمان والو! جب تم سرگوشی کرو تو گناہ، زیادتی اور اللہ تعالیٰ کے رسول صلی اللہ علیہ وسلم کی نافرمانی کی سرگوشی نہ کرو اور نیکی پرہیز گاری کی سرگوشی کرو اور اللہ تعالیٰ کا خوف رکھو جس کی جانب تم اکٹھے کیے جائوگے۔‘‘ حقیقت میں یہ عادت دیکھی گئی ہے کہ اگر کام اچھا ہے تو اس کے بارے میں گفتگو کھلی مجلس میں کی جاتی ہے جب کہ جس کام میں شر بلکہ گناہ کا پہلو بظاہر دکھائی دیتا ہے اس کے بارے میں مشورہ تنہائی میں ہوتا ہے ایک اثر میں گناہ کی تعریف یہ ہے کہ اس کے احساس سے دل میں کھٹکا رونما ہو اور دل میں یہ خیال چھاجاتا ہے کہ کہیں لوگوں کو اس کا علم نہ ہو جائے۔ البتہ صدقہ و خیرات کے کاموں میں یا دیگر معروف کاموں میں اسی طرح لوگوں میں اصلاح کے انداز کو اُجاگر کرنے کے لیے سرگوشیاں کرنا نہایت بہتر ہے بلکہ اللہ تعالیٰ کی رضا کے حصول کے لیے سرگوشی کرنا نہایت بابرکت اور ثواب عظیم کا کام ہے۔"]])